test('native Copy Path and Copy Relative Path retain citation filename suffixes', async () => {
  const { linkTarget, resolveLink, relativePath, nativePath } = await import('./transcript.js');
  const copied: string[] = [];
  const root = process.platform === 'win32' ? 'C:/workspace' : '/workspace';
  const outside = process.platform === 'win32' ? 'C:/Downloads' : '/Downloads';
  const host = {
    workspace: { workspaceFolders: [{ uri: { fsPath: root } }] },
    env: {
      clipboard: {
        writeText: async (text: string) => {
          copied.push(text);
        },
      },
    },
    window: { setStatusBarMessage() {} },
  };
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const compiled = ts.transpileModule(declarationSource(extensionSource, 'copyPath'), {
    compilerOptions: { target: ts.ScriptTarget.ES2022 },
  }).outputText;
  const copy = new Function(
    'vscode',
    'fs',
    'pathFrom',
    'linkTarget',
    'resolveLink',
    'relativePath',
    'nativePath',
    'nativeCitationPath',
    `${compiled}\nreturn copyPath;`,
  )(host, fs, () => null, linkTarget, resolveLink, relativePath, nativePath, nativeCitationPath);
  for (const folder of [root, outside]) {
    for (const suffix of ['#L10', ':10', '%20']) {
      const file = `${folder}/report.csv${suffix}`;
      for (const relative of [false, true]) {
        await copy({ link: file, destination: { kind: 'fileCitation', path: file } }, relative);
        assert.equal(copied.at(-1), nativePath(relative ? relativePath(file, [root]) : file));
        await copy({ link: file }, relative);
        const ordinary = linkTarget(file)!;
        assert.equal(copied.at(-1), nativePath(relative ? relativePath(ordinary, [root]) : ordinary));
      }
    }
  }
});

test('response citation presses open external literal files without workspace or snapshot routing', async () => {
  const { linkCandidates } = await import('./transcript.js');
  const opened: Array<{ path: string; options: Record<string, unknown> }> = [];
  const commands: unknown[][] = [];
  const notices: string[] = [];
  const checked: string[] = [];
  let kind = 1;
  let missing = false;
  const root = process.platform === 'win32' ? 'C:/workspace' : '/workspace';
  const outside = process.platform === 'win32' ? 'C:/Downloads' : '/Downloads';
  const uri = (file: string) => ({ scheme: 'file', fsPath: file, toString: () => `file://${file}` });
  const host = {
    Uri: { file: uri, joinPath: (base: { fsPath: string }, file: string) => uri(path.join(base.fsPath, file)) },
    FileType: { Directory: 2, File: 1 },
    workspace: {
      workspaceFolders: [{ uri: uri(root) }],
      fs: {
        stat: async (file: { fsPath: string }) => {
          checked.push(file.fsPath);
          if (missing) throw new Error('missing');
          return { type: kind };
        },
      },
    },
    env: {
      openExternal: async () => {
        throw new Error('unexpected external URL');
      },
    },
    commands: {
      executeCommand: async (...args: unknown[]) => {
        commands.push(args);
      },
    },
    Range: class {
      constructor(
        public from: number,
        public start: number,
        public to: number,
        public end: number,
      ) {}
    },
    window: {
      showInformationMessage: (message: string) => notices.push(message),
      showTextDocument: async (file: { fsPath: string }, options: Record<string, unknown>) => {
        opened.push({ path: file.fsPath, options });
      },
    },
  };
  const source = ts.transpileModule(declarationSource(panelHostSource, 'openLink'), {
    compilerOptions: { target: ts.ScriptTarget.ES2022 },
  }).outputText;
  const open = new Function(
    'vscode',
    'path',
    'normalizeFsPath',
    'linkCandidates',
    'nativeCitationPath',
    'linkTargetIsImage',
    'linkTargetIsHtml',
    'linkTargetIsMarkdown',
    `${source}\nreturn openLink;`,
  )(
    host,
    path,
    (file: string) => file.replace(/\\/g, '/').toLowerCase(),
    linkCandidates,
    nativeCitationPath,
    (file: string) => file.endsWith('.png'),
    (file: string) => file.endsWith('.html'),
    (file: string) => file.endsWith('.md'),
  );
  for (const name of ['one%20.csv', 'one .csv', 'one#L10', 'one:10', 'Case.csv', 'case.csv']) {
    const file = `${outside}/${name}`;
    await open(file, 2, true);
    assert.deepEqual(opened.at(-1), { path: file, options: { selection: undefined, preview: true, viewColumn: 2 } });
    assert.equal(checked.at(-1), file);
  }
  assert.equal(commands.length, 0);
  await open(`${outside}/file.csv`, 2);
  assert.equal(opened.length, 7);
  assert.equal(opened.at(-1)!.path, path.normalize(`${outside}/file.csv`));
  assert.equal(notices.length, 0);
  await open(`${root}/file.csv#L10-L12`, 1);
  assert.equal(opened.at(-1)!.path, path.resolve(root, 'file.csv'));
  assert.equal((opened.at(-1)!.options.selection as { from: number }).from, 9);
  for (const file of [
    'relative.csv',
    'https://example.com',
    'file:///tmp/file',
    process.platform === 'win32' ? '/foreign/file' : 'C:/foreign/file',
  ]) {
    const count = checked.length;
    await open(file, 2, true);
    assert.equal(checked.length, count, file);
  }
  kind = 2;
  await open(`${outside}/folder`, 2, true);
  assert.match(notices.pop()!, /is a folder/);
  assert.equal(commands.length, 0);
  kind = 1;
  missing = true;
  await open(`${outside}/missing.csv`, 2, true);
  assert.equal(notices.pop(), `Arc: no file at ${outside}/missing.csv.`);
  missing = false;
  for (const [name, command] of [
    ['picture.png', 'vscode.open'],
    ['page.html', 'workbench.action.browser.open'],
    ['guide.md', 'vscode.openWith'],
  ]) {
    await open(`${outside}/${name}`, 2, true);
    assert.equal(commands.at(-1)![0], command);
  }
  const routed: unknown[][] = [];
  const handler = new Function(
    'openLink',
    'vscode',
    'parseSessionLink',
    `return async function(msg){${handlerBody(panelHostSource, 'openLink')}}`,
  )(
    (...args: unknown[]) => routed.push(args),
    { ViewColumn: { Beside: 2 } },
    () => ({ kind: 'other' }),
  );
  await handler.call(
    { column: () => 1 },
    { destination: { kind: 'fileCitation', path: `${outside}/one%20.csv#L10` }, beside: true },
  );
  assert.deepEqual(routed, [[`${outside}/one%20.csv#L10`, 2, true]]);
});

test('clicked local links open outside workspace folders through their existing editor routes', async () => {
  const { linkCandidates } = await import('./transcript.js');
  const source = ts.transpileModule(declarationSource(panelHostSource, 'openLink'), {
    compilerOptions: { target: ts.ScriptTarget.ES2022 },
  }).outputText;
  for (const [platform, roots, skill, text, parent] of [
    [
      'win32',
      ['C:/Workspace/App', 'C:/Workspace/Lib'],
      'C:/Users/Reader/Notes/.claude/skills/arc-session-digest/SKILL.md',
      'D:/Notes/Mixed.ts',
      'C:/Workspace/Outside.ts',
    ],
    [
      'darwin',
      ['/Users/Reader/Workspace/App', '/Users/Reader/Workspace/Lib'],
      '/Users/Reader/Notes/SKILL.md',
      '/Users/Reader/Notes/Mixed.ts',
      '/Users/Reader/Workspace/Outside.ts',
    ],
    [
      'linux',
      ['/home/reader/Workspace/App', '/home/reader/Workspace/Lib'],
      '/home/reader/Notes/SKILL.md',
      '/home/reader/Notes/Mixed.ts',
      '/home/reader/Workspace/Outside.ts',
    ],
  ] as const) {
    const paths = platform === 'win32' ? path.win32 : path.posix;
    const uri = (file: string) => ({ scheme: 'file', fsPath: file, toString: () => `file://${file}` });
    const commands: unknown[][] = [];
    const opened: Array<{ file: ReturnType<typeof uri>; options: Record<string, unknown> }> = [];
    const notices: string[] = [];
    const checked: string[] = [];
    const external: string[] = [];
    const existing = new Map<string, number>();
    let previewFails = false;
    const host = {
      Uri: {
        file: uri,
        parse: (href: string) => href,
        joinPath: (base: ReturnType<typeof uri>, file: string) => uri(paths.join(base.fsPath, file)),
      },
      FileType: { Directory: 2, File: 1 },
      workspace: {
        workspaceFolders: roots.map((root) => ({ uri: uri(root) })),
        fs: {
          stat: async (file: ReturnType<typeof uri>) => {
            checked.push(file.fsPath);
            const type = existing.get(file.fsPath);
            if (type === undefined) throw new Error('missing');
            return { type };
          },
        },
      },
      env: {
        openExternal: async (href: string) => {
          external.push(href);
        },
      },
      commands: {
        executeCommand: async (...args: unknown[]) => {
          commands.push(args);
          if (previewFails && args[0] === 'vscode.openWith') throw new Error('preview unavailable');
        },
      },
      Range: class {
        constructor(
          public from: number,
          public start: number,
          public to: number,
          public end: number,
        ) {}
      },
      window: {
        showInformationMessage: (message: string) => notices.push(message),
        showTextDocument: async (file: ReturnType<typeof uri>, options: Record<string, unknown>) => {
          opened.push({ file, options });
        },
      },
    };
    const open = new Function(
      'vscode',
      'path',
      'normalizeFsPath',
      'linkCandidates',
      'nativeCitationPath',
      'linkTargetIsImage',
      'linkTargetIsHtml',
      'linkTargetIsMarkdown',
      `${source}\nreturn openLink;`,
    )(
      host,
      paths,
      (file: string) => file.replace(/\\/g, '/').toLowerCase(),
      (target: string, folders: string[]) => linkCandidates(target, folders, platform),
      nativeCitationPath,
      (file: string) => /\.png$/i.test(file),
      (file: string) => /\.html?$/i.test(file),
      (file: string) => /\.(md|markdown)$/i.test(file),
    );
    const skillPath = paths.normalize(skill);
    existing.set(skillPath, 1);
    await open(skill, 2);
    assert.equal(commands.at(-1)?.[0], 'vscode.openWith', `${platform}: outside Markdown was blocked`);
    assert.equal((commands.at(-1)![1] as ReturnType<typeof uri>).fsPath, skillPath);
    assert.equal((commands.at(-1)![1] as ReturnType<typeof uri>).scheme, 'file');
    assert.deepEqual(commands.at(-1)!.slice(2), ['vscode.markdown.preview.editor', 2]);
    assert.deepEqual(checked, [skillPath]);
    assert.deepEqual(notices, []);
    if (platform === 'win32') {
      await open(skill.replace(/\//g, '\\'), 1);
      assert.equal((commands.at(-1)![1] as ReturnType<typeof uri>).fsPath, skillPath);
      assert.equal(commands.at(-1)![3], 1);
    }
    existing.set(paths.normalize(text), 1);
    for (const [suffix, column, from, to] of [
      ['#L42-L51', 2, 41, 50],
      [':42', 1, 41, 41],
    ] as const) {
      await open(text + suffix, column);
      assert.equal(opened.at(-1)!.file.scheme, 'file');
      assert.equal(opened.at(-1)!.file.fsPath, paths.normalize(text));
      assert.equal(opened.at(-1)!.options.viewColumn, column);
      assert.deepEqual({ ...(opened.at(-1)!.options.selection as object) }, { from, start: 0, to, end: 0 });
    }
    existing.set(paths.normalize(parent), 1);
    await open('../Outside.ts', 2);
    assert.equal(opened.at(-1)!.file.fsPath, paths.normalize(parent));
    for (const name of ['Inside.ts', 'store.ts', 'command', 'file']) existing.set(paths.join(roots[0], name), 1);
    await open('Inside.ts', 1);
    assert.equal(opened.at(-1)!.file.fsPath, paths.join(roots[0], 'Inside.ts'));
    await open(paths.join(roots[0], 'Inside.ts'), 2);
    assert.equal(opened.at(-1)!.file.fsPath, paths.join(roots[0], 'Inside.ts'));
    for (const name of ['store.ts:42', 'store.ts:42:7', 'command:42', 'file:42']) {
      await open(name, 1);
      assert.equal(opened.at(-1)!.file.fsPath, paths.join(roots[0], name.split(':')[0]));
      assert.equal(opened.at(-1)!.file.scheme, 'file');
      assert.deepEqual({ ...(opened.at(-1)!.options.selection as object) }, { from: 41, start: 0, to: 41, end: 0 });
    }
    const lib = paths.join(roots[1], 'Only.ts');
    existing.set(lib, 1);
    checked.length = 0;
    await open('Only.ts', 2);
    assert.deepEqual(checked, [paths.join(roots[0], 'Only.ts'), lib]);
    assert.equal(opened.at(-1)!.file.fsPath, lib);
    for (const [name, command] of [
      ['Folder.html', 'revealInExplorer'],
      ['image.png', 'vscode.open'],
      ['page.html', 'workbench.action.browser.open'],
    ] as const) {
      const file = paths.join(paths.dirname(text), name);
      existing.set(file, name === 'Folder.html' ? 2 : 1);
      await open(file, 2);
      assert.equal(commands.at(-1)![0], command);
      assert.equal(
        command === 'workbench.action.browser.open'
          ? commands.at(-1)![1]
          : (commands.at(-1)![1] as ReturnType<typeof uri>).fsPath,
        command === 'workbench.action.browser.open' ? `file://${file}` : file,
      );
    }
    const beforePreview = opened.length;
    previewFails = true;
    await open(skill, 2);
    assert.equal(opened.length, beforePreview);
    assert.equal(notices.pop(), `Arc: VS Code did not open ${skillPath} in Markdown Preview.`);
    previewFails = false;
    await open(text + '.missing', 1);
    assert.equal(notices.pop(), `Arc: no file at ${text}.missing.`);
    for (const href of ['command:workbench.action.files.openFile', 'file:///tmp/file', 'mailto:reader@example.com']) {
      checked.length = 0;
      const commandCount = commands.length;
      await open(href, 1);
      assert.deepEqual(
        checked,
        roots.map((root) => paths.join(root, href)),
      );
      assert.equal(commands.length, commandCount);
      assert.equal(notices.pop(), `Arc: no file at ${href}.`);
    }
    checked.length = 0;
    for (const href of ['http://example.com/a.md', 'HTTPS://example.com/a.md']) await open(href, 2);
    assert.deepEqual(external, ['http://example.com/a.md', 'HTTPS://example.com/a.md']);
    assert.deepEqual(checked, []);
    host.workspace.workspaceFolders = [];
    await open(skill, 2);
    assert.equal((commands.at(-1)![1] as ReturnType<typeof uri>).fsPath, skillPath);
    checked.length = 0;
    await open('missing.ts', 1);
    assert.deepEqual(checked, []);
    assert.equal(notices.pop(), 'Arc: no file at missing.ts.');
  }
});

test('recorded, restored and live response citations share summary, earlier-answer and Activity rendering', () => {
  const file = process.platform === 'win32' ? 'C:/Downloads/source.csv' : '/Downloads/source.csv';
  const source = `:codex-file-citation{path='${file}' purpose=source}`;
  const original = turn({
    summary: source,
    answers: [{ text: 'Earlier ' + source, at: 2, stepsBefore: 0 }],
    updates: [
      { sourceId: 'commentary', kind: 'commentary', text: source, at: 3, stepsBefore: 0, status: 'done' },
      { sourceId: 'reasoning', kind: 'reasoning', text: source, at: 4, stepsBefore: 0, status: 'done' },
    ],
  });
  const provider: any = Object.assign(Object.create(PanelProvider.prototype), {
    live: {},
    turnsByKey: new Map(),
    dispatchedCostsForTurn: () => [],
    cardCacheExpiryWarning: () => null,
    withActivity: (turn: unknown) => turn,
  });
  for (const [recorded, latest] of [
    [original, false],
    [JSON.parse(JSON.stringify(original)), false],
    [original, true],
  ] as const) {
    const card = provider.renderTurnCard(
      recorded,
      latest,
      'Source session',
      5,
      [],
      new Set(),
      new Map(),
      new Map(),
      () => ({}),
      () => ({}),
    );
    const surfaces = [
      card.summaryHtml,
      ...card.earlierAnswers.map((answer: any) => answer.summaryHtml),
      ...card.saidMessages.map((message: any) => message.summaryHtml),
      ...card.activity.filter((row: any) => row.kind === 'message').map((row: any) => row.summaryHtml),
    ];
    assert.ok(surfaces.length >= 4);
    for (const html of surfaces) assert.ok(html.includes(`data-link="${file}" data-link-kind="file-citation"`), html);
    assert.equal(recorded.summary, source);
  }
});

test('response session targets require a unique scoped accepted identity without provisional drafts', () => {
  const inside = (cwd: string) => cwd === 'project';
  const source = { sessionId: 'saved-id', agent: 'claude', cwd: 'project' };
  const other = { ...source, agent: 'codex' };
  assert.equal(resolveResponseSession('saved-id', [source], [source], inside).kind, 'resolved');
  assert.equal(resolveResponseSession('saved-id', [source], [other], inside).kind, 'ambiguous');
  assert.equal(resolveResponseSession('saved-id', null, [source], inside).kind, 'resolved');
  assert.equal(resolveResponseSession('saved-id', null, [], inside).kind, 'loading');
  assert.equal(resolveResponseSession('saved-id', [], [{ ...source, cwd: 'elsewhere' }], inside).kind, 'missing');
  assert.equal(resolveResponseSession('saved-id', [], [{ ...source, cwd: null }], inside).kind, 'missing');
  assert.equal(resolveResponseSession('short', [source], [], inside).kind, 'missing');
  assert.equal(
    resolveResponseSession('draft:provisional', [{ ...source, sessionId: 'draft:provisional' }], [], inside).kind,
    'missing',
  );
  assert.equal(pendingResponseSessionAdmitted(source, [other]), false);
  assert.equal(pendingResponseSessionAdmitted(source, [source]), true);
});

test('response session anchor masks suppress inherited turn, selection, comment and copy menus', () => {
  const entries = manifestMenu(manifest);
  for (const arcSelection of [true, false]) {
    const inherited = {
      webviewSection: 'arcTurnReadSummary',
      session: 'source',
      key: 'source:1',
      arcTurn: true,
      arcComments: true,
      arcCopyLink: true,
      arcSelection,
    };
    assert.ok(menuGroups(entries, inherited).flat().length > 0);
    assert.deepEqual(menuGroups(entries, { ...inherited, ...sessionLinkContext('arc-session:saved-id') }).flat(), []);
  }
});

test('response session navigation releases only its invoking clear route and retains rejected state', async () => {
  const first = { active: () => true };
  const second = { active: () => false };
  const outcomes: string[] = [];
  const provider: any = Object.assign(Object.create(PanelProvider.prototype), {
    healthPanel: () => ({ id: 1 }),
    health: { begin: () => 1, settle: (_action: number, outcome: string) => outcomes.push(outcome) },
    readyHosts: new Set([first, second]),
    repositoryScope: { snapshot: () => ({ ready: true, roots: ['project'] }) },
    folders: () => ['project'],
    authoritativeCatalogScope: JSON.stringify(['project']),
    authoritativeCatalog: [{ sessionId: 'source', agent: 'claude', cwd: 'project' }],
    awaitingSessionRecords: {},
    sessionAliases: new Map([['draft:old', { actual: 'source', expiresAt: Date.now() + 60000 }]]),
    clearRoutes: new Map([
      [
        'source',
        {
          successor: 'successor',
          hosts: new Map([
            [first, 7],
            [second, 8],
          ]),
        },
      ],
    ]),
    hostSessions: new Map([
      [first, 'reader'],
      [second, 'successor'],
    ]),
    newDrafts: { reader: { text: 'unsent' } },
    runningNow: new Set(['claude:source']),
    trail: visitPlace(emptyTrail(), 'reader'),
    show(session: string, host: { active: () => boolean }) {
      this.hostSessions.set(host, session);
    },
  });
  const draft = provider.newDrafts.reader;
  const trail = provider.trail;
  const original = vscode.window.setStatusBarMessage;
  const notices: string[] = [];
  Object.assign(vscode.window, {
    setStatusBarMessage: (message: string) => {
      notices.push(message);
    },
  });
  try {
    for (const session of ['missing', 'draft:unadopted'])
      await provider.onMessage({ type: 'showSession', session, responseLink: true }, first);
    assert.equal(provider.hostSessions.get(first), 'reader');
    assert.equal(provider.clearRoutes.get('source').hosts.size, 2);
    assert.equal(notices.length, 2);
    assert.deepEqual(outcomes, ['rejected', 'rejected']);
    const accepted = provider.authoritativeCatalog;
    provider.authoritativeCatalog = null;
    await provider.onMessage({ type: 'showSession', session: 'source', responseLink: true }, first);
    assert.match(notices.at(-1)!, /loading/);
    assert.equal(outcomes.at(-1), 'rejected');
    assert.equal(provider.clearRoutes.get('source').hosts.size, 2);
    provider.awaitingSessionRecords = { source: { ...accepted[0], createdAt: 1 } };
    provider.authoritativeCatalogScope = 'stale-scope';
    provider.authoritativeCatalog = [{ ...accepted[0], agent: 'codex' }];
    await provider.onMessage({ type: 'showSession', session: 'source', responseLink: true }, first);
    assert.equal(provider.hostSessions.get(first), 'source');
    provider.clearRoutes.get('source').hosts.set(first, 7);
    provider.hostSessions.set(first, 'reader');
    provider.authoritativeCatalogScope = JSON.stringify(['project']);
    await provider.onMessage({ type: 'showSession', session: 'source', responseLink: true }, first);
    assert.match(notices.at(-1)!, /more than one/);
    assert.equal(outcomes.at(-1), 'rejected');
    assert.equal(provider.hostSessions.get(first), 'reader');
    assert.equal(provider.clearRoutes.get('source').hosts.size, 2);
    provider.authoritativeCatalog = accepted;
    provider.awaitingSessionRecords = {};
    await provider.onMessage({ type: 'showSession', session: 'draft:old', responseLink: true }, first);
    assert.equal(provider.hostSessions.get(first), 'source');
    assert.equal(provider.hostSessions.get(second), 'successor');
    assert.deepEqual([...provider.clearRoutes.get('source').hosts.keys()], [second]);
    await provider.onMessage({ type: 'showSession', session: 'source' }, second);
    assert.equal(provider.hostSessions.get(second), 'successor');
    await provider.onMessage({ type: 'showSession', session: 'source', responseLink: true }, second);
    assert.equal(provider.clearRoutes.size, 0);
    assert.equal(provider.panelSession('source', first), 'source');
    assert.equal(provider.newDrafts.reader, draft);
    assert.equal(provider.trail, trail);
    assert.equal(provider.runningNow.has('claude:source'), true);
  } finally {
    Object.assign(vscode.window, { setStatusBarMessage: original });
  }
});
import type { TurnOutcome } from './transcript';
