test('the panel persists an owned response speed and omits unowned or foreign completions', () => {
  const saves: Array<{ key: string; rates: unknown }> = [];
  const rate = {
    sessionId: 'speed-session',
    responseId: 'response',
    model: 'claude-opus-5',
    output: 84,
    milliseconds: 10000,
  };
  const provider: any = Object.assign(Object.create(PanelProvider.prototype), {
    live: { 'speed-session': [{ kind: 'prompt', at: 1000, turnId: 1 }] },
    responseRates: [],
    pendingResponseOwners: new Map(),
    showing: null,
    memento: {
      update: async (key: string, rates: unknown) => {
        saves.push({ key, rates });
      },
    },
  });
  provider.noteResponseRate('speed-session', rate, 2);
  provider.noteResponseRate('foreign', rate, 1);
  assert.equal(saves.length, 0);
  provider.noteResponseRate('speed-session', rate, 1);
  assert.equal(saves.length, 1);
  assert.equal(saves[0].key, 'arc.responseRates.v1');
  assert.deepEqual(
    responseRateForTurn(
      { sessionId: 'speed-session', model: rate.model, responseIds: ['response'], interrupted: false },
      savedResponseRates(JSON.parse(JSON.stringify(saves[0].rates))),
    ),
    { output: 84, milliseconds: 10000 },
  );
});

test('Claude response speed persists after a running prompt reconciles to its recorded turn', () => {
  const press = {
    ...livePress({ sessionId: 'speed-session', agent: 'claude' }),
    at: 1000,
    ran: true,
    started: true,
    turnId: 1,
  };
  const recorded = turn({
    sessionId: press.sessionId,
    agent: 'claude',
    startedAt: press.at,
    model: 'claude-opus-5',
    responseIds: ['first', 'second'],
  });
  const fixture = liveProviderFixture(press, recorded);
  const provider = fixture.provider as any;
  const saves: unknown[] = [];
  provider.responseRates = [];
  provider.memento = {
    update: async (_key: string, rates: unknown) => {
      saves.push(rates);
    },
  };
  provider.completeSelectedWindow = () => Promise.resolve();
  provider.running.add('claude:' + press.sessionId);
  const rate = {
    sessionId: press.sessionId,
    responseId: 'first',
    model: recorded.model!,
    output: 84,
    milliseconds: 10000,
  };
  assert.equal(fixture.call.dropSpentPresses(), true);
  assert.equal(provider.live[press.sessionId], undefined);
  provider.noteResponseRate(press.sessionId, rate, 99);
  provider.noteResponseRate('foreign', { ...rate, sessionId: 'foreign' }, press.turnId);
  assert.equal(saves.length, 0);
  provider.noteResponseRate(press.sessionId, rate, press.turnId);
  provider.noteResponseRate(press.sessionId, { ...rate, responseId: 'second', output: 168 }, press.turnId);
  assert.equal(saves.length, 2);
  const reloaded = savedResponseRates(JSON.parse(JSON.stringify(saves.at(-1))));
  assert.deepEqual(responseRateForTurn(recorded, reloaded), { output: 252, milliseconds: 20000 });
  provider.noteResponseEnded(press.sessionId, { status: 'ok' }, press.turnId);
  provider.noteResponseRate(press.sessionId, { ...rate, responseId: 'late' }, press.turnId);
  assert.equal(saves.length, 2);
});

// Catches a final reply whose saved callback is lost after a panel refresh retires the prompt card, because the
// selected window already shows the recorded turn. Every admitted Claude request then failed after a successful turn.
// The wire lines follow the order a Claude CLI turn sends: tool use, tool result, final text, end of turn, result.
test('a Claude self-compaction request compacts once after its turn when the selected window already shows that turn', async () => {
  const window = 'b'.repeat(24);
  const requestId = window + ':aaaaaaaa-1111-2222-3333-444444444444';
  const payload = { requestId, window, self: true, afterTurn: true };
  const literal = `arc compact request --self --after-turn --request-id ${requestId} --window ${window} --json`;
  const session = 'compact-session';
  const press = {
    ...livePress({ sessionId: session, agent: 'claude' }),
    at: 1000,
    ran: true,
    started: true,
    turnId: 7,
  };
  const fixture = liveProviderFixture(press, turn({ sessionId: session, agent: 'claude', startedAt: press.at }));
  const provider = fixture.provider as any;
  provider.completeSelectedWindow = () => Promise.resolve();
  provider.running.add('claude:' + session);
  const state = {
    sessionId: session,
    busy: true,
    asks: [] as unknown[],
    ready: true,
    exited: false,
  };
  let writes = 0;
  const child: CompactChild = {
    key: 'child',
    agent: 'claude',
    state: () => state,
    compactionUnresolved: () => false,
    compact: async (beforeWrite) => {
      beforeWrite();
      writes++;
    },
  };
  const owner = new CompactHost<CompactChild>(window, {
    find: () => child,
    withActivity: async (_child, work) => {
      await work(child);
      return undefined;
    },
    readerWork: () => 'none',
  });
  // Routes wire events as extension.ts does while turn 7 is the one open turn.
  const wire = new ClaudeWire({
    send() {},
    sessionId: session,
    emit: (event) => {
      if (event.kind === 'native') owner.native(child, event.event, 7);
      if (event.kind === 'text')
        provider.noteCompletedReply(session, event.text, event.sourceId, 7, () => owner.replyRetained(child, 7));
      if (event.kind === 'turnEnd') {
        provider.noteResponseEnded(session, event.outcome, 7);
        owner.turnEnded(child);
      }
    },
  });
  owner.submitted(child, 7);
  await wire.prompt('Save the handoff, then compact this session.');
  const send = (line: Record<string, unknown>) =>
    wire.receive(
      JSON.stringify({
        session_id: session,
        parent_tool_use_id: null,
        ...line,
      }),
    );
  const stream = (event: Record<string, unknown>) => send({ type: 'stream_event', event });
  const input = {
    command: literal,
    description: 'Request owner after this turn',
  };
  const tool = {
    type: 'tool_use',
    id: 'toolu_compact',
    name: 'Bash',
    input,
    caller: { type: 'direct' },
  };
  stream({
    type: 'message_start',
    message: { id: 'msg_tool', role: 'assistant', content: [] },
  });
  stream({
    type: 'content_block_start',
    index: 0,
    content_block: { ...tool, input: {} },
  });
  stream({
    type: 'content_block_delta',
    index: 0,
    delta: { type: 'input_json_delta', partial_json: JSON.stringify(input) },
  });
  send({
    type: 'assistant',
    uuid: 'tool-envelope',
    message: { id: 'msg_tool', role: 'assistant', content: [tool] },
  });
  stream({ type: 'content_block_stop', index: 0 });
  stream({ type: 'message_delta', delta: { stop_reason: 'tool_use' } });
  stream({ type: 'message_stop' });
  assert.deepEqual(owner.handle({ method: 'compact-ready', params: payload }), {
    ready: true,
  });
  assert.equal(
    (
      owner.handle({ method: 'compact-request', params: payload }) as {
        state: string;
      }
    ).state,
    'queued',
  );
  // A refresh shows the recorded turn in the selected window and retires the prompt card.
  assert.equal(fixture.call.dropSpentPresses(), true);
  assert.equal(provider.live[session], undefined);
  send({
    type: 'user',
    message: {
      role: 'user',
      content: [
        {
          tool_use_id: 'toolu_compact',
          type: 'tool_result',
          content: 'queued',
          is_error: false,
        },
      ],
    },
    tool_use_result: { stdout: 'queued', stderr: '', interrupted: false },
  });
  send({ type: 'system', subtype: 'status', status: 'requesting' });
  const reply = 'The handoff is saved. Compaction is queued.';
  stream({
    type: 'message_start',
    message: { id: 'msg_final', role: 'assistant', content: [] },
  });
  stream({
    type: 'content_block_start',
    index: 0,
    content_block: { type: 'text', text: '' },
  });
  stream({
    type: 'content_block_delta',
    index: 0,
    delta: { type: 'text_delta', text: reply },
  });
  send({
    type: 'assistant',
    uuid: 'final',
    message: {
      id: 'msg_final',
      role: 'assistant',
      content: [{ type: 'text', text: reply }],
    },
  });
  stream({ type: 'content_block_stop', index: 0 });
  stream({ type: 'message_delta', delta: { stop_reason: 'end_turn' } });
  stream({ type: 'message_stop' });
  send({
    type: 'result',
    subtype: 'success',
    is_error: false,
    stop_reason: 'end_turn',
    terminal_reason: 'completed',
    num_turns: 2,
    result: reply,
    uuid: 'root-result',
    result_index: 0,
  });
  send({ type: 'system', subtype: 'session_state_changed', state: 'idle' });
  const status = () =>
    owner.handle({ method: 'compact-status', params: { requestId } }) as {
      state: string;
      reason: string;
    };
  assert.equal(status().state, 'queued', status().reason);
  assert.deepEqual(
    owner.requests.deliverable(session).map(({ id }) => id),
    [requestId],
  );
  state.busy = false;
  await owner.drain(session);
  assert.equal(writes, 1);
  assert.equal(status().state, 'uncertain');
  wire.close('finished');
});

test('the host reads closed child work once per file version and never reads open child work', () => {
  const start = panelHostSource.indexOf('private liveOpenChildren(');
  const source = memberFrom(panelHostSource, start).replace('private liveOpenChildren(', 'function liveOpenChildren(');
  const compiled = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022 } }).outputText;
  const now = Date.parse('2026-10-03T03:15:00Z');
  const close = now - 120_000;
  const reader = vi.fn<() => number>(() => close - 28);
  class WorkCache extends ClaudeChildWorkCache {
    override read(file: string, version: string): number | undefined {
      return super.read(file, version, reader);
    }
  }
  const read = new Function(
    'liveTimelineChildren',
    'ClaudeChildWorkCache',
    'runningSessionsSince',
    `${compiled}\nreturn liveOpenChildren;`,
  )(liveTimelineChildren, WorkCache, () => new Map());
  let version = 'v1';
  const outcome = {
    finished: true,
    error: false,
    interrupted: false,
    endedAt: close,
    openChildren: ['child'],
    closedChildren: undefined as TurnOutcome['closedChildren'],
  };
  const host = {
    sessionOutcomes: new Map([['parent', outcome]]),
    claudeChildren: [{ parentSessionId: 'parent', sessionId: 'child', file: '/child', mtimeMs: close + 2000 }],
    claudeChildReferences: [],
    claudeChildStatWrites: new Map(),
    claudeChildVersion: () => version,
  };
  assert.deepEqual(read.call(host, now), new Map([['parent', ['child']]]));
  assert.equal(reader.mock.calls.length, 0);
  outcome.closedChildren = [{ id: 'child', closedAt: close }];
  assert.deepEqual(read.call(host, now), new Map());
  assert.deepEqual(read.call(host, now), new Map());
  assert.equal(reader.mock.calls.length, 1);
  version = 'v2';
  assert.deepEqual(read.call(host, now), new Map());
  assert.equal(reader.mock.calls.length, 2);
  version = 'v3';
  reader.mockReturnValue(close + 2000);
  assert.deepEqual(read.call(host, now), new Map([['parent', ['child']]]));
  assert.deepEqual(read.call(host, now), new Map([['parent', ['child']]]));
  assert.equal(reader.mock.calls.length, 3);
});
