test('retained focus restores the host blur without overriding newer focus', () => {
  let hasFocus = true,
    defaultFocus = true;
  const connected = new Set(['detail', 'prompt']);
  const restored: string[] = [];
  const owner = createRetainedFocus<string>({
    hasFocus: () => hasFocus,
    activeIsDefault: () => defaultFocus,
    eligible: (node) => connected.has(node),
    focus: (node) => restored.push(node),
  });
  owner.focused('detail');
  owner.hidden();
  owner.released();
  assert.deepEqual(restored, ['detail']);
  owner.hidden();
  defaultFocus = false;
  owner.released();
  assert.deepEqual(restored, ['detail']);
  owner.hidden();
  defaultFocus = true;
  hasFocus = false;
  owner.released();
  assert.deepEqual(restored, ['detail']);
  owner.hidden();
  hasFocus = true;
  connected.delete('detail');
  owner.released();
  assert.deepEqual(restored, ['detail']);
  connected.add('detail');
  owner.focused('detail');
  owner.hidden();
  hasFocus = false;
  owner.released();
  hasFocus = true;
  owner.windowFocused();
  assert.deepEqual(restored, ['detail', 'detail']);
  connected.add('detail');
  owner.hidden();
  owner.focused('prompt');
  owner.released();
  assert.deepEqual(restored, ['detail', 'detail']);
});
test('newer read-only activity cancels remembered and pending retained focus', () => {
  const restored: string[] = [];
  const owner = createRetainedFocus<string>({
    hasFocus: () => true,
    activeIsDefault: () => true,
    eligible: (node) => node === 'prompt',
    focus: (node) => restored.push(node),
  });
  owner.focused('prompt');
  owner.activity(null);
  owner.hidden();
  owner.released();
  assert.deepEqual(restored, [], 'read-only activity before hide restores old Prompt focus');
  owner.focused('prompt');
  owner.hidden();
  owner.activity(null);
  owner.released();
  owner.windowFocused();
  assert.deepEqual(restored, [], 'read-only activity during release restores old Prompt focus');
  owner.focused('prompt');
  owner.hidden();
  owner.focused('readonly');
  owner.released();
  owner.hidden();
  owner.released();
  assert.deepEqual(restored, [], 'newer ineligible focus leaves remembered or pending Prompt focus');
});

test('activity inside the focused control preserves its next host-blur target', () => {
  const restored: string[] = [];
  const owner = createRetainedFocus<string>({
    hasFocus: () => true,
    activeIsDefault: () => true,
    eligible: (node) => node === 'prompt' || node === 'detail',
    focus: (node) => restored.push(node),
  });
  owner.focused('prompt');
  owner.activity('prompt');
  owner.hidden();
  owner.released();
  assert.deepEqual(restored, ['prompt']);
  owner.hidden();
  owner.activity('detail');
  owner.focused('detail');
  owner.released();
  assert.deepEqual(restored, ['prompt'], 'newer activity restores the old control');
  owner.hidden();
  owner.released();
  assert.deepEqual(restored, ['prompt', 'detail']);
});

import { createPanelVisibility } from './panelvisibility.ts';

function retainedVisibilityFixture(observation = true) {
  let opacity = '0.7';
  let box: VisibilityBox = { x: 0, y: 0, width: 200, height: 100 };
  const paints: (() => void)[] = [];
  const observations: { receive: (entry: VisibilityObservation) => void; disconnected: boolean }[] = [];
  let placements = 0;
  const controller = createRetainedVisibility({
    opacity: () => opacity,
    setOpacity: (value) => {
      opacity = value;
    },
    box: () => box,
    afterPaint: (callback) => paints.push(callback),
    place: () => {
      placements++;
    },
    observe: observation
      ? (receive) => {
          const observer = { receive, disconnected: false };
          observations.push(observer);
          return () => {
            observer.disconnected = true;
          };
        }
      : undefined,
  });
  return {
    controller,
    paints,
    observations,
    opacity: () => opacity,
    placements: () => placements,
    box: () => box,
    resize: (next: VisibilityBox) => {
      box = next;
      controller.resize();
    },
  };
}

test('retained returns require a fresh full current-box observation and paint', () => {
  const f = retainedVisibilityFixture();
  f.controller.receive({ visible: true, revision: 0 });
  assert.equal(f.opacity(), '0.7');
  f.controller.receive({ visible: false, revision: 1 });
  assert.equal(f.opacity(), '0');
  f.controller.receive({ visible: true, revision: 2 });
  f.paints[0]();
  f.observations[0].receive({ full: true, box: { ...f.box(), width: 300, height: 150 } });
  assert.equal(f.opacity(), '0', 'a cached fallback box releases the current page');
  f.observations[0].receive({ full: false, box: f.box() });
  assert.equal(f.opacity(), '0', 'a partly clipped current box releases the page');
  f.observations[0].receive({ full: true, box: f.box() });
  assert.equal(f.opacity(), '0.7', 'a genuine small group never becomes readable');
  assert.equal(f.placements(), 1);
});

test('resize and hide reject old observer and paint generations', () => {
  const f = retainedVisibilityFixture();
  f.controller.receive({ visible: false, revision: 1 });
  f.controller.receive({ visible: true, revision: 2 });
  f.resize({ ...f.box(), width: 80, height: 60 });
  assert.ok(f.observations[0].disconnected);
  f.observations[0].receive({ full: true, box: f.box() });
  f.paints[0]();
  f.paints[1]();
  assert.equal(f.opacity(), '0', 'obsolete observation releases resized content');
  f.controller.receive({ visible: false, revision: 3 });
  f.observations[1].receive({ full: true, box: f.box() });
  assert.equal(f.opacity(), '0');
  f.controller.receive({ visible: true, revision: 2 });
  assert.equal(f.observations.length, 2, 'an old show starts a new release');
  f.controller.receive({ visible: true, revision: 4 });
  f.observations[2].receive({ full: true, box: f.box() });
  assert.equal(f.opacity(), '0', 'observation skips the paint boundary');
  f.paints[2]();
  assert.equal(f.opacity(), '0.7');
  f.resize({ ...f.box() });
  assert.equal(f.observations.length, 3, 'synthetic resize starts unnecessary work');
  f.controller.dispose();
  assert.ok(f.observations[2].disconnected);
  f.controller.receive({ visible: false, revision: 5 });
  assert.equal(f.opacity(), '0.7');
});

test('unsupported observation releases after paint and disposal restores opacity', () => {
  const f = retainedVisibilityFixture(false);
  f.controller.receive({ visible: false, revision: 1 });
  f.controller.receive({ visible: true, revision: 2 });
  assert.equal(f.opacity(), '0');
  f.paints[0]();
  assert.equal(f.opacity(), '0.7');
  f.controller.receive({ visible: false, revision: 3 });
  f.controller.receive({ visible: true, revision: 4 });
  f.controller.dispose();
  f.paints[1]();
  assert.equal(f.opacity(), '0.7');
});

test('visibility revisions belong to one panel lifetime', () => {
  const owner = createPanelVisibility<object>();
  const a = {},
    b = {};
  assert.deepEqual(owner.current(a, false), { type: 'visibility', revision: 1, visible: false });
  assert.equal(owner.current(a, true).revision, 2);
  assert.equal(owner.current(b, true).revision, 1);
  owner.release(a);
  assert.equal(owner.current(a, true).revision, 1);
  owner.clear();
  assert.equal(owner.current(b, false).revision, 1);
});
