test('command-only admission removes pending rows through every catalog path and releases list and search names', () => {
  const directory = tempDir('command-catalog-');
  const file = path.join(directory, 'command.jsonl');
  const peerFile = path.join(directory, 'peer.jsonl');
  fs.writeFileSync(
    peerFile,
    JSON.stringify({
      type: 'user',
      timestamp: '2026-10-09T05:30:52.052Z',
      message: { role: 'user', content: 'another task' },
    }) + '\n',
  );
  const peer = {
    agent: 'claude',
    sessionId: 'peer',
    cwd: directory,
    file: peerFile,
    ...revisionOf(fs.statSync(peerFile, { bigint: true })),
  };
  const command = {
    type: 'user',
    uuid: 'B',
    timestamp: '2026-10-09T05:30:52.052Z',
    message: {
      role: 'user',
      content:
        '<command-name>/usage-credits</command-name>\n<command-message>usage-credits</command-message>\n<command-args></command-args>',
    },
  };
  const caveat = {
    ...command,
    uuid: 'A',
    isMeta: true,
    timestamp: '2026-10-09T05:30:52.053Z',
    message: { role: 'user', content: '<local-command-caveat>Run in the CLI</local-command-caveat>' },
  };
  const answer = {
    ...command,
    uuid: 'C',
    parentUuid: 'B',
    message: { role: 'user', content: '<local-command-stdout>Login interrupted</local-command-stdout>' },
  };
  let sources: any[] = [];
  const dependencies = {
    fs,
    fileRevisionOf: revisionOf,
    revalidatedCatalog,
    revalidatedCatalogPaths,
    orderSessionCatalog,
    readSession,
    readCodexSession,
    turnKey,
    AGENT_NAMES,
    searchablePrompt,
    searchableSummary,
    SEARCH_TAIL_BYTES: 1024 * 1024,
    codexSessionIndexPath: () => '',
    readThreadNames: () => ({ stamp: '', names: new Map() }),
    projectsRoot: () => directory,
    codexSessionsRoot: () => directory,
    sessionFilesFor: () => sources,
    readSessionCwd: () => directory,
    staleMetas: () => [],
    discoverClaudeSessionSpendSources: () => [],
    codexSessionFiles: () => ({ walked: [], sessions: [], sources: [], subagents: [] }),
  };
  const compile = (name: string, body: string, parameters: string) => {
    const code = ts.transpileModule(`function ${name}(${parameters}) { ${body} }`, {
      compilerOptions: { target: ts.ScriptTarget.ES2022 },
    }).outputText;
    return new Function(...Object.keys(dependencies), code + `\nreturn ${name};`)(...Object.values(dependencies));
  };
  const listing = compile('listing', methodBody('private allSessions('), 'reuseCatalog = false');
  const search = compile('search', methodBody('private searchCorpus('), 'only = null');
  const refreshBody = methodBody('async refresh(');
  const selected = compile(
    'selected',
    refreshBody.slice(
      refreshBody.indexOf('let all = selectedOnly'),
      refreshBody.indexOf("this.performanceCounters.recordRefresh('catalog-enumeration'"),
    ) + '\nreturn all;',
    'selectedOnly = true, reuseCatalog = true',
  );
  const childrenBody = methodBody('private async prepareClaudeChildren(');
  const discovery = compile(
    'discovery',
    childrenBody.slice(
      childrenBody.indexOf('const held = this.catalog?.sessions'),
      childrenBody.indexOf('this.discoveryComplete = {'),
    ) + '\nreturn sessions;',
    'progress, spendSources = null',
  );
  for (const route of ['walk', 'targeted', 'reuse', 'selected', 'worker']) {
    fs.writeFileSync(file, [caveat, command].map((row) => JSON.stringify(row)).join('\n') + '\n');
    const source = () => ({
      agent: 'claude',
      sessionId: 'command',
      cwd: directory,
      file,
      ...revisionOf(fs.statSync(file, { bigint: true })),
    });
    sources = [source(), peer];
    const provider: any = Object.assign(Object.create(PanelProvider.prototype), {
      folders: () => [directory],
      repositoryScope: { snapshot: () => ({ ready: true, roots: [directory], revision: 1 }) },
      publishWindowState() {},
      activityFor: () => 1,
      codexMetas: { revision: 0, keys: () => [] },
      codexStats: { keys: () => [] },
      subagentDirectories: { sweep() {} },
      cwds: new Map(),
      humanScans: new Map(),
      claudeChildren: [],
      titles: new Map(),
      sessionNames: new SessionNames(),
      carriedNames: new Map(),
      hidden: new Set(['command']),
      pinnedTop: new Set(),
      saved: { labels: { command: ['Review'] }, read: ['turn'], readTo: { command: 1 } },
      showing: 'peer',
      newDrafts: {},
      awaitingSessionRecords: {},
      metaFor(session: any) {
        return this.titles.get(session.file);
      },
      corpus: new Map(),
      threadNames: { stamp: '', names: new Map() },
      allSessions(reuse = false) {
        return listing.call(this, reuse);
      },
    });
    const observe = () => {
      const meta = readSessionMeta(file);
      const next = {
        ...source(),
        label: meta.title ?? '',
        fullLabel: meta.fullTitle ?? '',
        nameSource: meta.titleSource ?? undefined,
        nameAt: meta.titleAt,
        headKey: meta.headKey,
        withdrawnPrompt: meta.withdrawnPrompt,
        outcome: meta.outcome,
        stats: null,
        agentRun: false,
        activityMs: meta.activityMs,
      };
      const carried = carryDerivedTitleFacts(provider.titles.get(file), next);
      provider.titles.set(file, provider.observeStoredName(source(), carried));
    };
    const read = () => {
      if (route === 'worker') return discovery.call(provider, { roots: sources });
      if (route === 'selected') return selected.call(provider);
      provider.targetedRefreshPaths = route === 'targeted' ? [peerFile] : null;
      return listing.call(provider, route === 'reuse');
    };
    assert.equal(listing.call(provider).length, 2);
    provider.authoritativeCatalog = sources;
    if (route === 'selected') {
      const accepted = provider.authoritativeCatalog;
      const acceptedBytes = accepted[1].size;
      fs.appendFileSync(peerFile, JSON.stringify({ type: 'mode', mode: 'normal' }) + '\n');
      const refreshed = read();
      assert.ok(refreshed[1].size > acceptedBytes);
      assert.equal(
        provider.authoritativeCatalog,
        accepted,
        'revalidation without removal preserves accepted revisions',
      );
    }
    observe();
    assert.equal(provider.sessionLabel(source()).label, '/usage-credits');
    fs.appendFileSync(file, JSON.stringify(answer) + '\n');
    sources = [source(), peer];
    assert.deepEqual(
      read().map((session: any) => session.sessionId),
      ['peer'],
      route,
    );
    if (route === 'selected') assert.equal(provider.authoritativeCatalog.length, 1);
    observe();
    assert.equal(provider.sessionNames.get('command'), null, route);
    fs.appendFileSync(
      file,
      JSON.stringify({ ...command, uuid: 'D', message: { role: 'user', content: 'actual task' } }) + '\n',
    );
    sources = [source(), peer];
    provider.targetedRefreshPaths = [file];
    assert.equal(listing.call(provider).length, 2, route);
    observe();
    assert.equal(provider.sessionLabel(source()).fullLabel, 'actual task', route);
    assert.equal(
      search.call(provider).find((entry: any) => entry.sessionId === 'command')?.sessionTitle,
      'actual task',
      route,
    );
    assert.equal(provider.hidden.has('command'), true);
    assert.deepEqual(provider.saved.labels.command, ['Review']);
    assert.deepEqual(provider.saved.read, ['turn']);
    assert.equal(provider.saved.readTo.command, 1);
  }
});

test('human admission uses walked sizes and stats reused rows only until evidence is confirmed', async () => {
  const { scanForHumanPrompt, promptScanLists } = await import('./transcript.ts');
  const directory = tempDir('command-size-');
  const file = path.join(directory, 'command.jsonl');
  const command = { type: 'user', uuid: 'command', message: { role: 'user', content: '/usage-credits' } };
  fs.writeFileSync(file, JSON.stringify(command) + '\n');
  const source: any = { agent: 'claude', file, size: fs.statSync(file).size };
  const provider: any = Object.assign(Object.create(PanelProvider.prototype), { humanScans: new Map() });
  const stat = vi.fn<typeof fs.statSync>(fs.statSync);
  const compiled = ts.transpileModule(
    `function admission(session, sizeCurrent = false) { ${methodBody('private hasHumanPrompt(')} }`,
    {
      compilerOptions: { target: ts.ScriptTarget.ES2022 },
    },
  ).outputText;
  provider.hasHumanPrompt = new Function(
    'fs',
    'scanForHumanPrompt',
    'promptScanLists',
    compiled + '\nreturn admission;',
  )({ statSync: stat }, scanForHumanPrompt, promptScanLists);
  assert.equal(provider.hasHumanPrompt(source, true), true);
  assert.equal(stat.mock.calls.length, 0);
  fs.appendFileSync(
    file,
    JSON.stringify({
      type: 'user',
      parentUuid: 'command',
      message: { content: '<local-command-stdout>Done</local-command-stdout>' },
    }) + '\n',
  );
  assert.equal(provider.hasHumanPrompt(source), false);
  assert.equal(stat.mock.calls.length, 1);
  // Model work after the answer leaves the command withdrawn. A later typed prompt and its reply confirm.
  fs.appendFileSync(
    file,
    [
      { type: 'assistant', message: { role: 'assistant', content: 'model work' } },
      { type: 'user', uuid: 'task', timestamp: '2026-01-01T00:00:05.000Z', message: { role: 'user', content: 'task' } },
      { type: 'assistant', message: { role: 'assistant', content: 'task work' } },
    ]
      .map((record) => JSON.stringify(record))
      .join('\n') + '\n',
  );
  assert.equal(provider.hasHumanPrompt(source), true);
  assert.equal(stat.mock.calls.length, 2);
  assert.equal(provider.hasHumanPrompt(source), true);
  assert.equal(stat.mock.calls.length, 2, 'confirmed evidence does not stat a stale row');
});

test('current whole-file facts archive a listed session with no turn, refuse unavailable facts, and archive known active work only with force', async () => {
  const directory = tempDir('empty-session-archive-');
  const file = path.join(directory, 'empty.jsonl');
  fs.writeFileSync(file, JSON.stringify({ type: 'mode', mode: 'normal' }) + '\n');
  const source = {
    agent: 'claude',
    sessionId: 'empty',
    cwd: directory,
    file,
    ...revisionOf(fs.statSync(file, { bigint: true })),
  };
  const meta = readSessionMeta(file);
  const entry: any = {
    ...source,
    outcome: meta.outcome,
    activityMs: meta.activityMs,
    metadataWindow: meta.coverage,
    starts: readSessionTurnStarts(file),
  };
  let visible = true;
  let unread: any = undefined;
  const provider: any = Object.assign(Object.create(PanelProvider.prototype), {
    disposed: false,
    folders: () => [directory],
    repositoryScope: { snapshot: () => ({ ready: true, roots: [directory], revision: 1 }) },
    authoritativeCatalog: [source],
    authoritativeCatalogScope: JSON.stringify([directory]),
    anyVisible: () => visible,
    watching: true,
    pendingWatch: { snapshot: () => ({ eventCount: 0, broadRequired: false }) },
    unreadCounts: () => new Map(unread ? [['empty', unread]] : []),
    titles: new Map([[file, entry]]),
    cache: new Map(),
    pinnedTop: new Set(),
    hidden: new Set(),
    saved: normalizePanelState(null),
    sessionLabel: () => ({ fullLabel: 'Empty' }),
    agentRunFor: () => false,
    readyHosts: new Set([{}]),
    memento: { update: async () => {} },
    sessionWriteQueue: Promise.resolve(),
    running: new Set(),
    asks: [],
    post: async () => {},
    postRail() {},
    sessionAliases: new Map(),
  });
  const request: any = {
    method: 'curate',
    requester: null,
    params: { sessionId: 'empty', action: 'archive', force: false, dryRun: false },
  };
  const row = () => provider.readSessionRequest({ ...request, method: 'sessions', params: {} }).sessions[0];
  assert.deepEqual([row().runStatus, row().attention], ['none', 'idle']);
  source.agent = 'codex';
  assert.equal(row().runStatus, 'unknown');
  const rollout = path.join(directory, 'observed.jsonl');
  fs.writeFileSync(
    rollout,
    [
      { type: 'session_meta', payload: { id: 'empty' } },
      { type: 'event_msg', timestamp: '2026-01-01T00:00:01Z', payload: { type: 'task_started', turn_id: 'turn' } },
      { type: 'event_msg', timestamp: '2026-01-01T00:00:01Z', payload: { type: 'user_message', message: 'work' } },
      {
        type: 'turn_context',
        timestamp: '2026-01-01T00:00:02Z',
        payload: { turn_id: 'turn', model: 'gpt-6.1-sol', effort: 'low' },
      },
      { type: 'event_msg', timestamp: '2026-01-01T00:00:03Z', payload: { type: 'task_complete', turn_id: 'turn' } },
    ]
      .map((record) => JSON.stringify(record))
      .join('\n') + '\n',
  );
  entry.stats = sessionStatFactsOf(readCodexSession(rollout, 'empty'));
  assert.deepEqual(row().setup, { model: 'gpt-6.1-sol', effort: 'low', source: 'recorded' });
  entry.stats.turns[0].effort = null;
  assert.equal(row().setup.effort, null);
  delete entry.stats;
  source.agent = 'claude';
  assert.equal((await provider.handleSessionRequest(request)).status, 'applied');
  assert.equal(provider.hidden.has('empty'), true);
  for (const pending of ['event', 'refresh']) {
    await provider.handleSessionRequest({ ...request, params: { ...request.params, action: 'unarchive' } });
    provider.pendingWatch = { snapshot: () => ({ eventCount: pending === 'event' ? 1 : 0, broadRequired: false }) };
    provider.refreshController = pending === 'refresh' ? {} : null;
    assert.deepEqual([row().facts, row().runStatus, row().attention], ['current', 'none', 'idle']);
    assert.equal((await provider.handleSessionRequest(request)).status, 'applied');
    assert.equal(provider.hidden.has('empty'), true);
  }
  provider.pendingWatch = { snapshot: () => ({ eventCount: 0, broadRequired: false }) };
  provider.refreshController = null;
  const refuse = async (pattern: RegExp) =>
    assert.match((await provider.handleSessionRequest(request)).reason, pattern);
  entry.metadataWindow = { whole: false, windowBytes: 1 };
  assert.equal(row().runStatus, 'unknown');
  await refuse(/unavailable/);
  entry.metadataWindow = meta.coverage;
  entry.starts = { whole: false, starts: [] };
  await refuse(/unavailable/);
  entry.starts = undefined;
  await refuse(/unavailable/);
  entry.starts = readSessionTurnStarts(file);
  provider.titles.clear();
  await refuse(/unavailable/);
  provider.titles.set(file, entry);
  visible = false;
  assert.deepEqual([row().facts, row().runStatus, row().attention], ['current', 'none', 'unknown']);
  await refuse(/unavailable/);
  visible = true;
  provider.running.add('claude:empty');
  await refuse(/running or needs input/);
  provider.running.clear();
  provider.asks = [{ session: 'empty' }];
  await refuse(/running or needs input/);
  provider.asks = [];
  entry.backgroundCommands = [{ id: 'background', startedAt: Date.now() }];
  assert.equal(row().runStatus, 'background');
  await refuse(/background work/);
  assert.equal(
    (await provider.handleSessionRequest({ ...request, params: { ...request.params, force: true } })).status,
    'refused',
  );
  visible = false;
  assert.equal(row().runStatus, 'background');
  visible = true;
  delete entry.backgroundCommands;
  unread = { count: 1, atLeast: false };
  await refuse(/--force/);
  assert.equal(
    (await provider.handleSessionRequest({ ...request, params: { ...request.params, force: true } })).status,
    'applied',
  );
  unread = undefined;
  // Known running or Needs input evidence admits a forced archive while the transcript metadata is stale.
  const forced = { ...request, params: { ...request.params, force: true } };
  const saves: string[][] = [];
  provider.memento = {
    update: async (_key: string, state: { hidden: string[] }) => {
      saves.push([...state.hidden]);
    },
  };
  provider.pendingWatch = { snapshot: () => ({ eventCount: 1, broadRequired: false }) };
  entry.size = -1;
  for (const [active, live] of [
    ['running', () => provider.running.add('claude:empty')],
    ['input', () => (provider.asks = [{ session: 'empty' }])],
  ] as const) {
    assert.equal(
      (await provider.handleSessionRequest({ ...request, params: { ...request.params, action: 'unarchive' } })).status,
      'applied',
    );
    provider.pinnedTop = new Set(['empty']);
    live();
    assert.deepEqual([row().facts, row().attention], ['stale', active]);
    await refuse(/running or needs input\. Use --force/);
    assert.equal(provider.hidden.has('empty'), false);
    const dry = await provider.handleSessionRequest({ ...forced, params: { ...forced.params, dryRun: true } });
    assert.equal(dry.status, 'dry-run');
    assert.equal(dry.evaluatedRunStatus, active === 'input' ? 'waiting' : 'running');
    assert.equal(provider.hidden.has('empty'), false);
    saves.length = 0;
    const result = await provider.handleSessionRequest(forced);
    assert.deepEqual([result.status, result.archived, result.pinned], ['applied', true, false], result.reason);
    assert.equal(result.evaluatedRunStatus, active === 'input' ? 'waiting' : 'running');
    assert.deepEqual(saves, [['empty']]);
    assert.equal(provider.pinnedTop.has('empty'), false);
    provider.running.clear();
    provider.asks = [];
  }
  // A rejected save leaves a forced archive of an active session unapplied and keeps its pin.
  assert.equal(
    (await provider.handleSessionRequest({ ...request, params: { ...request.params, action: 'unarchive' } })).status,
    'applied',
  );
  provider.pinnedTop = new Set(['empty']);
  provider.running.add('claude:empty');
  const update = provider.memento.update;
  provider.memento.update = async () => {
    throw new Error('save refused');
  };
  await assert.rejects(provider.handleSessionRequest(forced), /save refused/);
  assert.equal(provider.hidden.has('empty'), false);
  assert.equal(provider.pinnedTop.has('empty'), true);
  provider.memento.update = update;
  provider.running.clear();
  // A hidden panel leaves attention unknown, and known running evidence still admits the forced archive.
  visible = false;
  provider.running.add('claude:empty');
  assert.deepEqual([row().runStatus, row().attention, row().facts], ['running', 'unknown', 'stale']);
  await refuse(/--force/);
  assert.equal((await provider.handleSessionRequest(forced)).status, 'applied');
  provider.running.clear();
  // A forced archive admits an inactive session whose state Arc cannot read, and ordinary archive still refuses it.
  // The first row has stale facts. The second row has a known run status behind a hidden panel.
  const finished = {
    startedAt: Date.now() - 2000,
    endedAt: Date.now() - 1000,
    finished: true,
    error: false,
    interrupted: false,
  };
  for (const [unreadable, state] of [
    [() => (visible = true), ['unknown', 'unknown', 'stale']],
    [
      () => {
        visible = false;
        provider.pendingWatch = { snapshot: () => ({ eventCount: 0, broadRequired: false }) };
        entry.size = source.size;
        entry.outcome = finished;
      },
      ['done', 'unknown', 'current'],
    ],
  ] as const) {
    assert.equal(
      (await provider.handleSessionRequest({ ...request, params: { ...request.params, action: 'unarchive' } })).status,
      'applied',
    );
    provider.pinnedTop = new Set(['empty']);
    unreadable();
    assert.deepEqual([row().runStatus, row().attention, row().facts], state);
    const refused = await provider.handleSessionRequest(request);
    assert.deepEqual(
      [refused.status, refused.reason],
      ['refused', 'The session state is unavailable. Show Arc and retry.'],
    );
    assert.equal(provider.hidden.has('empty'), false);
    saves.length = 0;
    const result = await provider.handleSessionRequest(forced);
    assert.deepEqual([result.status, result.archived, result.pinned], ['applied', true, false], result.reason);
    assert.deepEqual(saves, [['empty']]);
    assert.equal(provider.pinnedTop.has('empty'), false);
  }
  // A finished turn that left background work running refuses archive, with force too.
  visible = true;
  for (const [outcome, runStatus] of [
    [{ ...finished, openChildren: ['child'] }, 'subagents'],
    [{ ...finished, backgroundCommands: [{ id: 'command', startedAt: Date.now() - 1000 }] }, 'background'],
  ] as const) {
    assert.equal(
      (await provider.handleSessionRequest({ ...request, params: { ...request.params, action: 'unarchive' } })).status,
      'applied',
    );
    entry.outcome = outcome;
    saves.length = 0;
    for (const attempt of [forced, request]) {
      const result = await provider.handleSessionRequest(attempt);
      assert.deepEqual([result.status, provider.hidden.has('empty')], ['refused', false], runStatus);
      assert.match(result.reason, /^Arc cannot tell whether background work in the session ended/);
    }
    assert.deepEqual(saves, []);
    assert.deepEqual([row().runStatus, row().attention, row().facts], [runStatus, 'running', 'current']);
  }
});

test('window session reads leave reader state and live capabilities unchanged and reject unknown IDs', () => {
  const directory = tempDir('window-session-state-');
  const file = path.join(directory, 'known.jsonl');
  fs.writeFileSync(
    file,
    [
      {
        type: 'user',
        sessionId: 'known',
        cwd: directory,
        timestamp: '2026-10-08T12:00:00Z',
        message: { role: 'user', content: 'read me' },
      },
      {
        type: 'assistant',
        timestamp: '2026-10-08T12:00:01Z',
        message: {
          id: 'reply',
          model: 'claude-opus-5-5',
          role: 'assistant',
          content: [{ type: 'text', text: 'reply' }],
          stop_reason: 'end_turn',
          usage: { input_tokens: 1, output_tokens: 1 },
        },
      },
    ]
      .map((row) => JSON.stringify(row))
      .join('\n') + '\n',
  );
  const stat = revisionOf(fs.statSync(file, { bigint: true }));
  const source = { agent: 'claude', sessionId: 'known', file, size: stat.size, mtimeMs: stat.mtimeMs };
  const saved = {
    labels: { known: ['Review'] },
    readerParents: { known: 'parent' },
    read: ['earlier'],
    readTo: { known: 1 },
  };
  const untouched = {
    saved,
    showing: 'other',
    drafts: { other: 'unsent prompt' },
    hostSessions: new Map([['restored', 'other']]),
    picks: { other: { model: 'chosen' } },
    runtime: { other: { send: true } },
    startedHere: new Set(['other']),
    catalog: { folders: 'held', sessions: [source] },
    catalogWalked: false,
    titles: new Map(),
    carriedNames: new Map([['held', 'Held title']]),
    enumeratedSpendSources: { claude: [source], codex: [], children: [] },
  };
  const provider: any = Object.assign(Object.create(PanelProvider.prototype), untouched, {
    disposed: false,
    folders: () => [directory],
    repositoryScopeRoots: [directory],
    completeCatalogScope: JSON.stringify([directory]),
    repositoryScope: { snapshot: () => ({ ready: true, roots: [directory], revision: 1 }) },
    authoritativeCatalog: [source],
    authoritativeCatalogScope: JSON.stringify([directory]),
    pendingWatch: { snapshot: () => ({ eventCount: 0, broadRequired: false }) },
    exitedSinceKeys: new Map(),
    allSessions(this: any) {
      this.catalogWalked = true;
      this.titles.clear();
      return [source];
    },
    sessionParentEdges: () => ({ edges: new Map() }),
    anyVisible: () => false,
    sessionLabel: () => ({ fullLabel: 'Known' }),
    titles: new Map(),
    pinnedTop: new Set(['known']),
    hidden: new Set(['known']),
    cache: new Map(),
  });
  const snapshot = JSON.stringify(untouched, (_key, value) =>
    value instanceof Map || value instanceof Set ? [...value] : value,
  );
  const request: any = { method: 'sessions', params: {}, requester: 'requesting-agent' };
  const listing = provider.readSessionRequest(request);
  assert.equal(listing.sessions[0].attention, 'unknown');
  assert.equal(listing.sessions[0].facts, 'unparsed');
  assert.equal(listing.sessions[0].pinned, true);
  assert.equal(listing.sessions[0].archived, true);
  assert.deepEqual(listing.sessions[0].labels, [{ name: 'Review', source: 'reader' }]);
  const read = provider.readSessionRequest({ ...request, method: 'session', params: { sessionId: 'known', turns: 1 } });
  assert.equal(read.turns[0].summary, 'reply');
  assert.throws(
    () =>
      provider.readSessionRequest({ ...request, method: 'session', params: { sessionId: '/other/file', turns: 1 } }),
    /unknown or ambiguous/,
  );
  assert.equal(
    JSON.stringify(Object.fromEntries(Object.keys(untouched).map((key) => [key, provider[key]])), (_key, value) =>
      value instanceof Map || value instanceof Set ? [...value] : value,
    ),
    snapshot,
  );
});

// These host cases catch reader-state loss and premature durable replies. They reuse the live-provider fixture without browser startup.
test('window starts adopt both providers and classifications without changing the reader draft, selection, watermarks or tabs', async () => {
  for (const agent of ['claude', 'codex'] as const)
    for (const agentRun of [false, true]) {
      const fixture = liveProviderFixture(livePress({ sessionId: 'reader', agent }));
      const provider: any = fixture.provider;
      const messages: any[] = [];
      const catalog = {
        [agent]: [
          {
            value: 'runtime-model',
            label: 'Runtime model',
            description: '',
            efforts: [{ value: 'runtime-effort', label: 'Runtime effort', description: '' }],
          },
        ],
      };
      const profile = {
        agent,
        model: 'runtime-model',
        effort: 'runtime-effort',
        permissionMode: '',
        source: 'custom' as const,
      };
      let save!: () => void;
      let calls = 0;
      Object.assign(provider, {
        saved: normalizePanelState({
          showing: 'reader',
          read: ['read-key'],
          readTo: { reader: 9 },
          labels: { reader: ['Existing'] },
        }),
        drafts: { reader: 'unsent reader prompt' },
        draftProfiles: {},
        staging: new Set(),
        railOrder: ['reader'],
        startedHere: new Set(['reader']),
        pinnedTop: new Set(['reader']),
        hidden: new Set(),
        trail: emptyTrail(),
        models: catalog,
        pendingModels: [],
        setupProject: 'project',
        folders: () => ['C:/workspace'],
        repositoryScope: { snapshot: () => ({ ready: true, roots: ['C:/workspace'], revision: 1 }) },
        launcherFor: () => ({ view: sessionLauncherView(null, [], catalog) }),
        post: async (message: unknown) => {
          messages.push(message);
        },
        memento: {
          update: () =>
            new Promise<void>((resolve) => {
              save = resolve;
            }),
        },
        onSessionSettingsAdopted: async () => {},
        onRenameStartedSession: async (provider: string, session: string, cwd: string, name: string) => {
          assert.equal(provider, agent);
          assert.equal(session, 'accepted');
          assert.equal(cwd, 'C:/workspace');
          assert.equal(name, 'Initial name');
          messages.push({ type: 'initialName' });
        },
        onSendDraftPrompt: async (draft: NewSessionDraft, prompt: { text: string }) => {
          calls++;
          assert.deepEqual(draft.profile, profile);
          assert.equal(prompt.text, 'work');
          return { delivered: true, session: 'accepted', turnId: 7, reason: '' };
        },
      });
      const before = JSON.stringify([
        provider.showing,
        provider.drafts,
        [...provider.hostSessions],
        [...provider.hostPreviousSessions],
        provider.saved.read,
        provider.saved.readTo,
      ]);
      const request: any = {
        method: 'start',
        requester: 'attribution',
        params: {
          prompt: 'work',
          name: 'Initial name',
          setup: { kind: 'custom', ...profile },
          agentRun,
          labels: [' Review ', 'review'],
          pinned: true,
        },
      };
      let settled = false;
      const pending = provider.handleSessionRequest(request).then((value: unknown) => {
        settled = true;
        return value;
      });
      await vi.waitFor(() => assert.equal(typeof save, 'function'));
      assert.equal(settled, false);
      save();
      const result: any = await pending;
      assert.equal(result.status, 'accepted');
      assert.equal(result.sessionId, 'accepted');
      assert.deepEqual(provider.saved.labels.accepted, ['Review']);
      assert.equal(provider.pinnedTop.has('accepted'), true);
      assert.equal(provider.startedHere.has('accepted'), !agentRun);
      assert.equal(provider.saved.agentRuns?.includes('accepted') ?? false, agentRun);
      assert.equal(
        JSON.stringify([
          provider.showing,
          provider.drafts,
          [...provider.hostSessions],
          [...provider.hostPreviousSessions],
          provider.saved.read,
          provider.saved.readTo,
        ]),
        before,
      );
      assert.equal(calls, 1);
      for (const prompt of ['', '  ', '/clear', '  /model'])
        await assert.rejects(
          provider.handleSessionRequest({ ...request, params: { ...request.params, prompt } }),
          /nonempty prompt/,
        );
      await assert.rejects(
        provider.handleSessionRequest({
          ...request,
          params: { ...request.params, setup: { kind: 'custom', ...profile, model: 'unknown' } },
        }),
        /unavailable/,
      );
      assert.equal(calls, 1);
      assert.equal(
        messages.some((message) => message.type === 'labelsChanged'),
        true,
      );
      assert.equal(
        messages.some((message) => message.type === 'initialName'),
        true,
      );
    }
});

