test('commit repository replies expire on parent-only changes and reject stale or changed ownership', async () => {
  const directory = tempDir('host-commit-evidence-');
  const parentFile = path.join(directory, 'parent.jsonl');
  const childFile = path.join(directory, 'child.jsonl');
  fs.writeFileSync(parentFile, 'parent');
  fs.writeFileSync(childFile, 'child');
  const parent = { agent: 'codex', sessionId: 'parent', file: parentFile, size: 6, mtimeMs: 1 };
  const child = {
    threadId: 'child',
    parentThreadId: 'parent',
    file: childFile,
    agentPath: '/root/worker',
    backgroundReview: false,
    openedAt: 1,
    startedAt: 1,
    threadSource: 'subagent',
  };
  const session = { ...parent, sessionId: 'child', file: childFile };
  const commit = {
    sha: 'a'.repeat(7),
    printedSha: 'a'.repeat(40),
    subject: 'Recorded',
    at: 5,
    files: 1,
    added: 2,
    removed: 0,
    dir: null,
    place: null,
    repositoryEvidence: { dirs: ['C:/first/worktree'], at: 6, turnId: 'turn', complete: true },
  };
  const turns = [turn({ commits: [commit] })];
  const provider: any = Object.create(PanelProvider.prototype);
  provider.codexSubagents = [child];
  provider.allSessions = () => [parent];
  provider.commitRepositoryReplies = new Map();
  provider.commitRepositoryReservations = new CommitRepositoryReservations();
  let alter = () => {};
  provider.progressiveWorker = {
    async run(request: any, generation: number) {
      alter();
      return {
        generation,
        revision: request.parent.revision,
        value: {
          kind: 'commit-repositories',
          status: 'complete',
          token: 'complete',
          parent: request.parent,
          child: request.child,
          parserVersion: request.parserVersion,
          readBytes: { parent: 0, child: 0 },
          covered: { parent: [0, request.parent.revision.size], child: [0, request.child.revision.size] },
          targets: [
            {
              sha: commit.printedSha,
              dirs: ['C:/first'],
              occurrence: JSON.stringify([
                commit.repositoryEvidence.turnId,
                commit.at,
                commit.repositoryEvidence.at,
                commit.printedSha,
                commit.repositoryEvidence.dirs,
              ]),
            },
          ],
        },
      };
    },
  };
  await provider.hydrateCommitRepositories(session, turns, 1, new AbortController().signal);
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.deepEqual(turns[0].commits[0].candidates, { dirs: ['C:/first'], complete: true });
  fs.appendFileSync(parentFile, ' changed');
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
  assert.equal(turns[0].commits[0].dir, null);
  alter = () => fs.appendFileSync(parentFile, ' stale');
  await provider.hydrateCommitRepositories(session, turns, 2, new AbortController().signal);
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
  alter = () => {};
  await provider.hydrateCommitRepositories(session, turns, 3, new AbortController().signal);
  fs.renameSync(parentFile, parentFile + '.old');
  fs.writeFileSync(parentFile, 'replacement');
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
  provider.codexSubagents = [{ ...child, parentThreadId: 'other' }];
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
});

// Gives a commit allowance host the selection state that completeSelectedWindow reads, and counts its redraws.
function selectCommitSession(provider: any, session: any, turns: any[]) {
  const drawn = { refreshes: 0 };
  Object.assign(provider, {
    authoritativeCatalog: [session],
    history: new Map(),
    cache: new Map([
      [session.file, { read: { turns }, agentKey: 'agents', revision: { size: session.size, mtimeMs: 1 } }],
    ]),
    selectionWork: null,
    selectionFailure: null,
    selectionGeneration: 1,
    showing: session.sessionId,
    hosts: [],
    folders: () => [],
    anyVisible: () => true,
    progressiveCurrent: () => true,
    agentSpendKey: () => 'agents',
    acceptSelectedMetadataRead() {},
    refresh() {
      drawn.refreshes++;
    },
  });
  return drawn;
}

test('an unchanged pending commit reply does not redraw the selected session', async () => {
  const { provider, parent, sessions, reply, resolve } = commitAllowanceHost(1);
  const drawn = selectCommitSession(provider, sessions[0].session, sessions[0].turns);
  const statuses = ['pending', 'pending', 'pending', 'complete'];
  const drawnAfter: number[] = [];
  provider.progressiveWorker = {
    async run(request: any, generation: number) {
      drawnAfter.push(drawn.refreshes);
      return reply(request, generation, statuses[drawnAfter.length - 1], { parent: 0, child: 0 });
    },
  };
  await provider.completeSelectedWindow('child-0', 1);
  await vi.waitFor(() => {
    assert.equal(drawnAfter.length, statuses.length);
    assert.equal(provider.selectionWork, null);
  });
  // The first pending reply is the first stored reply, so it draws once. Later pending replies keep its status and key.
  assert.deepEqual(drawnAfter, [0, 1, 1, 1], 'an unchanged pending commit reply redrew the selected session');
  assert.equal(drawn.refreshes, 2, 'the complete commit reply did not redraw the selected session exactly once');
  assert.deepEqual(resolve(0), { dirs: ['C:/child-0'], complete: true });
  // A parent-only change expires the complete reply. A cancelled request stores nothing, and the rows still lose navigation.
  statuses.push('cancelled');
  fs.appendFileSync(parent.file, ' changed');
  await provider.completeSelectedWindow('child-0', 1);
  assert.equal(drawnAfter.length, statuses.length);
  assert.equal(drawn.refreshes, 3, 'an expired complete commit reply left its navigable rows drawn');
  assert.equal(resolve(0)?.complete, false);
});

const commitProofExpiries: Record<string, (host: ReturnType<typeof commitAllowanceHost>) => void> = {
  'its source changes': ({ children }) => fs.appendFileSync(children[1].file, ' changed'),
  'its context disappears': (host) => {
    host.provider.codexSubagents = [host.children[0]];
  },
};
for (const [change, expire] of Object.entries(commitProofExpiries))
  test(`a rejected commit reply redraws a complete commit row whose proof expired when ${change}`, async () => {
    const host = commitAllowanceHost(2);
    const { provider, parent, children, sessions, reply } = host;
    // The selected parent session owns two child contexts: the first holds a pending reply and the second a complete one.
    const agents = sessions.map(({ session, turns: [owned] }) => ({
      id: session.sessionId,
      description: 'worker',
      agentType: null,
      status: 'completed',
      commits: owned.commits.map((commit: any) => ({ ...commit })),
    }));
    const turns = [turn({ commits: [], agents: agents as any })];
    const statuses = ['complete', 'pending'];
    provider.progressiveWorker = {
      run: async (request: any, generation: number) =>
        reply(request, generation, statuses.shift()!, { parent: 0, child: 0 }),
    };
    // A child's own context has the same key as its context in the parent, so these replies serve the parent's rows.
    for (const index of [1, 0])
      await provider.hydrateCommitRepositories(
        sessions[index].session,
        sessions[index].turns,
        1,
        new AbortController().signal,
      );
    const proven = () => {
      provider.applyCommitRepositoryEvidence(parent, turns);
      return turns[0].agents.map((agent: any) => agent.commits[0].candidates?.complete);
    };
    assert.deepEqual(proven(), [false, true]);
    const drawn = selectCommitSession(provider, parent, turns);
    const drawnAfter: number[] = [];
    provider.progressiveWorker = {
      async run(request: any, generation: number) {
        drawnAfter.push(drawn.refreshes);
        assert.equal(request.child.file, children[0].file);
        // On the second request the first child grows, so its reply is rejected, and the complete proof expires.
        if (drawnAfter.length === 2) {
          fs.appendFileSync(children[0].file, ' changed');
          expire(host);
        }
        return reply(request, generation, 'pending', { parent: 0, child: 0 });
      },
    };
    await provider.completeSelectedWindow('parent', 1);
    await vi.waitFor(() => {
      assert.equal(drawnAfter.length, 2);
      assert.equal(provider.selectionWork, null);
    });
    assert.deepEqual(
      drawnAfter,
      [0, 0],
      'an unchanged pending reply beside a complete reply redrew the selected session',
    );
    assert.equal(drawn.refreshes, 1, 'a rejected commit reply left an expired complete row navigable');
    assert.equal(proven()[1], false);
  });

function commitAllowanceHost(count: number) {
  const directory = tempDir('host-commit-allowance-');
  const parentFile = path.join(directory, 'parent.jsonl');
  fs.writeFileSync(parentFile, 'p'.repeat(1000));
  const parent = { agent: 'codex', sessionId: 'parent', file: parentFile, size: 1000, mtimeMs: 1 };
  const children = Array.from({ length: count }, (_, index) => {
    const file = path.join(directory, `child-${index}.jsonl`);
    fs.writeFileSync(file, 'c'.repeat(100 + index));
    return {
      threadId: `child-${index}`,
      parentThreadId: 'parent',
      file,
      agentPath: '/root/worker',
      backgroundReview: false,
      openedAt: 1,
      startedAt: 1,
      threadSource: 'subagent',
    };
  });
  const sessions = children.map((child, index) => ({
    session: { ...parent, sessionId: child.threadId, file: child.file },
    turns: [
      turn({
        commits: [
          {
            sha: 'a'.repeat(7),
            printedSha: 'a'.repeat(40),
            subject: 'Recorded',
            at: 5,
            files: 1,
            added: 2,
            removed: 0,
            dir: null,
            place: null,
            repositoryEvidence: { dirs: [`C:/child-${index}/worktree`], at: 6, turnId: 'turn', complete: true },
          },
        ],
      }),
    ],
  }));
  const provider: any = Object.create(PanelProvider.prototype);
  provider.codexSubagents = children;
  provider.allSessions = () => [parent];
  provider.commitRepositoryReplies = new Map();
  provider.commitRepositoryReservations = new CommitRepositoryReservations();
  const reply = (request: any, generation: number, status: string, readBytes: { parent: number; child: number }) => ({
    generation,
    revision: request.parent.revision,
    value: {
      kind: 'commit-repositories',
      status,
      token: status === 'pending' || status === 'complete' ? `token-${generation}` : null,
      parent: request.parent,
      child: request.child,
      parserVersion: request.parserVersion,
      readBytes,
      covered: {
        parent: [0, status === 'complete' ? request.parent.revision.size : 0],
        child: [0, status === 'complete' ? request.child.revision.size : 0],
      },
      targets:
        status === 'complete'
          ? request.commits.map((commit: any) => ({
              sha: commit.sha,
              dirs: [commit.dirs[0].replace('/worktree', '')],
              occurrence: JSON.stringify([commit.turnId, commit.at, commit.evidenceAt, commit.sha, commit.dirs]),
            }))
          : [],
    },
  });
  // The fake worker follows the real allowance rule: an unread parent or a child without allowance ends the request.
  const worker = (childStatus: (request: any) => { status: string; child: number }) => {
    let parentRead = false;
    return (request: any, generation: number) => {
      if ((!parentRead && request.parentBytes === 0) || request.childBytes === 0)
        return reply(request, generation, 'exhausted', { parent: 0, child: 0 });
      const parentBytes = parentRead ? 0 : request.parent.revision.size;
      parentRead = true;
      const child = childStatus(request);
      return reply(request, generation, child.status, { parent: parentBytes, child: child.child });
    };
  };
  const resolve = (index: number) => {
    const { session, turns } = sessions[index];
    provider.applyCommitRepositoryEvidence(session, turns);
    return turns[0].commits[0].candidates;
  };
  const bytes = (file: string, sessionId: string) =>
    provider.commitRepositoryReservations.bytes({ file, sessionId, revision: provider.revisionOf({ file }) });
  return { provider, parent, children, sessions, reply, worker, resolve, bytes };
}

test('repeated pending commit replies charge the bytes read and resolve the commit', async () => {
  const { provider, sessions, worker, resolve } = commitAllowanceHost(1);
  let requests = 0;
  const model = worker(() =>
    ++requests > 200 ? { status: 'complete', child: 100 } : { status: 'pending', child: 4096 },
  );
  provider.progressiveWorker = { run: async (request: any, generation: number) => model(request, generation) };
  const { session, turns } = sessions[0];
  for (let generation = 1; generation < 400; generation++)
    if (!(await provider.hydrateCommitRepositories(session, turns, generation, new AbortController().signal))) break;
  assert.deepEqual(resolve(0), { dirs: ['C:/child-0'], complete: true });
  assert.equal(requests, 201);
});

test('children sharing one parent charge the parent only for bytes the worker read', async () => {
  const { provider, parent, children, sessions, worker, resolve, bytes } = commitAllowanceHost(131);
  const charges = new Map<string, number>();
  const install = () => {
    const model = worker((request) => ({ status: 'complete', child: request.child.revision.size }));
    provider.progressiveWorker = {
      async run(request: any, generation: number) {
        const result = model(request, generation);
        charges.set(request.child.file, result.value.readBytes.child);
        return result;
      },
    };
  };
  install();
  for (const [index, { session, turns }] of sessions.entries()) {
    // A replacement worker keeps no parent cursor, so its first request reads the parent again.
    if (index === 130) install();
    await provider.hydrateCommitRepositories(session, turns, index + 1, new AbortController().signal);
  }
  for (const index of sessions.keys())
    assert.deepEqual(resolve(index), { dirs: [`C:/child-${index}`], complete: true }, `child ${index}`);
  assert.equal(bytes(parent.file, 'parent'), 2 * 1000);
  for (const child of children) assert.equal(bytes(child.file, child.threadId), charges.get(child.file));
});

test('stale commit replies and complete replies without full coverage keep their whole charge', async () => {
  const { provider, parent, children, sessions, reply, bytes } = commitAllowanceHost(2);
  const replies = [
    (request: any, generation: number) => reply(request, generation, 'stale', { parent: 10, child: 10 }),
    (request: any, generation: number) => {
      const partial = reply(request, generation, 'complete', { parent: 10, child: 10 });
      partial.value.covered.child = [0, request.child.revision.size - 1];
      return partial;
    },
  ];
  let calls = 0;
  provider.progressiveWorker = {
    run: async (request: any, generation: number) => replies[calls++](request, generation),
  };
  for (const [index, { session, turns }] of sessions.entries())
    await provider.hydrateCommitRepositories(session, turns, index + 1, new AbortController().signal);
  assert.equal(calls, 2);
  assert.equal(bytes(parent.file, 'parent'), 1024 * 1024);
  for (const child of children) assert.equal(bytes(child.file, child.threadId), 512 * 1024);
});

test('concurrent commit requests on one parent wait so a nearly spent parent still funds both', async () => {
  const { provider, parent, sessions, worker, resolve } = commitAllowanceHost(2);
  const revision = provider.revisionOf(parent);
  // Settled reads leave the parent 512 KiB and 1 byte of its lifetime allowance.
  provider.commitRepositoryReservations.reserved.set(
    JSON.stringify([revision.dev, revision.ino, revision.size, revision.mtimeMs]),
    64 * 1024 * 1024 - 512 * 1024 - 1,
  );
  const model = worker((request) => ({ status: 'complete', child: request.child.revision.size }));
  const requests: any[] = [];
  let release!: () => void;
  const held = new Promise<void>((resolve) => (release = resolve));
  provider.progressiveWorker = {
    async run(request: any, generation: number) {
      requests.push(request);
      if (requests.length === 1) await held;
      return model(request, generation);
    },
  };
  const hydrate = (index: number) =>
    provider.hydrateCommitRepositories(
      sessions[index].session,
      sessions[index].turns,
      index + 1,
      new AbortController().signal,
    );
  const first = hydrate(0);
  await vi.waitFor(() => assert.equal(requests.length, 1));
  const second = hydrate(1);
  release();
  await Promise.all([first, second]);
  assert.equal(requests.length, 2);
  assert.ok(requests[1].parentBytes > 1, `the second request carried ${requests[1].parentBytes} parent bytes`);
  assert.deepEqual(resolve(0), { dirs: ['C:/child-0'], complete: true });
  assert.deepEqual(resolve(1), { dirs: ['C:/child-1'], complete: true });
  assert.deepEqual(
    requests.map((request) => request.parent.revision),
    [revision, revision],
  );
  assert.deepEqual(provider.revisionOf(parent), revision);
});

test('a lost commit reply frees its sources and a request aborted while it waits sends nothing', async () => {
  const { provider, parent, sessions, worker, resolve, bytes } = commitAllowanceHost(1);
  const model = worker((request) => ({ status: 'complete', child: request.child.revision.size }));
  const { session, turns } = sessions[0];
  let calls = 0;
  let release!: () => void;
  const held = new Promise<void>((resolve) => (release = resolve));
  provider.progressiveWorker = {
    async run(request: any, generation: number) {
      calls++;
      if (calls === 1) return null;
      if (calls === 2) await held;
      return model(request, generation);
    },
  };
  assert.equal(await provider.hydrateCommitRepositories(session, turns, 1, new AbortController().signal), true);
  const second = provider.hydrateCommitRepositories(session, turns, 2, new AbortController().signal);
  await vi.waitFor(() => assert.equal(calls, 2));
  const controller = new AbortController();
  const waiting = provider.hydrateCommitRepositories(session, turns, 3, controller.signal);
  controller.abort();
  assert.equal(await waiting, false);
  release();
  assert.equal(await second, false);
  assert.equal(calls, 2);
  assert.deepEqual(resolve(0), { dirs: ['C:/child-0'], complete: true });
  assert.equal(bytes(parent.file, 'parent'), 512 * 1024 + 1000);
});

test('a commit request aborted after it takes its free sources charges nothing and frees them', async () => {
  const { provider, parent, children, sessions, worker, bytes } = commitAllowanceHost(1);
  const model = worker((request) => ({ status: 'complete', child: request.child.revision.size }));
  let calls = 0;
  provider.progressiveWorker = {
    async run(request: any, generation: number, signal: AbortSignal) {
      calls++;
      return signal.aborted ? null : model(request, generation);
    },
  };
  const { session, turns } = sessions[0];
  const controller = new AbortController();
  const hydration = provider.hydrateCommitRepositories(session, turns, 1, controller.signal);
  controller.abort();
  assert.equal(await hydration, false);
  assert.equal(calls, 0);
  assert.equal(bytes(parent.file, 'parent'), 0);
  assert.equal(bytes(children[0].file, children[0].threadId), 0);
  assert.equal(provider.commitRepositoryReservations.active.size, 0);
});

test.each(['current', 'retained'])(
  'commit replies keep repeated object owners and unresolved occurrences separate: %s',
  async (placement) => {
    const directory = tempDir('host-commit-occurrences-');
    const parentFile = path.join(directory, 'parent.jsonl');
    const childFile = path.join(directory, 'child.jsonl');
    fs.writeFileSync(parentFile, 'parent');
    fs.writeFileSync(childFile, 'child');
    const parent = { agent: 'codex', sessionId: 'parent', file: parentFile, size: 6, mtimeMs: 1 };
    const child = {
      threadId: 'child',
      parentThreadId: 'parent',
      file: childFile,
      agentPath: '/root/worker',
      backgroundReview: false,
      openedAt: 1,
      startedAt: 1,
      threadSource: 'subagent',
    };
    const session = { ...parent, sessionId: 'child', file: childFile };
    const commits = ['first', 'second', 'unproved'].map((name, index) => ({
      sha: 'a'.repeat(7),
      printedSha: 'a'.repeat(40),
      subject: 'Recorded',
      at: 5 + index * 10,
      files: 1,
      added: 2,
      removed: 0,
      dir: null,
      place: null,
      repositoryEvidence: { dirs: [`C:/${name}/worktree`], at: 6 + index * 10, turnId: name, complete: true },
    }));
    const turns = commits.map((commit, index) =>
      turn({ promptId: commit.repositoryEvidence.turnId, startedAt: index + 1, commits: [commit] }),
    );
    const provider: any = Object.create(PanelProvider.prototype);
    provider.codexSubagents = [child];
    provider.allSessions = () => [parent];
    provider.history = new Map([
      ['child', { pages: [{ turns: placement === 'retained' ? turns.slice(1) : [], compactions: [] }] }],
    ]);
    provider.commitRepositoryReplies = new Map();
    provider.commitRepositoryReservations = new CommitRepositoryReservations();
    let demand: any[] = [];
    provider.progressiveWorker = {
      async run(request: any, generation: number) {
        demand = request.commits;
        return {
          generation,
          value: {
            kind: 'commit-repositories',
            status: 'complete',
            token: 'complete',
            parent: request.parent,
            child: request.child,
            parserVersion: request.parserVersion,
            readBytes: { parent: 0, child: 0 },
            covered: { parent: [0, request.parent.revision.size], child: [0, request.child.revision.size] },
            targets: request.commits.slice(0, 2).map((commit: any, index: number) => ({
              sha: commit.sha,
              dirs: [`C:/${index === 0 ? 'first' : 'second'}`],
              occurrence: JSON.stringify([commit.turnId, commit.at, commit.evidenceAt, commit.sha, commit.dirs]),
            })),
          },
        };
      },
    };
    const window = placement === 'retained' ? turns.slice(0, 1) : turns;
    await provider.hydrateCommitRepositories(session, window, 1, new AbortController().signal);
    provider.applyCommitRepositoryEvidence(session, window);
    assert.equal(demand.length, 3, 'retained occurrences were omitted from hydration');
    assert.deepEqual(
      turns.map((one) => one.commits[0].candidates),
      [
        { dirs: ['C:/first'], complete: true },
        { dirs: ['C:/second'], complete: true },
        { dirs: ['C:/unproved/worktree'], complete: false },
      ],
    );
    turns[1].commits[0].dir = 'C:/second';
    fs.appendFileSync(parentFile, ' changed');
    provider.applyCommitRepositoryEvidence(session, window);
    assert.equal(turns[1].commits[0].dir, null, 'retained navigation survived a parent-only append');
    assert.ok(turns.every((one) => one.commits[0].candidates?.complete === false));
  },
);

