test('the panel narrows the command list the way the tested rule does', () => {
  sourceMatch(
    browserComposerSource,
    /historyPress, isSendChord, lineIntent, lineRange, matchCommandNames, PATH_COMPLETION_DEBOUNCE_MS, pathToken,[\s\S]*from '\.\.\/domain\/composer-editing\.ts';/,
  );
  const match = matchCommandNames;
  const names = PANEL_COMMANDS.map((c) => c.name);
  // Check command matching at every caret position.
  for (const text of TYPED) {
    for (let caret = 0; caret <= text.length; caret++) {
      const found = promptToken('claude', text, caret);
      if (!found) {
        continue;
      }
      assert.deepEqual(
        match(names, found.typed),
        matchCommands(PANEL_COMMANDS, found.typed).map((c) => c.name),
        `the two copies offer different commands for "${text}" with the caret at ${caret}`,
      );
    }
  }
  // Explicit parser results also catch mistakes shared by both matchers.
  assert.deepEqual(promptToken('claude', '/co', 3), { prefix: '/', typed: 'co', start: 0, end: 3 });
  assert.equal(promptToken('claude', '/co ', 4), null, 'the space that ends the name shuts the menu');
  assert.deepEqual(
    promptToken('claude', 'see /usr', 8),
    { prefix: '/', typed: 'usr', start: 4, end: 8 },
    'a slash that opens a word is a command wherever in the sentence it sits',
  );
  assert.equal(promptToken('claude', 'a/b', 3), null, 'a slash inside a word is a path, not a command');
  assert.deepEqual(
    match(names, 'co'),
    ['commit', 'compact', 'code-review', 'safe-compact'],
    'a name that starts with what was typed comes before one that only contains it',
  );
  assert.deepEqual(match(names, 'compact'), ['compact', 'safe-compact']);
  assert.deepEqual(match(names, 'review'), ['code-review']);
  assert.deepEqual(match(names, 'zzz'), []);
  assert.deepEqual(match(names, ''), names, 'a reader who has typed only the slash is asking what there is');
});

test('the Composer detects one complete path token at the caret', () => {
  assert.deepEqual(pathToken('~/Projects/wo', 13), { typed: '~/Projects/wo', start: 0, end: 13 });
  assert.deepEqual(pathToken("'./with space/wo", 16), { typed: './with space/wo', start: 1, end: 16 });
  assert.deepEqual(pathToken('../src/wo', 9), { typed: '../src/wo', start: 0, end: 9 });
  assert.deepEqual(pathToken('C:\\work\\wo', 10), { typed: 'C:\\work\\wo', start: 0, end: 10 });
  assert.deepEqual(pathToken('\\\\server\\share\\wo', 17), { typed: '\\\\server\\share\\wo', start: 0, end: 17 });
  assert.deepEqual(
    pathToken('/compact', 8),
    { typed: '/compact', start: 0, end: 8 },
    'the browser gives a matching slash-command row priority over this path candidate',
  );
  assert.equal(pathToken('plain', 5), null);
  assert.equal(pathToken('./src/file', 4), null, 'the caret must end the token');
});

test('the Composer replaces a completed quoted path without taking its delimiters', () => {
  for (const quote of ['"', "'", '`']) {
    const value = `${quote}./with space/wo${quote}`;
    assert.deepEqual(pathToken(value, value.length), {
      typed: './with space/wo',
      start: 1,
      end: value.length - 1,
    });
  }
  const open = '"./with space/wo';
  assert.deepEqual(pathToken(open, open.length), {
    typed: './with space/wo',
    start: 1,
    end: open.length,
  });
});

test('a command the panel answers itself opens a menu instead of going to the agent', () => {
  // The host handles panel commands before sending prompts to the agent.
  sourceMatch(
    panelHostSource,
    /const opens = panelCommand\(text\);/,
    'the provider no longer asks whether a command is one the panel answers itself',
  );
  const send = panelHostSource.slice(panelHostSource.indexOf('private sendPrompt('));
  const asks = send.indexOf('panelCommand(');
  const sends = send.indexOf('sendAction(');
  assert.ok(asks >= 0 && sends >= 0, 'sendPrompt no longer both asks and sends');
  assert.ok(asks < sends, 'the prompt is sent before the panel is asked whether it answers the command itself');
  sourceMatch(
    send.slice(0, sends),
    /type: 'openPick'/,
    'nothing tells the panel which control to open, so the command clears the box and does nothing',
  );
  sourceMatch(
    composerControlsSource,
    /type: 'openControl', control: pick\.control, session: props\.view!\.sessionId/,
    "pressing Servers opens cached rows without asking for the selected owner's live state",
  );

  // The browser opens the control named by the host.
  sourceMatch(
    panelHandler('openPick'),
    /composerControlsRenderer\.openPick\(msg\.control\)/,
    'the panel reads the message and opens something other than the control it names',
  );
});

