// Count imperative native-control construction in the selected browser modules.
test('vanilla-owned interactive construction stays below the migration ceiling', () => {
  const sources = [
    ts.createSourceFile('panel.ts', script, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS),
    ts.createSourceFile('composer.ts', browserComposerSource, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS),
    ts.createSourceFile(
      'composer-presentation.ts',
      browserComposerPresentationSource,
      ts.ScriptTarget.Latest,
      true,
      ts.ScriptKind.TS,
    ),
  ];
  const nativeTags = new Set(['button', 'input', 'select', 'textarea']);
  const createsNativeControl = (node: ts.Expression): boolean => {
    if (ts.isStringLiteral(node)) {
      return nativeTags.has(node.text);
    }
    if (ts.isParenthesizedExpression(node)) {
      return createsNativeControl(node.expression);
    }
    return (
      ts.isConditionalExpression(node) && (createsNativeControl(node.whenTrue) || createsNativeControl(node.whenFalse))
    );
  };
  let controls = 0;
  const visit = (node: ts.Node): void => {
    if (ts.isCallExpression(node) && node.arguments[0] && createsNativeControl(node.arguments[0])) {
      const call = node.expression;
      if (
        (ts.isIdentifier(call) && call.text === 'el') ||
        (ts.isPropertyAccessExpression(call) &&
          ts.isIdentifier(call.expression) &&
          call.expression.text === 'document' &&
          call.name.text === 'createElement')
      ) {
        controls++;
      }
    }
    ts.forEachChild(node, visit);
  };
  for (const source of sources) {
    visit(source);
  }
  // Keep imperative native-control construction within the migration ceiling.
  assert.ok(
    controls <= 38,
    `panel.ts and typed browser owners imperatively construct ${controls} native controls, above the migration ceiling`,
  );
  sourceDoesNotMatch(
    browserComposerSource,
    /document\.createElement\(['"](?:button|input|select|textarea)['"]\)/,
    'the Composer moved an owned native control back into vanilla construction',
  );
  sourceDoesNotMatch(
    script,
    /function (?:drawCustomLauncher|drawLauncherMenu|launcherSelect|writePicker|addPicker)\(/,
    'panel.ts regained an interactive surface owned by the Preact chrome',
  );
});

// Return declarations from top-level rules with this exact selector list.
// Selector prefixes and rules inside at-rules do not match.
function styleRule(selector: string): string {
  const declarations = cssDeclarations(styleSource, selector);
  assert.ok(
    styleRules().some((rule) => rule.selector === selector && !rule.conditions.length),
    `the stylesheet has no "${selector}" rule, so this guard cannot see it`,
  );
  // Resolve panel text placeholders in declaration values.
  return fillPanelText(declarations.map((declaration) => `${declaration};`).join(' '), panelValues());
}

// Cache all stylesheet rules, including rules inside at-rules.
let styleRuleList: CssRule[] | undefined;
function styleRules(): CssRule[] {
  styleRuleList ??= cssContract(styleSource);
  return styleRuleList;
}

// Split every stylesheet rule's selector list.
function styleSelectors(): string[] {
  return styleRules().flatMap((rule) => rule.selector.split(', '));
}

// Join declarations from rules whose selector list contains this exact selector.
function styleRulesNaming(selector: string): string {
  const found = styleRules().filter((rule) => rule.selector.split(', ').includes(selector));
  assert.ok(found.length, `no stylesheet rule names "${selector}", so this guard cannot see it`);
  return found
    .flatMap((rule) => rule.declarations)
    .map((declaration) => `${declaration};`)
    .join(' ');
}

// Match declaration prefixes in every stylesheet rule.
function styleDeclares(start: string): boolean {
  return styleRules().some((rule) => rule.declarations.some((declaration) => declaration.startsWith(start)));
}

// Read the session list card's left padding from the stylesheet.
function railCardIndent(): number {
  const found = /padding: 7px 10px 7px (\d+)px;/.exec(styleRule('.railcard'));
  assert.ok(found, 'the card no longer reserves the left padding the unread dot is drawn in');
  return Number(found[1]);
}
function borderedCardIndent(status: string): number {
  const rule = styleRule(`.railcard.${status}`);
  assert.match(rule, /border-left: 3px solid/, `a ${status} card no longer wears the border this indent pays for`);
  const found = /padding-left: (\d+)px;/.exec(rule);
  assert.ok(found, `a ${status} card writes no left padding of its own, so its border pushes the text right`);
  return Number(found[1]);
}

interface FakeElement {
  tag: string;
  className: string | null;
  textContent: string;
  style: Record<string, string>;
  attributes: Record<string, string>;
  dataset: Record<string, string>;
  children: FakeElement[];
  classList: {
    add(name: string): void;
    remove(name: string): void;
    contains(name: string): boolean;
    toggle(name: string, on?: boolean): void;
  };
  src?: string;
  alt?: string;
  title?: string;
  hidden?: boolean;
  // Text fields expose their value, placeholder, row count, and label target.
  value?: string;
  placeholder?: string;
  rows?: number;
  id?: string;
  // Track registered listeners and focus calls.
  listeners: Record<string, ((e: unknown) => void)[]>;
  focused: number;
  appendChild(child: FakeElement): FakeElement;
  // Comment editors insert the quoted text before the existing label.
  readonly firstChild: FakeElement | null;
  insertBefore(child: FakeElement, before: FakeElement | null): FakeElement;
  setAttribute(name: string, value: string): void;
  removeAttribute(name: string): void;
  getAttribute(name: string): string | null;
  addEventListener(type: string, fn: (e: unknown) => void): void;
  focus(): void;
  querySelector(selector: string): FakeElement | null;
  querySelectorAll(selector: string): FakeElement[];
  [extra: string]: unknown;
}

// Match one class or one tag against a fake element.
function fakeMatches(node: FakeElement, selector: string): boolean {
  if (selector.startsWith('.')) {
    return (node.className || '').split(' ').includes(selector.slice(1));
  }
  return node.tag === selector;
}
function fakeFind(node: FakeElement, selector: string): FakeElement | null {
  for (const child of node.children) {
    if (fakeMatches(child, selector)) {
      return child;
    }
    const deeper = fakeFind(child, selector);
    if (deeper) {
      return deeper;
    }
  }
  return null;
}

// Find matching descendants in document order across a comma-separated selector list.
function fakeFindAll(node: FakeElement, selector: string): FakeElement[] {
  const wanted = selector
    .split(',')
    .map((one) => one.trim())
    .filter(Boolean);
  const found: FakeElement[] = [];
  for (const child of node.children) {
    if (
      wanted.some((one) => (one === '[data-control]' ? child.dataset.control !== undefined : fakeMatches(child, one)))
    ) {
      found.push(child);
    }
    found.push(...fakeFindAll(child, selector));
  }
  return found;
}

// Clearing textContent removes children.
// classList.add preserves existing classes.
const fakeDocument = {
  createElement(tag: string): FakeElement {
    let text = '';
    const node: FakeElement = {
      tag,
      className: null,
      get textContent() {
        return text;
      },
      set textContent(next: string) {
        text = next;
        if (next === '') {
          node.children.length = 0;
        }
      },
      style: {},
      attributes: {},
      // Clock updates read timestamps from data attributes.
      dataset: {},
      children: [],
      classList: {
        add(name: string) {
          if (!node.classList.contains(name)) {
            node.className = node.className ? node.className + ' ' + name : name;
          }
        },
        remove(name: string) {
          node.className = (node.className || '')
            .split(' ')
            .filter((c) => c !== name)
            .join(' ');
        },
        contains(name: string) {
          return (node.className || '').split(' ').includes(name);
        },
        toggle(name: string, on?: boolean) {
          const want = on === undefined ? !node.classList.contains(name) : on;
          if (want) {
            node.classList.add(name);
          } else {
            node.classList.remove(name);
          }
        },
      },
      listeners: {},
      focused: 0,
      appendChild(child: FakeElement) {
        node.children.push(child);
        return child;
      },
      get firstChild() {
        return node.children[0] ?? null;
      },
      insertBefore(child: FakeElement, before: FakeElement | null) {
        const at = before ? node.children.indexOf(before) : -1;
        if (at < 0) {
          node.children.push(child);
        } else {
          node.children.splice(at, 0, child);
        }
        return child;
      },
      setAttribute(name: string, value: string) {
        node.attributes[name] = value;
      },
      removeAttribute(name: string) {
        delete node.attributes[name];
      },
      getAttribute(name: string) {
        return Object.prototype.hasOwnProperty.call(node.attributes, name) ? node.attributes[name] : null;
      },
      addEventListener(type: string, fn: (e: unknown) => void) {
        (node.listeners[type] = node.listeners[type] || []).push(fn);
      },
      focus() {
        node.focused += 1;
      },
      querySelector(selector: string) {
        return fakeFind(node, selector);
      },
      querySelectorAll(selector: string) {
        return fakeFindAll(node, selector);
      },
    };
    return node;
  },
  createTextNode(value: string): FakeElement {
    const node = fakeDocument.createElement('#text');
    node.textContent = value;
    return node;
  },
  // This fixture treats every element as attached.
  contains(_node: unknown): boolean {
    return true;
  },
};

