test('the content policy lets the icon theme font and a theme image through', () => {
  // The content policy must admit icon fonts and theme images.
  const marker = 'const csp = [';
  const from = panelDevelopmentSource.indexOf(marker);
  assert.notEqual(
    from,
    -1,
    `paneldevelopment.ts no longer contains "${marker}", so this guard cannot see the content policy`,
  );
  const csp = panelDevelopmentSource.slice(from, panelDevelopmentSource.indexOf('].join', from));
  assert.notEqual(csp.length, 0, 'the content policy list has no end, so this guard is reading the rest of the file');
  sourceMatch(
    csp,
    /`img-src \$\{options\.cspSource\}`/,
    'the content policy no longer allows a theme image, so every image icon theme draws broken pictures',
  );
  sourceMatch(
    csp,
    /`font-src \$\{options\.cspSource\}`/,
    'the content policy no longer allows the icon theme font, so every glyph draws as an empty box',
  );
  sourceMatch(
    csp,
    /"default-src 'none'"/,
    'the content policy no longer starts by blocking everything, so the two rules above grant nothing',
  );
});

