test('the selected session is the progressive read target', () => {
  // Check the host's selected-session target and scheduling order.
  const marker = 'private shownSessions(';
  const from = panelHostSource.indexOf(marker);
  assert.notEqual(from, -1, `panelhost.ts no longer contains "${marker}", so this guard cannot see the cut`);
  const body = memberFrom(panelHostSource, from);
  sourceMatch(
    body,
    /new Set\(\[this\.showing, \.\.\.\(this\.hostSessions\?\.values\(\) \?\? \[\]\)\]/,
    'background work omits a session retained in a side-by-side panel',
  );
  sourceMatch(
    body,
    /return all\.filter\(\(session\) => showing\.has\(session\.sessionId\)\);/,
    'background work reads sessions no open panel selected',
  );
  const progressive = memberFrom(panelHostSource, panelHostSource.indexOf('private async prepareProgressive('));
  sourceMatch(
    progressive,
    /sort\(\(a, b\) => Number\(b\.sessionId === this\.showing\) - Number\(a\.sessionId === this\.showing\)\)/,
    'the selected session is not scheduled before the retained recent session',
  );
});

