// Comment operations apply to the current store rather than replacing it with a host's saved copy.
test('clearing empties one session and leaves the other agents alone', () => {
  // Clearing sent comments targets one session.
  const note = (id: string, sessionId: string, at: number) => ({
    id,
    sessionId,
    turnKey: sessionId + ':100',
    part: 'summary',
    quote: '',
    note: 'comment ' + id,
    headline: 'Rewrote the parser',
    sessionTitle: 'The parser',
    turnAt: 100,
    at,
  });
  let held = applyComment([], { op: 'write', note: note('a', 's1', 1) });
  held = applyComment(held, { op: 'write', note: note('b', 's1', 2) });
  held = applyComment(held, { op: 'write', note: note('c', 's2', 3) });
  held = applyComment(held, { op: 'clear', sessionId: 's1' });
  // Preserve comments belonging to other sessions.
  assert.deepEqual(
    held.map((c) => c.id),
    ['c'],
    'clearing one session reached into another',
  );
  // Clearing an absent session preserves the existing comments.
  assert.deepEqual(
    applyComment(held, { op: 'clear', sessionId: 's9' }).map((c) => c.id),
    ['c'],
  );
  // Reject clear operations without a valid session ID.
  for (const junk of [{ op: 'clear' }, { op: 'clear', sessionId: '' }, { op: 'clear', sessionId: 7 }]) {
    assert.deepEqual(
      applyComment(held, junk).map((c) => c.id),
      ['c'],
      'an unnamed session cleared everything: ' + JSON.stringify(junk),
    );
  }
});

test('both agents reach one list, and each session is read and named by its own reader', () => {
  const marker = 'private allSessions(reuseCatalog = false)';
  const from = panelHostSource.indexOf(marker);
  assert.notEqual(from, -1, `panelhost.ts no longer contains "${marker}", so this guard cannot see the merge`);
  const merge = memberFrom(panelHostSource, from);
  sourceMatch(merge, /sessionFilesFor\(projectsRoot\(\)/, 'the list no longer holds Claude Code sessions');
  sourceMatch(merge, /codexSessionFiles\(codexSessionsRoot\(\)/, 'the list no longer holds Codex sessions');
  sourceMatch(
    merge,
    /const scope = this\.repositoryScope\.snapshot\(workspaceFolders\);/,
    'the listing never asks Git which registered worktrees belong to the open project',
  );
  sourceMatch(
    merge,
    /sessionFilesFor\(projectsRoot\(\), scope\.roots,[\s\S]*workspaceFolders\);/,
    'Claude discovery either omits worktree roots or trusts a missing cwd outside the open folder',
  );
  sourceMatch(
    merge,
    /codexSessionFiles\(codexSessionsRoot\(\), scope\.roots,/,
    'Codex discovery does not use the same registered worktree scope as Claude',
  );
  sourceMatch(
    merge,
    /hit && sameSessionRevision\(hit, session\)/,
    'a missing Claude cwd is retained after its incomplete transcript grows',
  );
  sourceMatch(
    merge,
    /if \(hit\?\.cwd\) \{ return hit\.cwd; \}[\s\S]*hit && sameSessionRevision\(hit, session\)/,
    'a known Claude cwd is read again or replaced when its transcript grows',
  );
  sourceDoesNotMatch(
    panelHostSource,
    /automaticFirstProjectProfile/,
    'startup creates a draft before the reader presses New',
  );
  // Match the combined catalog through its return statement.
  sourceMatch(
    merge,
    /const walkedSessions = orderSessionCatalog\(\[\.\.\.listed, \.\.\.this\.claudeChildren, \.\.\.codex\],[\s\S]*this\.activityFor\(session\)\);[\s\S]*return walkedSessions;/,
    'what the panel gets back is not both lists in one order, whatever was listed above it',
  );
  // Retain rollout metadata and trim its cache against walked files.
  sourceMatch(
    merge,
    /this\.codexMetas\.get\(file\)/,
    'the panel keeps no opening record, so it reads every head again on every poll',
  );
  sourceMatch(
    merge,
    /staleMetas\(this\.codexMetas\.keys\(\), listing\.walked\)/,
    'the meta cache is trimmed against something other than the walk, which empties it',
  );
  const trims = (panelHostSource.match(/this\.codexMetas\.delete\(/g) ?? []).length;
  assert.equal(
    trims,
    1,
    'the meta cache is trimmed somewhere else as well, and only one of the two can be measuring it against the walk',
  );
  const workerEntry = fs.readFileSync(path.join(__dirname, 'progressiveworker-entry.ts'), 'utf8');
  sourceMatch(
    workerEntry,
    /session\.agent === 'claude'[\s\S]*readClaudeSessionIncremental[\s\S]*readCodexSessionIncremental/,
    'the progressive worker does not dispatch each session to its own reader',
  );
  sourceMatch(
    panelHostSource,
    /private readFor\([\s\S]*?const hit = this\.cache\.get\(session\.file\);/,
    'the host does not expose only an accepted worker window to card collection',
  );
});

