// Dispatch edges connect catalog members for cost attribution and agent-run classification.
test("the host counts a dispatched session in its parent's cost once and files it by who asked for it", async () => {
  const folder = tempDir('dispatch-cost-');
  const bucket = (input: number) =>
    aggregateUsageEvents([
      {
        timestamp: Date.parse('2026-08-31T10:00:00'),
        agent: 'claude',
        provider: null,
        model: 'claude-opus-5',
        contextWindow: null,
        billingClass: 'metered',
        inferenceClass: null,
        serviceTier: null,
        reportedCost: null,
        requestKey: null,
        usage: { input, cacheWrite1h: 0, cacheWrite5m: 0, cacheWrite30m: 0, cacheRead: 0, output: 0, thinking: 0 },
      },
    ]);
  const inputs: Record<string, number> = {
    parent: 100_000,
    child: 150_000,
    hidden: 70_000,
    stray: 30_000,
    helper: 40_000,
    worker: 20_000,
  };
  const fileOf = (id: string) => path.join(folder, `${id}.jsonl`);
  const records = Object.entries(inputs).map(([id, input]) => ({
    file: fileOf(id),
    workspace: 'w',
    size: 10,
    mtimeMs: 1,
    offset: 10,
    trailing: '',
    buckets: [],
    indexedAt: 1,
    complete: true,
    lifetimeBuckets: bucket(input),
  }));
  const session = (sessionId: string) => ({ sessionId, file: fileOf(sessionId), agent: 'claude' });
  const launch = (parentSessionId: string, sessionId: string, toolUseId = 'toolu_1', owned = false) => ({
    kind: 'dispatch',
    agent: 'claude',
    parentSessionId,
    sessionId,
    file: fileOf(sessionId),
    toolUseIds: [toolUseId],
    name: null,
    owned,
  });
  type Host = {
    saved: ReturnType<typeof normalizePanelState>;
    claudeChildReferences: unknown[];
    startedHere: Set<string>;
    projectSpendRevision: number;
    projectSpendFiles: unknown[];
    projectSpendVisibleFiles: unknown[];
    projectSpendIndexing: boolean;
    updateSessionSpendSources(codex: unknown[], sessions: unknown[]): void;
    sessionParentEdges(sessions: unknown[]): { edges: ReadonlyMap<string, unknown> };
    parentOfShown(session: string): { id: string; relation: string } | undefined;
    lifetimeFiguresBySession(): {
      costs: Record<string, { dollars: number | null; partial: boolean }>;
      stats: Record<string, { label?: string }[]>;
    };
    agentRunFor(session: unknown, edges: ReadonlyMap<string, unknown>): boolean;
    dispatchFacts: Map<string, { person: boolean }>;
    metaFor(session: unknown): { agentRun: boolean | null | undefined };
  };
  // Map Claude subagent IDs to their parent IDs.
  const hostWith = (
    references: unknown[],
    listed = ['parent', 'child'],
    files: unknown[] = records,
    children: Record<string, string> = {},
  ) => {
    const host = Object.assign(Object.create(PanelProvider.prototype), {
      claudeChildReferences: references,
      sessionParents: null,
      startedHere: new Set<string>(),
      claudeSpendSources: [
        ...Object.keys(inputs).map((id) => ({ sessionId: id, file: fileOf(id), primary: true })),
        ...Object.entries(children).map(([child, parent]) => ({
          sessionId: parent,
          file: fileOf(child),
          primary: false,
        })),
      ],
      claudeChildren: Object.entries(children).map(([child, parent]) => ({
        ...session(child),
        parentSessionId: parent,
        childTranscript: true,
      })),
      codexSubagents: [],
      subagentDirectories: { files: () => [] },
      sessionSpendSourceIndex: new SessionSpendSourceIndex(),
      sessionSpendSources: [],
      projectSpendRevision: 0,
      lifetimeFigures: new SessionFiguresCache(),
      projectSpendHydrated: true,
      projectSpendIndexing: false,
      projectSpendOffers: new Set(),
      projectSpendQueued: new Set<string>(),
      projectSpendFiles: files,
      projectSpendVisibleFiles: files,
      metaFor: () => ({ agentRun: false }),
      dispatchFacts: new Map(),
      saved: normalizePanelState(null),
      sessionRows: ['parent', 'child'].map((id) => ({ id, label: id })),
      sessionParentEdgeSet: null,
    }) as Host;
    host.updateSessionSpendSources([], listed.map(session));
    return host;
  };
  const cost = (host: Host, id: string) => host.lifetimeFiguresBySession().costs[id]?.dollars ?? null;
  const alone = hostWith([]);
  const parent = cost(alone, 'parent');
  const child = cost(alone, 'child');
  assert.ok(parent !== null && child !== null && parent > 0 && child > 0, 'the fixture priced nothing');
  const reader = hostWith([]);
  reader.saved.readerParents = { child: 'parent' };
  reader.updateSessionSpendSources([], ['parent', 'child'].map(session));
  assert.equal(cost(reader, 'parent'), parent);
  assert.equal(cost(reader, 'child'), child);
  assert.equal(reader.sessionParentEdges(['parent', 'child'].map(session)).edges.size, 0);
  assert.equal(
    reader.agentRunFor(session('child'), reader.sessionParentEdges(['parent', 'child'].map(session)).edges),
    false,
  );

  for (const references of [
    [launch('parent', 'child')],
    [launch('parent', 'child'), launch('parent', 'child', 'toolu_2')],
  ]) {
    const host = hostWith(references);
    assert.ok(
      Math.abs((cost(host, 'parent') ?? 0) - (parent + child)) < 1e-9,
      `${references.length} launch results put ${cost(host, 'parent')} on the parent, not ${parent} plus the child's ${child}`,
    );
    assert.equal(cost(host, 'child'), child, "the dispatched session's own cost moved");
  }

  // Dispatch cycles count each transcript once.
  const cycle = hostWith([launch('parent', 'child'), launch('child', 'parent', 'toolu_9')]);
  for (const id of ['parent', 'child']) {
    assert.ok(
      Math.abs((cost(cycle, id) ?? 0) - (parent + child)) < 1e-9,
      `a dispatch cycle put ${cost(cycle, id)} on ${id}, not ${parent} plus ${child}`,
    );
  }

  // A subagent's dispatch contributes the child session and its subagent once.
  const family = { helper: 'parent', worker: 'child' };
  const members = ['parent', 'helper', 'child', 'worker'];
  const unlinked = hostWith([], members, records, family);
  const chained = hostWith([launch('helper', 'child')], members, records, family);
  const top = (cost(unlinked, 'parent') ?? 0) + (cost(unlinked, 'child') ?? 0);
  assert.ok(cost(unlinked, 'parent')! > parent, "the subagent's file never reached the top session");
  assert.ok(
    Math.abs((cost(chained, 'parent') ?? 0) - top) < 1e-9,
    `a subagent's dispatch put ${cost(chained, 'parent')} on the top session, not ${top}`,
  );

  // An incomplete child record leaves the parent cost as a lower bound.
  const writing = records.map((record) =>
    record.file === fileOf('child') ? { ...record, trailing: '{"type":' } : record,
  );
  const growing = hostWith([launch('parent', 'child')], ['parent', 'child'], writing);
  const figure = (host: Host) => ({
    cost: host.lifetimeFiguresBySession().costs.parent,
    label: host.lifetimeFiguresBySession().stats.parent?.[0]?.label ?? '',
  });
  assert.deepEqual(figure(growing).cost, { dollars: parent, partial: true }, 'a growing child left the parent whole');
  assert.match(figure(growing).label, /[+]$/, 'a growing child drew no lower-bound mark on its parent');
  growing.projectSpendFiles = records;
  growing.projectSpendVisibleFiles = records;
  assert.equal(figure(growing).cost.partial, false, 'the lower bound outlived the completed record');
  assert.ok(
    Math.abs((figure(growing).cost.dollars ?? 0) - (parent + child)) < 1e-9,
    'the completed child never joined',
  );
  assert.doesNotMatch(figure(growing).label, /[+]$/, 'the lower-bound mark outlived the completed record');

  // An open child turn keeps the parent cost partial until completion or exclusion by the history limit.
  const turn = { finished: false, error: false, interrupted: false, endedAt: 1, startedAt: 1 };
  const withTurn = (outcome: typeof turn) =>
    records.map((record) => (record.file === fileOf('child') ? { ...record, outcome } : record));
  let limit: number | null = null;
  const running = Object.assign(hostWith([launch('parent', 'child')], ['parent', 'child'], withTurn(turn)), {
    projectSpendHistoryCutoff: () => limit,
  });
  assert.deepEqual(
    figure(running).cost,
    { dollars: parent, partial: true },
    'a running child between two writes left the parent whole',
  );
  assert.match(figure(running).label, /[+]$/, 'a running child between two writes drew no lower-bound mark');
  const joined = { dollars: parent + child, partial: false };
  running.projectSpendFiles = withTurn({ ...turn, finished: true });
  running.projectSpendVisibleFiles = running.projectSpendFiles;
  assert.deepEqual(figure(running).cost, joined, 'the lower bound outlived the ended turn');
  running.projectSpendFiles = withTurn(turn);
  running.projectSpendVisibleFiles = running.projectSpendFiles;
  assert.equal(figure(running).cost.partial, true, 'a turn that opened again left the parent whole');
  limit = 10_000;
  assert.deepEqual(figure(running).cost, joined, 'a running child the history limit skips held its parent');

  // A child record ending mid-line keeps the parent partial until the history limit excludes it.
  let stale: number | null = null;
  const stopped = Object.assign(hostWith([launch('parent', 'child')], ['parent', 'child'], writing), {
    projectSpendHistoryCutoff: () => stale,
  });
  assert.equal(
    figure(stopped).cost.partial,
    true,
    'a child cut off mid-line inside the history limit left the parent whole',
  );
  assert.match(figure(stopped).label, /[+]$/, 'a child cut off mid-line inside the history limit drew no mark');
  stale = 10_000;
  assert.deepEqual(figure(stopped).cost, joined, 'a child cut off mid-line past the history limit held its parent');
  assert.doesNotMatch(figure(stopped).label, /[+]$/, 'a child cut off mid-line past the history limit kept the mark');

  // A dispatched child outside the catalog contributes no cost or partial marker.
  for (const files of [records, writing]) {
    const gone = hostWith([launch('parent', 'child')], ['parent'], files);
    assert.deepEqual(
      figure(gone).cost,
      { dollars: parent, partial: false },
      'a child outside the catalog moved its parent',
    );
    assert.doesNotMatch(figure(gone).label, /[+]$/, 'a child outside the catalog marked its parent');
  }

  // Skipped children leave the parent cost complete.
  // Queued children keep it partial until the ledger releases them.
  const cutoff = 10_000;
  const age = (id: string, mtimeMs: number) => fs.utimesSync(fileOf(id), mtimeMs / 1000, mtimeMs / 1000);
  for (const id of Object.keys(inputs)) {
    fs.writeFileSync(fileOf(id), '');
    age(id, cutoff / 10);
  }
  const unread = records.filter((record) => record.file !== fileOf('child'));
  const rail: { dollars: number | null; partial: boolean }[] = [];
  const waiting = Object.assign(hostWith([launch('parent', 'child')], ['parent', 'child'], unread), {
    projectSpendWorkspace: folder,
    projectSpendStorageDir: folder,
    projectSpendQueue: [],
    projectSpendTick: null,
    codexSpendSources: [],
    projectSpendHistoryCutoff: () => cutoff,
    postProjectSpend: () => {},
    // Capture the parent cost supplied to the session list.
    postRail(this: Host) {
      rail.push(this.lifetimeFiguresBySession().costs.parent);
    },
  }) as unknown as Host & {
    projectSpendOffers: Set<unknown>;
    projectSpendQueued: Set<string>;
    projectSpendTick: unknown;
    scheduleProjectSpendIndex(listed: ReadonlyMap<string, unknown>, only: null): void;
    queueProjectSpendIndex(): void;
    restartProjectSpendOffer(): void;
  };
  const whole = { dollars: parent, partial: false };
  waiting.scheduleProjectSpendIndex(new Map(), null);
  (waiting as unknown as { postRail(): void }).postRail();
  assert.deepEqual(rail, [whole], 'the rail drew a lower bound for a skipped child while an offer waited');
  await vi.waitFor(() => assert.equal(waiting.projectSpendOffers.size, 0));
  assert.equal(waiting.projectSpendQueued.size, 0, 'the offer queued a child the history limit skips');
  assert.deepEqual(rail, [whole], 'the offer redrew the rail with no figure moved');
  // Hold the queued child by supplying an existing tick.
  waiting.projectSpendTick = {};
  age('child', cutoff * 2);
  waiting.queueProjectSpendIndex();
  assert.deepEqual(rail.at(-1), { dollars: parent, partial: true }, 'a queued child drew no lower bound on the rail');
  age('child', cutoff / 10);
  waiting.restartProjectSpendOffer();
  assert.deepEqual(rail.at(-1), whole, 'the rail kept the lower bound after the ledger let the child go');

  // Finishing ledger indexing refreshes the session list after a selection render reads the changed figures.
  type Rail = { stats: Record<string, { label?: string }[]> };
  type Drawn = Host & {
    projectSpendIndexing: boolean;
    projectSpendQueued: Set<string>;
    postRail(inputsChanged: boolean): void;
    railInputFor(
      counts: Map<string, unknown>,
      statuses: Map<string, unknown>,
      open: Map<string, number>,
      now: number,
    ): unknown;
    finishProjectSpendIndex(): void;
  };
  const childKey = normalizeSpendFile(fileOf('child'));
  let passed: number | null = null;
  for (const [name, files, queued, move] of [
    ['the ledger let the queued child go', unread, true, (host: Drawn) => host.projectSpendQueued.delete(childKey)],
    ['the history limit passed the running child', withTurn(turn), false, () => (passed = 10_000)],
  ] as const) {
    const rails: Rail[] = [];
    passed = null;
    const drawn = Object.assign(hostWith([launch('parent', 'child')], ['parent', 'child'], files), {
      projectSpendHistoryCutoff: () => passed,
      postProjectSpend: () => {},
      projectSpendRailOwed: false,
      ...(() => {
        const host = {};
        return { hosts: [host], readyHosts: new Set([host]) };
      })(),
      sendToHost: (_host: unknown, message: Rail) => rails.push(message),
      catalog: null,
      railRevision: 0,
      lastRailRevision: -1,
      lastRailDay: '',
      lastRailKey: null,
      lastRailAdoptionsJson: '',
      railOrder: [],
      sessionAliases: new Map(),
      unreadCounts: () => new Map(),
      railStatuses: () => ({ statuses: new Map(), openChildren: new Map() }),
      newestTurns: () => new Map(),
      runningSessions: () => new Set(),
      runningSince: () => new Map(),
      waitingSessions: () => new Set(),
      liveBackgroundCommands: () => new Map(),
      sessionOutcomes: new Map(),
      hidden: new Set(),
      pinnedTop: new Set(),
      drafts: {},
      saved: normalizePanelState({}),
      metadataStatsBySession: {},
      parsedRailCaches: {},
      metadataRailCaches: {},
      metadataRailRevisions: {},
    }) as unknown as Drawn;
    const mark = () => rails.at(-1)?.stats.parent?.[0]?.label ?? '';
    if (queued) {
      drawn.projectSpendQueued.add(childKey);
    }
    drawn.postRail(true);
    assert.match(mark(), /[+]$/, `before ${name}, the rail drew no lower-bound mark`);
    drawn.projectSpendIndexing = true;
    move(drawn);
    drawn.railInputFor(new Map(), new Map(), new Map(), Date.now());
    drawn.finishProjectSpendIndex();
    assert.doesNotMatch(mark(), /[+]$/, `a selection render after ${name} left the lower-bound mark on the rail`);
  }

  // An edge with either end missing from the catalog moves no figure and no revision.
  const drawn = hostWith([launch('parent', 'child')]);
  const loose = hostWith([launch('parent', 'child'), launch('gone', 'stray'), launch('parent', 'hidden')]);
  assert.equal(
    cost(loose, 'parent'),
    cost(drawn, 'parent'),
    "a dispatched session with no row changed its parent's cost",
  );
  assert.equal(loose.projectSpendRevision, drawn.projectSpendRevision, 'an edge with no row moved the spend revision');

  // A dispatched child is an agent run unless this window started it.
  const rows = [session('parent'), session('child')];
  const edges = drawn.sessionParentEdges(rows).edges;
  assert.equal(drawn.agentRunFor(rows[1], edges), true, "a dispatched session was filed as the reader's own");
  assert.equal(drawn.agentRunFor(rows[0], edges), false, 'the session that dispatched a child was filed as a run');
  drawn.startedHere.add('child');
  assert.equal(drawn.agentRunFor(rows[1], edges), false, 'a session this window started was filed as a run');
  const orphan = hostWith([launch('gone', 'child')]);
  assert.equal(
    orphan.agentRunFor(rows[1], orphan.sessionParentEdges(rows).edges),
    false,
    'a dispatched session whose parent has no row was filed as a run',
  );

  // Subagent edges do not add another cost contribution or override transcript classification.
  const subagent = hostWith([
    { kind: 'subagent', parentSessionId: 'parent', sessionId: 'child', file: fileOf('child'), toolUseIds: ['toolu_1'] },
  ]);
  assert.equal(cost(subagent, 'parent'), parent, "a subagent edge added the child's cost to its parent a second time");
  assert.equal(subagent.projectSpendRevision, alone.projectSpendRevision, 'a subagent edge moved the spend revision');
  assert.equal(
    subagent.agentRunFor(rows[1], subagent.sessionParentEdges(rows).edges),
    false,
    'a subagent edge filed a session whose transcript shows a person as a run',
  );

  // Reader-owned dispatches retain parent links and cost attribution without agent-run classification.
  for (const references of [
    [launch('parent', 'child', 'toolu_1', true)],
    [launch('parent', 'child'), launch('parent', 'child', 'toolu_2', true)],
  ]) {
    const owned = hostWith(references);
    owned.metaFor = () => ({ agentRun: true });
    assert.equal(
      owned.agentRunFor(rows[1], owned.sessionParentEdges(rows).edges),
      false,
      `a dispatched session its receipt says the reader asked for was filed under Run by agents (${references.length} launch results)`,
    );
    assert.deepEqual(
      owned.parentOfShown('child'),
      { id: 'parent', label: 'parent', relation: 'dispatched' },
      'an owned dispatched session lost the from figure on its heading',
    );
    assert.ok(
      Math.abs((cost(owned, 'parent') ?? 0) - (parent + child)) < 1e-9,
      `an owned dispatched session put ${cost(owned, 'parent')} on its parent, not ${parent} plus the child's ${child}`,
    );
  }

  // A human prompt overrides agent-run classification.
  // Automated follow-ups and notices retain it.
  const bg = { sessionKind: 'bg', entrypoint: 'cli', cwd: 'C:/repo' };
  const typed = (at: number, text: string, extra: Record<string, unknown>) => ({
    type: 'user',
    ...bg,
    timestamp: new Date(at).toISOString(),
    message: { role: 'user', content: text },
    ...extra,
  });
  const answered = (at: number) => ({
    type: 'assistant',
    ...bg,
    timestamp: new Date(at).toISOString(),
    message: {
      role: 'assistant',
      model: 'claude-opus-5',
      stop_reason: 'end_turn',
      content: [{ type: 'text', text: 'Done.' }],
    },
  });
  const launched = [typed(1_000, 'Review the branch', { origin: { kind: 'human' } }), answered(2_000)];
  const agentsOnly = [
    ...launched,
    typed(3_000, 'Now check the tests', { promptSource: 'sdk' }),
    answered(4_000),
    typed(5_000, 'Another Claude session sent a message', {
      isMeta: true,
      promptSource: 'system',
      origin: { kind: 'peer', from: 'a1' },
    }),
    {
      type: 'attachment',
      ...bg,
      timestamp: new Date(6_000).toISOString(),
      attachment: {
        type: 'queued_command',
        prompt: '<task-notification>done</task-notification>',
        commandMode: 'task-notification',
      },
    },
    answered(7_000),
  ];
  const personTyped = [
    ...launched,
    typed(3_000, 'Use the other fixture instead', { origin: { kind: 'human' } }),
    answered(4_000),
  ];
  for (const [records, run, why] of [
    [agentsOnly, true, "an agent's own dispatched worker with only SDK follow-ups left Run by agents"],
    [personTyped, false, 'a dispatched session a person typed into stayed under Run by agents'],
  ] as const) {
    fs.writeFileSync(fileOf('child'), records.map((record) => JSON.stringify(record)).join('\n') + '\n');
    const size = fs.statSync(fileOf('child')).size;
    const host = hostWith([launch('parent', 'child')]);
    host.metaFor = () => ({ agentRun: readSessionMeta(fileOf('child'), 1024 * 1024, 'child', true).agentRun });
    host.dispatchFacts.set('child', { person: scanForPerson(fileOf('child'), size).person });
    assert.equal(host.agentRunFor(rows[1], host.sessionParentEdges(rows).edges), run, why);
  }
  // Ledger usage differs from transcript usage, so the cost assertion detects direct transcript pricing.
  for (const id of ['child', 'grandchild']) {
    fs.writeFileSync(
      fileOf(id),
      JSON.stringify({
        type: 'assistant',
        timestamp: '2026-08-31T10:00:00.000Z',
        message: { id: `msg_${id}`, model: 'claude-opus-5', usage: { input_tokens: 9_000_000, output_tokens: 0 } },
      }) + '\n',
    );
  }
  type CardHost = Host & {
    live: Record<string, unknown>;
    liveActivity: Record<string, unknown>;
    turnsByKey: Map<string, unknown>;
    postActivity(session: string): boolean;
    finishProjectSpendIndex(): void;
    hydrateProjectSpend(workspace: string, generation: number, tick: unknown): void;
    renderTurnCard(...args: unknown[]): {
      label: string;
      dispatched?: { description: string }[];
      chips: {
        metric?: string;
        label: string;
        name?: string;
        detailList?: { heading?: { value?: string }; entries: { label: string; value?: string }[] };
      }[];
    };
  };
  const cardHost = (references: unknown[], listed?: string[], children?: Record<string, string>) =>
    Object.assign(hostWith(references, listed, records, children), {
      live: {},
      liveActivity: {},
      turnsByKey: new Map(),
    }) as CardHost;
  const parentTurn = (ids: string[], startedAt = Date.parse('2026-08-31T09:00:00')) =>
    fixtureTurn({ sessionId: 'parent', startedAt, files: [], commits: [], agents: [], dispatchToolUseIds: ids });
  // Exercise card batches and the newest-card Activity update.
  const cardOf = (host: CardHost, recorded: ReturnType<typeof fixtureTurn>, latest = false) => {
    if (!latest) {
      return host.renderTurnCard(recorded, false, 'Parent', NOW, [], new Set(), new Map(), new Map(), () =>
        (host as unknown as { dispatchedTurnCosts(): unknown }).dispatchedTurnCosts(),
      );
    }
    const posted: { card: ReturnType<CardHost['renderTurnCard']> }[] = [];
    // The editor surfaces around the redraw are not under test.
    Object.assign(host, {
      newestBySession: new Map([[recorded.sessionId, recorded]]),
      cards: [{ kind: 'turn', key: turnKey(recorded) }],
      hosts: [{ webview: {} }],
      sessionNames: new SessionNames(),
      folders: () => [],
      runningSessions: () => new Set(),
      liveOpenChildren: () => new Map(),
      railStatuses: () => ({ statuses: new Map(), openChildren: new Map() }),
      themedFor: (cards: unknown[]) => cards,
      sendToHost: (_host: unknown, message: { card: ReturnType<CardHost['renderTurnCard']> }) => posted.push(message),
    });
    assert.equal(host.postActivity(recorded.sessionId), true, 'the activity redraw posted nothing');
    return posted[0].card;
  };
  const costOf = (card: ReturnType<CardHost['renderTurnCard']>) => card.chips.find((chip) => chip.metric === 'cost');
  const ownCost = turnCost(parentTurn(['toolu_1'])).dollars ?? 0;
  const amount = (dollars: number) => `$${dollars.toFixed(2)}`;
  const assertCounted = (card: ReturnType<CardHost['renderTurnCard']>, sessions: number, why: string) => {
    const figure = costOf(card);
    if (!figure) {
      // This fixture has no own-turn cost.
      // A card with no counted child therefore has no cost figure.
      assert.deepEqual([sessions, ownCost], [0, 0], `${why}: the card drew no cost figure`);
      return;
    }
    const sum = amount(ownCost + sessions * child);
    assert.equal(figure.label, sum, why);
    assert.equal(figure.detailList?.heading?.value, sum, why);
    assert.ok(figure.name?.includes(sum), `${why}: the spoken name reads ${figure.name}`);
    assert.ok(card.label.includes(sum), `${why}: the card label left out the amount`);
    const entries = figure.detailList!.entries.filter((entry) => entry.label === 'child');
    assert.deepEqual(
      entries.map((entry) => entry.value),
      sessions ? [amount(child)] : [],
      `${why}: the popover entries`,
    );
  };
  {
    const host = cardHost([launch('parent', 'child'), launch('parent', 'child', 'toolu_2')]);
    const before = { ...host.lifetimeFiguresBySession().costs };
    const card = cardOf(host, parentTurn(['toolu_1', 'toolu_2']));
    assert.equal(card.dispatched?.length, 1, 'a repeated receipt drew two rows');
    assertCounted(card, 1, 'a turn with one dispatched session');
    assertCounted(cardOf(host, parentTurn(['toolu_1', 'toolu_2']), true), 1, 'an activity redraw');
    assert.deepEqual(host.lifetimeFiguresBySession().costs, before, 'drawing the card moved the session total');
    assert.ok(Math.abs((before.parent?.dollars ?? 0) - (parent + child)) < 1e-9);
  }
  {
    // Repeated receipts share the displayed name between the dispatched row and cost entry.
    const host = cardHost([
      { ...launch('parent', 'child'), name: 'First name' },
      { ...launch('parent', 'child', 'toolu_2'), name: 'Second name' },
    ]);
    const card = cardOf(host, parentTurn(['toolu_1', 'toolu_2']));
    const row = card.dispatched?.[0]?.description;
    assert.ok(row, 'the card drew no Dispatched row');
    assert.equal(
      costOf(card)?.detailList?.entries.at(-1)?.label,
      row,
      'the cost entry and the Dispatched row name the session differently',
    );
  }
  {
    const host = cardHost([launch('parent', 'child')]);
    const newest = parentTurn(['toolu_1']);
    const older = parentTurn(['toolu_1'], newest.startedAt - 1);
    cardOf(host, newest, true);
    const posted: any[] = [];
    const refresh = vi.fn<() => void>();
    Object.assign(host, {
      cards: [cardOf(host, newest), cardOf(host, older)],
      turnsByKey: new Map([[turnKey(older), older]]),
      sendToHost: (_host: unknown, message: unknown) => posted.push(message),
      postProjectSpend: () => {},
      postRail: () => {},
      postRailIfSpendPendingMoved: () => {},
      scheduleProjectSpendSave: () => {},
      refresh,
      projectSpendIndexing: true,
      projectSpendFiles: records.map((record) =>
        record.file === fileOf('child') ? { ...record, lifetimeBuckets: bucket(inputs.child * 2) } : record,
      ),
    });
    host.finishProjectSpendIndex();
    assert.equal(posted.length, 1);
    assert.equal(posted[0].type, 'activity');
    assert.deepEqual(
      posted[0].cards.map((card: any) => costOf(card)?.label),
      [amount(ownCost + child * 2), amount(ownCost + child * 2)],
    );
    assert.equal(refresh.mock.calls.length, 0);
    host.projectSpendIndexing = true;
    host.finishProjectSpendIndex();
    assert.equal(posted.length, 1, 'an unchanged ledger pass posted cards');
  }
  {
    const host = cardHost([launch('parent', 'child')]);
    const newest = parentTurn(['toolu_1']);
    cardOf(host, newest, true);
    const posted: any[] = [];
    const storage = tempDir('dispatch-cost-hydration-');
    saveSpendLedger(
      storage,
      'w',
      records.map((record) => ({ ...record, workspace: normalizeWorkspace('w') })),
    );
    Object.assign(host, {
      projectSpendHydrated: false,
      projectSpendFiles: [],
      projectSpendVisibleFiles: [],
      projectSpendQueued: new Set([childKey]),
      projectSpendWorkspace: 'w',
      projectSpendStorageDir: storage,
      refreshGeneration: 1,
      scheduleProjectSpendMidnight: () => {},
      scheduleProjectSpendIndex: () => {},
      scheduleProjectSpendSave: () => {},
      postProjectSpend: () => {},
      postRail: () => {},
      sendToHost: (_host: unknown, message: unknown) => posted.push(message),
      cards: [],
    });
    const before = cardOf(host, newest);
    assert.match(costOf(before)!.label, /[+]$/);
    Object.assign(host, { cards: [before] });
    host.hydrateProjectSpend('w', 1, null);
    assert.equal(posted.length, 1);
    assert.equal(posted[0].type, 'activity');
    assertCounted(posted[0].cards[0], 1, 'hydration redraw');
  }
  {
    // Discovery readiness changes the cost even when no source ownership changes.
    const host = cardHost([launch('parent', 'hidden')], ['parent']);
    const newest = parentTurn(['toolu_1']);
    cardOf(host, newest, true);
    const provider = host as unknown as Record<string, any>;
    const posted: any[] = [];
    const refresh = vi.fn<() => void>();
    Object.assign(provider, {
      dispatchDiscoveryPending: true,
      authoritativeCatalog: [session('parent')],
      catalog: { sessions: [session('parent')] },
      refreshGeneration: 1,
      repositoryScopeRoots: [],
      claudeParents: [session('parent')],
      claudeChildReferenceEntries: new Map(),
      claudeChildStatWrites: new Map(),
      derivedCacheCheckpointState: { markChanged() {} },
      checkpointDerivedCache() {},
      hasHumanPrompt: () => true,
      activityFor: () => 1,
      pruneDerivedTitles: () => false,
      sendToHost: (_host: unknown, message: unknown) => posted.push(message),
      refresh,
    });
    const sourceRevision = provider.sessionSpendSourceIndex.revision;
    for (const pending of [false, true]) {
      provider.cards = [cardOf(host, newest)];
      const before = costOf(provider.cards[0]);
      assert.equal(before?.label, pending ? undefined : '$0.00+');
      provider.progressiveWorker = {
        run: async () => ({
          generation: 1,
          value: {
            kind: 'claude-children',
            complete: !pending,
            continuation: false,
            references: provider.claudeChildReferences,
            referenceEntries: [],
            children: [],
            roots: [session('parent')],
          },
        }),
      };
      posted.length = 0;
      assert.equal(await provider.prepareClaudeChildren(1, new AbortController().signal), true);
      assert.equal(provider.dispatchDiscoveryPending, pending);
      assert.equal(provider.sessionSpendSourceIndex.revision, sourceRevision);
      assert.equal(posted.length, 1, `discovery ${pending ? 'pending' : 'complete'} posted no card`);
      assert.equal(posted[0].type, 'activity');
      assert.equal(costOf(posted[0].cards[0])?.label, pending ? '$0.00+' : undefined);
      assert.equal(refresh.mock.calls.length, 0, 'discovery readiness required a full refresh');
    }
  }
  {
    // One reference with receipts on two turns counts on the card of the first receipt.
    const host = cardHost([{ ...launch('parent', 'child'), toolUseIds: ['toolu_1', 'toolu_2'] }]);
    assertCounted(cardOf(host, parentTurn(['toolu_1'])), 1, 'the first receipt');
    const later = cardOf(host, parentTurn(['toolu_2'], Date.parse('2026-08-31T09:30:00')));
    assert.equal(later.dispatched?.length, 1, 'the later card lost its row');
    assertCounted(later, 0, 'a later receipt');
  }
  {
    // A subagent's dispatched session contributes cost without a Dispatched row.
    const subagentLaunch = (parentSessionId: string, sessionId: string, toolUseId: string) => ({
      kind: 'subagent',
      parentSessionId,
      sessionId,
      file: fileOf(sessionId),
      toolUseIds: [toolUseId],
    });
    const members = ['parent', 'helper', 'worker', 'child'];
    const direct = cardHost(
      [subagentLaunch('parent', 'helper', 'toolu_agent'), launch('helper', 'child', 'toolu_bash')],
      members,
      { helper: 'parent' },
    );
    const card = cardOf(direct, parentTurn(['toolu_agent']));
    assert.equal(card.dispatched, undefined, 'a session a subagent dispatched drew a Dispatched row');
    assertCounted(card, 1, 'a session a subagent dispatched');
    assertCounted(cardOf(direct, parentTurn([], Date.parse('2026-08-31T09:30:00'))), 0, 'a card without the launch');
    const nested = cardHost(
      [
        subagentLaunch('parent', 'helper', 'toolu_agent'),
        subagentLaunch('helper', 'worker', 'toolu_inner'),
        launch('worker', 'child', 'toolu_bash'),
      ],
      members,
      { helper: 'parent', worker: 'helper' },
    );
    assertCounted(cardOf(nested, parentTurn(['toolu_agent'])), 1, 'a session a nested subagent dispatched');
  }
});

