test('Claude relationships refresh current and retained parent rows without a parent transcript write', () => {
  const workerEntry = fs.readFileSync(path.join(__dirname, 'progressiveworker-entry.ts'), 'utf8');
  const claudeKeyAt = layoutIndexOf(
    workerEntry,
    ': references.filter((child) => child.parentSessionId === session.sessionId)',
  );
  assert.ok(claudeKeyAt > 0, 'the worker cache key omits Claude relationship state');
  const claudeKey = workerEntry.slice(claudeKeyAt, workerEntry.indexOf('.sort()', claudeKeyAt));
  sourceMatch(claudeKey, /toolUseIds/, 'the worker cache key omits the Claude launch ids');
  sourceDoesNotMatch(
    claudeKey,
    /spendFileVersion/,
    'a running Claude child append makes the selected parent read stale and shows the loading row',
  );
  const codexKeyAt = layoutIndexOf(
    workerEntry,
    "session.agent === 'codex' ? children.filter((child) => child.parentThreadId === session.sessionId)",
  );
  assert.ok(codexKeyAt > 0, 'the worker cache key omits Codex subagent state');
  sourceDoesNotMatch(
    workerEntry.slice(codexKeyAt, layoutIndexOf(workerEntry, ': references.filter(', codexKeyAt)),
    /spendFileVersion/,
    'a running Codex subagent append makes the selected parent read stale and shows the loading row',
  );
  sourceMatch(
    workerEntry,
    /agentKey: agentSpendDependencyKey\([^;]*codexChildFiles\b/,
    'the worker cost key drops the Codex subagent revisions the host key carries',
  );
  sourceMatch(
    panelHostSource,
    /return agentSpendDependencyKey\(read\.turns,/,
    'the host builds its cost key apart from the worker, so the two never agree',
  );
  const factsAt = panelHostSource.indexOf('private async refreshAgentFacts(');
  const facts = memberFrom(panelHostSource, factsAt);
  const readAt = facts.indexOf('entry.read = {');
  const agentKeyAt = facts.lastIndexOf(
    'entry.agentKey = this.agentSpendKey(session, entry.read, undefined, versions, now)',
  );
  assert.ok(
    readAt >= 0 && readAt < agentKeyAt,
    'the cost key names turns the round trip replaced, so every poll repeats the round trip',
  );
  const retainedAt = workerEntry.indexOf("if (request.kind === 'retained')");
  const retained = workerEntry.slice(retainedAt, workerEntry.indexOf("if (request.kind === 'page')", retainedAt));
  sourceMatch(
    retained,
    /refreshClaudeAgentFacts\(page\.turns, agentSpendOf, agentSessionTargetOf\)/,
    'retained Claude rows keep child targets and spend from their original page read',
  );
  const prepareAt = panelHostSource.indexOf('private async prepareProgressive(');
  const prepare = panelHostSource.slice(prepareAt, panelHostSource.indexOf('// Answer the sentinel', prepareAt));
  assert.ok(
    prepare.includes('this.historyAgentKey(session, history.pages, undefined, undefined, historyNow)'),
    'retained Claude pages keep the child relationships and costs of their original page read',
  );
  sourceDoesNotMatch(
    prepare,
    /session\.agent === 'codex' && history\?\.pages\.length/,
    'the host refreshes retained pages only for Codex sessions',
  );
});

