test('the reader icon theme reaches the rows the Files popover draws', () => {
  // Resolve the card's file icons through themedFor before reading its Files detail rows.
  const recorded = FIXTURE_TURNS.find((one) => one.files.length > 1)!;
  const card = toCard(recorded, false, NOW);
  const host = Object.create(PanelProvider.prototype) as Record<string, unknown>;
  Object.assign(host, {
    folders: () => [],
    icons: { iconFor: () => ({ glyph: { font: 'seti', character: 'B', colour: '#cc7832' } }) },
  });
  const themed = (
    host as unknown as {
      themedFor(cards: unknown[], webview: unknown, light: boolean): CardView[];
    }
  ).themedFor([card], {}, true)[0];

  const chip = themed.chips?.find((one) => one.metric === 'files');
  const rows = detailRowsFor(themed, chip?.detailList?.layout);
  assert.equal(rows?.kind, 'files', 'the Files chip no longer names the record its popover draws');
  const drawn = rows?.kind === 'files' ? rows.files : [];
  assert.ok(drawn.length > 1, 'the fixture turn drew no file rows');
  assert.deepEqual(
    drawn.map((file) => file.icon.glyph?.character),
    drawn.map(() => 'B'),
    'a file row in the Files popover kept the lettered badge, so the reader icon theme draws nowhere',
  );
  assert.notEqual(
    themed.files?.[0],
    card.files[0],
    'the theme icon was written into the card the panel keeps rather than onto a copy',
  );
});

test('the panel prefers the shared state, so a tab opens where the last one left off', () => {
  // Inject shared state through webviewPanelState.
  // The projection excludes host-owned labels.
  sourceMatch(
    panelHostSource,
    /savedStateJson: scriptJson\(webviewPanelState\(this\.saved\)\)/,
    'the shared state is not injected into the page, so a new host starts blank',
  );
  sourceMatch(
    panelDevelopmentSource,
    /const SAVED_STATE = \$\{options\.savedStateJson\};/,
    'the panel shell does not put the prepared state before the browser entry',
  );
  // scriptJson protects embedded state from closing the script element.
  sourceDoesNotMatch(
    panelHostSource,
    /const SAVED_STATE = \$\{JSON\.stringify/,
    'the state is stringified straight into the page, so a value can close the script block',
  );
  sourceMatch(
    bootstrapSource,
    /const sharedState = !options\.preferBrowserState && typeof SAVED_STATE === 'object' \? SAVED_STATE : undefined;/,
    'a fresh panel does not prefer the shared state, or a development reload cannot prefer its newer browser state',
  );
  sourceMatch(
    stateSource,
    /const initial = \{ \.\.\.\(shared \?\? browser \?\? \{\}\) \};/,
    'the saved-state service does not prefer the shared state over its own',
  );
  // Every checked session-state field reads the same initial state.
  for (const key of ['open', 'read', 'hidden', 'pinnedTop', 'showing']) {
    assert.ok(sessionStateSource.includes(`initial.${key}`), `the ${key} state is not read from the shared state`);
  }
  // panel.ts must not read the stored collapsed set.
  sourceDoesNotMatch(script, /saved\.collapsed/, 'the panel reads a fold set it has no way to draw');
  sourceDoesNotMatch(
    script,
    /browserState\.read\(\)/,
    'a remembered set still reads this webview own state directly, so it does not reach the other host',
  );

  // Save state to both browser storage and the host.
  sourceMatch(
    stateSource,
    /browserState\.write\(state\)/,
    'the saved-state service no longer keeps the browser copy of the state',
  );
  sourceMatch(
    stateSource,
    /host\.send\(\{ type: 'saveState', state \}\)/,
    'the saved-state service no longer sends the state on, so it never reaches the other host',
  );
});

test('a reload opens on the session the reader left, not on the newest', () => {
  // Restore the selected session in both the host and browser.
  sourceMatch(
    sessionStateSource,
    /let showing = typeof initial\.showing === 'string' \? initial\.showing : '';/,
    'the panel does not read the session on screen out of the saved state',
  );
  sourceMatch(
    sessionStateSource,
    /showing,/,
    'the saved state carries no session, so a reload opens on whichever is newest',
  );
  sourceMatch(
    panelHostSource,
    /this\.showing = this\.saved\.showing \|\| null;/,
    'the extension does not restore the session on screen, so the first parse is of another one',
  );
  // Save selection changes immediately.
  sourceMatch(
    sessionStateSource,
    /if \(showing !== next\) \{ showing = next; owner\.save\(\); \}/,
    'a change of session is not saved until something else is',
  );
  // State normalization retains the selected session.
  assert.equal(normalizePanelState({ showing: 'abc' }).showing, 'abc');
});

// Supply editor options, disposable listeners, and reveal tracking for panel adoption tests.
function fakeWebviewPanel(options: Record<string, unknown>) {
  const panel = {
    webview: { postMessage: () => Promise.resolve(true) },
    options,
    viewColumn: vscode.ViewColumn.Active,
    visible: true,
    active: true,
    revealed: 0,
    disposed: false,
    reveal: (): void => {
      panel.revealed += 1;
    },
    dispose: (): void => {
      panel.disposed = true;
    },
    onDidDispose: () => ({ dispose: () => undefined }),
    onDidChangeViewState: () => ({ dispose: () => undefined }),
  };
  return panel;
}

test('the log says where the panel it timed came from', () => {
  // Adoption and reveal diagnostics identify the panel's creation or restoration route.
  const logged: { event: string; record: unknown }[] = [];
  const created: ReturnType<typeof fakeWebviewPanel>[] = [];
  let currentOptions: Record<string, unknown> = {};
  const provider = Object.create(PanelProvider.prototype) as Record<string, unknown>;
  Object.assign(provider, {
    editorPanel: null,
    diagnostics: {
      enabled: () => true,
      log: (event: string, record: unknown) => {
        logged.push({ event, record });
      },
    },
    attach: () => undefined,
  });
  const host = provider as unknown as {
    editorPanel: unknown;
    openInEditor(column?: number): void;
    revivePanel(panel: vscode.WebviewPanel): void;
  };
  const editorWindow = vscode.window as unknown as Record<string, unknown>;
  editorWindow.createWebviewPanel = (
    _type: string,
    _title: string,
    _column: number,
    options: Record<string, unknown>,
  ) => {
    // Capture requested options for the restored-panel fixture.
    currentOptions = options;
    const panel = fakeWebviewPanel(options);
    created.push(panel);
    return panel;
  };
  try {
    host.openInEditor();
    // Reopening an existing panel reveals it without creating another.
    host.openInEditor();
    assert.equal(created.length, 1, 'the command made a second panel while one was already open');
    assert.equal(created[0].revealed, 1, 'the panel already open was not brought to the front');
    // Restore a panel with the current host options.
    host.editorPanel = null;
    const restored = fakeWebviewPanel({ ...currentOptions });
    host.revivePanel(restored as unknown as vscode.WebviewPanel);
    // Reveal the restored panel with its recorded origin.
    host.openInEditor();
    assert.equal(created.length, 1, 'the command made a panel while a restored one was held');
    assert.equal(restored.revealed, 1, 'the restored panel was not brought to the front');
    // Replace a restored panel whose stored options are stale.
    host.editorPanel = null;
    const stale = fakeWebviewPanel({ retainContextWhenHidden: true });
    host.revivePanel(stale as unknown as vscode.WebviewPanel);
    assert.equal(stale.disposed, true, 'a restored tab carrying stale options was kept');
    assert.equal(created.length, 2, 'a restored tab with stale options was not replaced');
    // With a panel already open, discard the stale restored panel and reveal the existing one.
    const alsoStale = fakeWebviewPanel({ retainContextWhenHidden: true });
    host.revivePanel(alsoStale as unknown as vscode.WebviewPanel);
    assert.equal(created.length, 2, 'a second panel was made while one was already open');
    assert.equal(created[1].revealed, 1, 'the panel already open was not brought to the front');
  } finally {
    delete editorWindow.createWebviewPanel;
  }

  assert.deepEqual(
    logged,
    [
      { event: 'panelAdopted', record: { origin: 'created' } },
      { event: 'panelRevealed', record: { origin: 'created' } },
      { event: 'panelAdopted', record: { origin: 'serializer' } },
      { event: 'panelRevealed', record: { origin: 'serializer' } },
      { event: 'panelAdopted', record: { origin: 'serializer-replaced' } },
      { event: 'panelRevealed', record: { origin: 'serializer-replaced' } },
    ],
    'a panel reached the reader under an origin the log does not tell apart',
  );
});

test('performance diagnostics are a redacted read-only snapshot of held state', () => {
  const command = manifest.contributes.commands.find(
    (one: { command: string }) => one.command === 'arc.savePerformanceDiagnostics',
  );
  assert.deepEqual(command, {
    command: 'arc.savePerformanceDiagnostics',
    title: 'Save Performance Diagnostics',
    category: 'Arc',
  });
  sourceMatch(
    panelHostSource,
    /registerCommand\('arc\.savePerformanceDiagnostics', /,
    'the contributed diagnostics command has no extension-host handler',
  );

  const save = memberFrom(
    panelHostSource,
    panelHostSource.indexOf('async savePerformanceDiagnostics(target?: string)'),
  );
  const saveBody = save;
  sourceMatch(
    saveBody,
    /this\.performanceCounters\.recordCapture\(\)/,
    'a capture is absent from its own monotonic count',
  );
  sourceMatch(
    saveBody,
    /const snapshot = this\.performanceDiagnostics\(capturedAt\)/,
    'the command bypasses the tested diagnostic projection input',
  );
  sourceMatch(
    saveBody,
    /vscode\.window\.showSaveDialog/,
    'the command writes without asking where the reader wants the JSON file',
  );
  sourceMatch(saveBody, /vscode\.workspace\.fs\.writeFile\(/, 'the selected diagnostics file is never written');
  // The host delegates capture-destination selection to savePerformanceDiagnosticsSnapshot.
  sourceMatch(
    saveBody,
    /savePerformanceDiagnosticsSnapshot\(\{/,
    'the command picks its own destination instead of the tested rules',
  );
  const savedTargets = sourceNodes(
    saveBody,
    (node) =>
      (ts.isShorthandPropertyAssignment(node) ||
        (ts.isPropertyAssignment(node) && node.initializer.getText() === 'target')) &&
      node.name.getText() === 'target' &&
      ts.isObjectLiteralExpression(node.parent) &&
      ts.isCallExpression(node.parent.parent) &&
      node.parent.parent.expression.getText() === 'savePerformanceDiagnosticsSnapshot',
  );
  assert.equal(savedTargets.length, 1, 'the command drops the path it was given');
  sourceMatch(
    saveBody,
    /environment: process\.env,/,
    'the command cannot be aimed by the environment, so an automated capture needs the dialog',
  );
  sourceMatch(
    saveBody,
    /vscode\.window\.showInformationMessage\(/,
    'a capture aimed by the environment leaves the reader at the palette no way to find the file',
  );
  sourceMatch(
    panelHostSource,
    /registerCommand\('arc\.savePerformanceDiagnostics', \(target\?: unknown\) =>/,
    'the command handler drops the path a caller passes',
  );
  sourceDoesNotMatch(
    saveBody,
    /\.refresh\(|allSessions\(|readSession|queueProjectSpend|saveSpendLedger|flushProjectSpend|statSync|readFile|createHash/,
    'capturing diagnostics starts work or reads an authoritative source',
  );

  const snapshotBody = memberFrom(panelHostSource, panelHostSource.indexOf('private performanceDiagnostics('));
  sourceMatch(
    snapshotBody,
    /projectPerformanceDiagnostics\(/,
    'the command does not use the tested redaction projector',
  );
  sourceDoesNotMatch(
    snapshotBody,
    /allSessions\(|readSession|queueProjectSpend|saveSpendLedger|flushProjectSpend|statSync|readFile|createHash/,
    'collecting held diagnostic state starts filesystem or ledger work',
  );
  sourceMatch(
    snapshotBody,
    /oldestPendingWakeAgeMs: this\.watchScheduler\.pendingAge\(capturedAt\)/,
    'the snapshot cannot distinguish a fresh wake from a starved one',
  );
  sourceMatch(
    snapshotBody,
    /oldestPendingCheckpointAgeMs:\s*this\.projectSpendSaveOwedSince === null \? null : Math\.max\(0, capturedAt - this\.projectSpendSaveOwedSince\)/,
    'the snapshot omits the age of a pending or failed ledger checkpoint',
  );

  const sent = panelHostSource.match(/\.webview\.postMessage\(/g) ?? [];
  assert.equal(sent.length, 1, 'a webview message bypasses the one path that records its type and serialized bytes');
  sourceMatch(
    panelHostSource,
    /const serializedBytes = budget === null \? null : serializedMessageBytes\(message\);/,
    'an unbudgeted message pays for a serialization that diagnostics cannot use',
  );
  sourceMatch(
    panelHostSource,
    /recordMessage\(kind, serializedBytes, host\)/,
    'the shared message path does not count the measured bytes by panel',
  );
  sourceMatch(
    panelHostSource,
    /recordPanelMessage\(msg\.kind, msg\.ms, host\)/,
    'a webview performance reply loses the panel identity that sent it',
  );

  // Post the message before measuring its serialized size.
  const sendBody = methodBody('private sendToHost(');
  const postedAt = layoutIndexOf(sendBody, 'const posted = host.webview.postMessage(message);');
  const measuredAt = layoutIndexOf(
    sendBody,
    'const serializedBytes = budget === null ? null : serializedMessageBytes(message);',
  );
  assert.ok(
    postedAt >= 0 && measuredAt > postedAt,
    'the message is measured before it is posted, so a click waits on the measurement',
  );
  assert.ok(
    sendBody.trimEnd().endsWith('return posted;'),
    'the answer the caller waits on is not the one the post gave',
  );
});

test('a capture that writes nothing puts its reason where a run with no reader can read it', async () => {
  // Failed captures reach the diagnostics log even when ordinary diagnostics logging is disabled.
  const shown: string[] = [];
  const diagnostics = createDiagnosticsLog({
    enabled: false,
    directory: tempDir('arc-capture-log-'),
    workspace: 'arc',
    pid: 4242,
    startedAt: Date.UTC(2026, 0, 1, 3, 4, 5),
  });
  const provider = Object.create(PanelProvider.prototype) as Record<string, unknown>;
  Object.assign(provider, {
    diagnostics,
    performanceCounters: { recordCapture: () => undefined },
    performanceDiagnostics: () => ({ schemaVersion: 1 }),
  });
  const editorWindow = vscode.window as unknown as Record<string, unknown>;
  const fileUri = vscode.Uri as unknown as Record<string, unknown>;
  const editorWorkspace = vscode.workspace as unknown as Record<string, unknown>;
  editorWindow.showErrorMessage = (message: string) => {
    shown.push(message);
    return Promise.resolve(undefined);
  };
  fileUri.file = (file: string) => ({ fsPath: file });
  editorWorkspace.fs = { writeFile: () => Promise.reject(new Error('EACCES: permission denied')) };
  const target = path.join(path.sep === '\\' ? 'C:\\arc-capture' : '/arc-capture', 'startup.json');
  const capture = provider as unknown as {
    savePerformanceDiagnostics(target?: string): Promise<string | null>;
  };
  let answered: string | null = target;
  let refused: string | null = target;
  try {
    answered = await capture.savePerformanceDiagnostics(target);
    // A relative destination without an open folder also records its refusal.
    refused = await capture.savePerformanceDiagnostics('out/startup.json');
  } finally {
    delete editorWindow.showErrorMessage;
    delete fileUri.file;
    delete editorWorkspace.fs;
  }

  assert.equal(answered, null, 'a capture that wrote nothing answered with a file');
  assert.equal(refused, null, 'a relative path with no folder open answered with a file');
  assert.equal(shown.length, 2, 'the reader at the window was told nothing about a failed capture');
  const logFile = diagnostics.file();
  assert.ok(logFile, 'a failed capture wrote no diagnostics line while the log setting was off');
  const lines = fs
    .readFileSync(logFile, 'utf8')
    .trim()
    .split('\n')
    .map((line) => JSON.parse(line) as Record<string, unknown>);
  assert.equal(lines.length, 2, 'a failed capture wrote no line for each failure, or wrote more');
  assert.equal(lines[0].event, 'performanceCaptureFailed', 'a failed capture is logged under another name');
  assert.equal(lines[0].file, target, 'the logged failure does not name the file it could not write');
  assert.equal(
    lines[0].reason,
    'EACCES: permission denied',
    'the logged failure does not carry what the file system said',
  );
  assert.equal(lines[1].event, 'performanceCaptureFailed', 'a refused path is logged under another name');
  assert.equal(lines[1].file, null, 'a refused path named a file that was never a file');
  assert.ok(
    String(lines[1].reason).includes('out/startup.json'),
    'the logged refusal does not name the path it could not read',
  );
});

test('a render writes the rail it posted down without yielding first', () => {
  // Compute and retain the posted session list key without yielding.
  // Another post during that interval would leave the retained key stale.
  const refresh = memberFrom(panelHostSource, panelHostSource.indexOf('async refresh('));
  const body = refresh;
  const worded = body.indexOf('const railInput = this.railInputFor(counts, statuses, openChildren, railNow);');
  const stamped = body.indexOf('this.lastRailKey = railKey;');
  assert.ok(worded >= 0 && stamped > worded, 'the rail is written down before the render that carried it is posted');
  assert.equal(
    body.slice(worded, stamped).match(/\bawait\b/g),
    null,
    'the stretch between wording the rail and writing it down yields, so a rail post can land inside it',
  );
});

