// Query behavior is imported from browser-safe modules. The panel keeps no copied grammar.
test('the panel imports the shared session query rules', () => {
  sourceMatch(
    railSource,
    /from '\.\.\/domain\/session-query[.]ts'/,
    'the panel does not import the shared query grammar',
  );
  for (const name of [
    'parseSessionQuery',
    'queryWords',
    'matchSessions',
    'queryToken',
    'replaceToken',
    'labelSuggestions',
    'labelKey',
    'quoteQueryValue',
  ]) {
    sourceDoesNotMatch(script, new RegExp('function ' + name + '\\('), name + ' is implemented again in the panel');
  }
  assert.deepEqual(
    matchSessions(
      [
        { id: 'one', label: 'Timeline UI work', agent: 'Claude', labels: ['release 0.4'] },
        { id: 'two', label: 'Hook smoke test', agent: 'Codex', labels: [] },
      ],
      'label:"release 0.4"',
    ).map((session) => session.id),
    ['one'],
  );
  assert.deepEqual(queryToken('agent:codex label:perf', 17), { prefix: 'label', value: 'perf', start: 12, end: 22 });
  assert.equal(
    labelSuggestions([{ name: 'release 0.4', count: 1, countName: 'carried by one session' }], 're')[0].token,
    'label:"release 0.4"',
  );
  assert.equal(canStartSearch('title:foo'), false);
  assert.equal(canStartSearch('foo'), true);
  assert.equal(withWhere('find: root', 'prompt'), 'find: root in:prompt');
  assert.equal(whereNote('find: x in:respons'), 'in:respons was not understood. Use in:prompt, in:summary or in:both.');
});
