test('a diff opened from the panel names the group it lands in', () => {
  // File and single-file diff commands name their target editor column.
  sourceMatch(
    panelHostSource,
    /\{ viewColumn: column, preserveFocus: false \}/,
    'the single-file diff opens without naming a group, so it can split the reader editor',
  );
  sourceMatch(
    panelHostSource,
    /'vscode\.open', vscode\.Uri\.file\(msg\.path\), \{ viewColumn: column \}/,
    'opening a file without a pending diff does not name a group',
  );
  // A modifier press requests the editor column beside the panel.
  sourceMatch(
    hostHandler('openFile'),
    /const column = msg\.beside \? vscode\.ViewColumn\.Beside : this\.column\(\);/,
    'a modifier press no longer opens the file in a group of its own',
  );
  sourceMatch(
    cardRowsSource,
    /beside: event\.ctrlKey \|\| event\.metaKey/,
    'a file row does not send whether a modifier was held',
  );
  sourceMatch(
    panelHostSource,
    /workbench\.action\.splitEditorRight/,
    'the multi-file diff ignores the modifier, since focus is the only way to tell it where to open',
  );
  // Focus the target column before opening a multi-file diff.
  sourceMatch(
    panelHostSource,
    /await this\.focusColumn\(beside\);\s*(?:\/\/[^\n]*\s*)*await vscode\.commands\.executeCommand\('vscode\.changes'/,
    'the multi-file diff does not focus the group it should open in, so it lands wherever focus was',
  );
  // The host passes column-selection inputs to editorColumn.
  sourceMatch(
    panelHostSource,
    /return editorColumn\(\{/,
    'the column is decided here rather than in the tested module',
  );
  sourceMatch(
    panelHostSource,
    /panel: this\.editorPanel\?\.viewColumn \?\? null,/,
    'the rule is not told where the panel own tab is, so it can send a diff into it',
  );
});

test('dispatched file presses open the child snapshot, including a path the parent also changed', async () => {
  const child = 'child-session';
  const only = 'C:/repo/child-only.ts';
  const shared = 'C:/repo/shared.ts';
  const card = { kind: 'turn', dispatched: [{ sessionId: child, files: [{ path: only }, { path: shared }] }] };
  const calls: unknown[][] = [];
  const snapshots: string[] = [];
  const provider = {
    column: () => 7,
    pendingEntry(sessionId: string, file: string) {
      snapshots.push(sessionId);
      return { snapshot: `${sessionId}/${file}`, path: file };
    },
  };
  const cardFor = (key: string) => (key === 'parent:1' ? { card, sessionId: 'parent' } : null);
  const vscode = {
    ViewColumn: { Beside: 99 },
    Uri: { file: (file: string) => file },
    commands: {
      executeCommand: (...args: unknown[]) => {
        calls.push(args);
      },
    },
  };
  const path = { basename: (file: string) => file.split('/').at(-1) };
  const baselineUri = (snapshot: string) => snapshot;
  const lifted = esbuild.transformSync(
    `async function lifted(msg, cardFor, vscode, path, baselineUri) {${handlerBody(panelHostSource, 'openFile')}}`,
    { loader: 'ts' },
  ).code;
  const run = new Function(`${lifted}; return lifted;`)() as (this: unknown, ...args: unknown[]) => Promise<void>;
  for (const file of [only, shared]) {
    await run.call(
      provider,
      { key: 'parent:1', path: file, sourceSessionId: child, beside: false },
      cardFor,
      vscode,
      path,
      baselineUri,
    );
  }
  assert.deepEqual(snapshots, [child, child]);
  assert.deepEqual(
    calls.map((call) => call[1]),
    [`${child}/${only}`, `${child}/${shared}`],
  );
  await run.call(provider, { key: 'parent:1', path: shared, beside: false }, cardFor, vscode, path, baselineUri);
  assert.deepEqual(snapshots, [child, child, 'parent']);
  const before = calls.length;
  await run.call(
    provider,
    { key: 'parent:1', path: 'C:/repo/unlisted.ts', sourceSessionId: child, beside: false },
    cardFor,
    vscode,
    path,
    baselineUri,
  );
  assert.equal(calls.length, before);
});

