// Extract one host method's block from the syntax tree.
function methodBody(marker: string): string {
  const at = panelHostSource.indexOf(marker);
  assert.notEqual(at, -1, `panelhost.ts no longer holds "${marker}", so this guard cannot see what it does`);
  const [body] = sourceNodes(
    panelHostSource,
    (node) =>
      ts.isBlock(node) &&
      node.parent !== undefined &&
      ts.isClassElement(node.parent) &&
      ts.isClassLike(node.parent.parent) &&
      node.parent.getFullStart() <= at &&
      at < node.parent.end,
  );
  assert.ok(body !== undefined, `${marker} has no body this guard can read`);
  return body.slice(1, -1);
}

function extractedFlushQueue(): (this: Record<string, any>, session: string) => void {
  const compiled = esbuild.transformSync(
    `
export function flushQueue(session: string) {
${methodBody('public flushQueue(')}
}`,
    { loader: 'ts', format: 'cjs', target: 'esnext' },
  ).code;
  const module = { exports: {} as { flushQueue: (this: Record<string, any>, session: string) => void } };
  new Function(
    'module',
    'exports',
    'commentsForQueuedSubmission',
    'compactSubmission',
    'clearSubmission',
    'clearRequest',
    'queueAfterAcceptedRecovery',
    'queueCanDrain',
    'queueResetInFlight',
    'queueSuccessorDelivery',
    compiled,
  )(
    module,
    module.exports,
    commentsForQueuedSubmission,
    compactSubmission,
    clearSubmission,
    clearRequest,
    queueAfterAcceptedRecovery,
    queueCanDrain,
    queueResetInFlight,
    queueSuccessorDelivery,
  );
  return module.exports.flushQueue;
}

test('New session keeps the initiating panel host on its provisional draft', () => {
  const launcherStates: unknown[] = [];
  let inheritedProfile = true;
  const newSession = new Function(
    'sessionLauncherView',
    'launcherProfile',
    'vscode',
    'DRAFT_SESSION_PREFIX',
    'crypto',
    `return function (request, host, ownership) {\n${methodBody('public newSession(')}\n};`,
  )(
    (state: unknown) => {
      launcherStates.push(state);
      return {
        primary: inheritedProfile
          ? { profile: { agent: 'claude', model: 'opus', effort: 'high', permissionMode: 'auto', source: 'recent' } }
          : null,
      };
    },
    () => ({ agent: 'claude', model: 'opus', effort: 'high', permissionMode: 'auto', source: 'recent' }),
    { window: { showInformationMessage() {} } },
    DRAFT_SESSION_PREFIX,
    { randomUUID: () => 'new-draft' },
  ) as (this: Record<string, unknown>, request?: unknown, panelHost?: unknown) => boolean;
  let active = true;
  const host = { tab: 'navigated', webview: { id: 'navigated-webview' }, active: () => active };
  const hostSessions = new Map([[host, 'navigated']]);
  const created: Array<{ id: string; source: string | null; mapped: string | null }> = [];
  const sent: unknown[] = [];
  const broadcast: unknown[] = [];
  const provider = {
    recentProfiles: [],
    models: [],
    hosts: [host],
    hostSessions,
    showing: 'global',
    composerState() {
      return { sessionId: 'global' };
    },
    composerStateFor(session: string, webview: unknown) {
      return { sessionId: session, webview };
    },
    launcherFor(owner?: typeof host) {
      owner ??= this.hosts.find((open) => open.active());
      const state = owner
        ? this.composerStateFor(this.hostSessions.get(owner) ?? this.showing, owner.webview)
        : this.composerState();
      launcherStates.push(state);
      return {
        owner,
        state,
        view: {
          primary: inheritedProfile
            ? { profile: { agent: 'claude', model: 'opus', effort: 'high', permissionMode: 'auto', source: 'recent' } }
            : null,
        },
      };
    },
    folders() {
      return ['C:/workspace'];
    },
    abandonDraft() {},
    createDraft(id: string, _cwd: string, source: string | null) {
      created.push({ id, source, mapped: hostSessions.get(host) ?? null });
    },
    sendToHost(owner: unknown, message: unknown) {
      sent.push({ owner, message });
      return Promise.resolve(true);
    },
    post(message: unknown) {
      broadcast.push(message);
      return Promise.resolve();
    },
  };

  assert.equal(newSession.call(provider, undefined, host), true);
  assert.deepEqual(created, [
    { id: `${DRAFT_SESSION_PREFIX}new-draft`, source: 'navigated', mapped: `${DRAFT_SESSION_PREFIX}new-draft` },
  ]);
  assert.deepEqual(launcherStates, [{ sessionId: 'navigated', webview: host.webview }]);
  assert.equal(
    hostSessions.get(host),
    `${DRAFT_SESSION_PREFIX}new-draft`,
    'the navigated panel host kept rendering its prior session after New created a draft',
  );
  assert.deepEqual(sent.at(-1), {
    owner: host,
    message: { type: 'focusComposer', session: `${DRAFT_SESSION_PREFIX}new-draft` },
  });
  assert.deepEqual(broadcast, []);

  hostSessions.set(host, 'navigated');
  assert.equal(newSession.call(provider), true);
  assert.equal(
    hostSessions.get(host),
    `${DRAFT_SESSION_PREFIX}new-draft`,
    'the command route left the active panel host on its prior session',
  );
  assert.deepEqual(launcherStates.at(-1), { sessionId: 'navigated', webview: host.webview });

  inheritedProfile = false;
  hostSessions.set(host, 'navigated');
  assert.equal(newSession.call(provider, undefined, host), false);
  assert.deepEqual(sent.at(-1), { owner: host, message: { type: 'openLauncher', custom: true } });
  assert.deepEqual(broadcast, []);

  inheritedProfile = true;
  active = false;
  hostSessions.set(host, 'navigated');
  assert.equal(newSession.call(provider), true);
  assert.equal(hostSessions.get(host), 'navigated');
  assert.deepEqual(launcherStates.at(-1), { sessionId: 'global' });
  assert.deepEqual(broadcast.at(-1), { type: 'focusComposer', session: `${DRAFT_SESSION_PREFIX}new-draft` });
});

test('/clear publishes the copied setup', () => {
  const move = new Function(
    'succeedSession',
    'labelsOf',
    'setSessionLabels',
    `return function (source, successor, agent, cwd) {\n${methodBody('public noteSessionMoved(')}\n};`,
  )(succeedSession, labelsOf, setSessionLabels) as (
    this: Record<string, unknown>,
    source: string,
    successor: string,
    agent: string,
    cwd: string,
  ) => void;
  const settings = {
    selectedModel: 'opus',
    selectedEffort: 'high',
    permissionMode: 'plan',
    effortModel: 'opus',
    pendingModel: null,
    pendingEffort: null,
  };
  let persisted: SessionSettingBook = { old: settings };
  const posted: Array<{ type: string; session: string }> = [];
  const memento = {
    value: undefined as unknown,
    update(_key: string, value: unknown) {
      this.value = structuredClone(value);
      return Promise.resolve();
    },
  };
  const saved = normalizePanelState(null);
  saved.labels = setSessionLabels(saved.labels, 'old', ['keep']);
  const queuedAsset: StoredPromptAsset = {
    id: '11111111-1111-4111-8111-111111111111',
    name: 'shot.png',
    mime: 'image/png',
    size: 1,
    digest: '1'.repeat(64),
  };
  const mappedHost = { tab: 'cleared session' };
  const host = {
    clearSettlements: new Map(),
    drafts: { old: 'unsent text' },
    assets: { old: [queuedAsset] },
    queues: { old: [{ id: 'q1', text: 'queued', commentIds: [], assets: [], at: 1 }] },
    live: {},
    picks: { old: settings },
    draftProfiles: {},
    sessionOrigins: {},
    sentPrompts: {},
    boxText: {},
    railOrder: ['old'],
    showing: 'old',
    hostSessions: new Map([[mappedHost, 'old']]),
    awaitingSessionRecords: {},
    newDrafts: {},
    promptsBySession: new Map(),
    draftCommentIds: {},
    saved,
    memento,
    rememberStarted() {
      /* Keep started-session persistence inactive to isolate label copying and writeDrafts persistence. */
    },
    refresh() {
      /* Inspect persisted state without rendering. */
    },
    post(msg: { type: string; session: string }) {
      posted.push(msg);
      return Promise.resolve();
    },
    writeDrafts() {
      this.saved.drafts = normalizeDrafts(this.drafts);
      this.saved.sentPrompts = sentPromptsToSave(this.sentPrompts, this.promptsBySession);
      this.saved.assets = normalizePromptAssetBook(this.assets);
      this.saved.queues = normalizeQueuedSubmissions(this.queues);
      return Promise.resolve(this.memento?.update('state', this.saved));
    },
    onSessionSettingsAdopted(session: string, accepted: typeof settings) {
      persisted = withSessionSettings(persisted, session, accepted);
    },
    finishClearSettlement() {},
  };
  move.call(host, 'old', 'new', 'claude', 'C:\\ws');
  assert.equal(
    host.hostSessions.get(mappedHost),
    'new',
    'the mapped editor tab still renders and submits against the cleared source session',
  );
  assert.deepEqual(
    sessionSettings(persisted, 'new'),
    settings,
    'retiring the cleared child leaves its successor with no accepted setup to reopen',
  );
  assert.deepEqual(
    sessionSettings(persisted, 'old'),
    settings,
    'publishing the successor removed the predecessor setup that remains resumable',
  );
  assert.deepEqual(
    labelsOf(host.saved.labels, 'new'),
    ['keep'],
    "the successor did not inherit the source session's labels",
  );
  assert.deepEqual(
    labelsOf(host.saved.labels, 'old'),
    ['keep'],
    "copying labels onto the successor emptied the source session's own labels",
  );
  assert.deepEqual(
    posted,
    [{ type: 'labelsChanged', session: 'new' }],
    'an open label editor was not told to redraw for the copied labels',
  );
  const persistedState = memento.value as {
    labels: Record<string, string[]>;
    queues: Record<string, unknown>;
    assets: Record<string, unknown>;
  };
  assert.deepEqual(
    labelsOf(persistedState?.labels, 'new'),
    ['keep'],
    'the copied labels on the successor did not reach the memento',
  );
  assert.deepEqual(
    labelsOf(persistedState?.labels, 'old'),
    ['keep'],
    "the source session's own labels did not reach the memento",
  );
  assert.deepEqual(
    Object.keys(persistedState?.queues ?? {}),
    ['new'],
    'the queued submission moved off the source did not reach the memento under the successor',
  );
  assert.deepEqual(
    Object.keys(persistedState?.assets ?? {}),
    ['new'],
    'the attachment moved off the source did not reach the memento under the successor',
  );
});

