test('a press on a draft whose first prompt has gone changes nothing', () => {
  const starting = draftPanel(DRAFT_SETUP, [DRAFT_SENT]);
  starting.press('agent', 'codex');
  // A submitted first prompt locks the draft setup used for launch.
  assert.equal(
    starting.newDrafts.d1.profile.agent,
    'claude',
    'a draft that is starting takes a press, so the row names an agent its child is not',
  );
  assert.equal(
    starting.draftProfiles.d1.agent,
    'claude',
    'a draft that is starting takes a press, so adoption carries a setup the child never had',
  );
  assert.deepEqual(
    starting.picks,
    {},
    'a draft that is starting takes a press, so the row draws a setup nothing runs on',
  );
  assert.deepEqual(
    [starting.refreshed.length, starting.posted.length],
    [0, 0],
    'a press that changes nothing repaints anyway',
  );

  // A failed first prompt leaves the setup editable for a retry.
  const failed = draftPanel(DRAFT_SETUP, [{ ...DRAFT_SENT, failed: true, reason: 'the agent never answered' }]);
  failed.press('agent', 'codex');
  assert.equal(
    failed.newDrafts.d1.profile.agent,
    'codex',
    'a draft whose prompt never left refuses the press that would let the reader try again',
  );
});

// Run stateForRow with a placeholder read window for drafts.
function stateForRow(
  rows: { id: string; label: string; agentKey: string }[],
  drafts: Record<string, NewSessionDraft>,
  id: string,
  selected: {
    newest?: Map<string, ReturnType<typeof turn>>;
    compactions?: Map<string, ReturnType<typeof compaction>>;
    runtime?: ReturnType<typeof composerRuntimeBySession>;
  } = {},
  overrides: {
    catalog?: { sessions: { agent: string; sessionId: string; cwd: string }[] };
    awaitingSessionRecords?: Record<string, { cwd: string }>;
    folders?: () => string[];
    skillLists?: Record<string, readonly string[]>;
    commandLists?: Record<string, PromptEntry[]>;
    picks?: SessionSettingBook;
    askLevels?: Record<string, string>;
    codexEffectiveModes?: Record<string, unknown>;
    claudeEffectiveModes?: Record<string, string>;
  } = {},
): ComposerState {
  const read = new Function(
    'windowFor',
    'currentContextOf',
    'nextTurnBasisOf',
    'sessionSettings',
    'sessionRunning',
    'promptHistory',
    'normalizeWorkspace',
    'storedAskValue',
    `return function (row, webview) {\n${methodBody('private stateForRow(')}\n};`,
  )(
    () => null,
    currentContextOf,
    nextTurnBasisOf,
    sessionSettings,
    sessionRunning,
    promptHistory,
    normalizeWorkspace,
    storedAskValue,
  ) as (this: unknown, row: unknown) => ComposerState;
  // Compile both working-directory lookups from the host source.
  const cwdForSession = new Function(
    `return function (agent, sessionId) {\n${methodBody('private cwdForSession(')}\n};`,
  )() as (this: unknown, agent: string, sessionId: string) => string | null;
  const ownCwdForSession = new Function(
    `return function (agent, sessionId) {\n${methodBody('private ownCwdForSession(')}\n};`,
  )() as (this: unknown, agent: string, sessionId: string) => string | null;
  const claudeCommandsFor = new Function(
    'claudeSkillPath',
    `return function (cwd) {\n${methodBody('private claudeCommandsFor(')}\n};`,
  )(claudeSkillPath) as (this: unknown, cwd: string | null) => PromptEntry[];
  const host = {
    newestBySession: selected.newest ?? new Map(),
    newestCompactionBySession: selected.compactions ?? new Map(),
    composerRuntime:
      selected.runtime ??
      composerRuntimeBySession([...(selected.newest?.values() ?? [])], selected.compactions ?? new Map()),
    picks: overrides.picks ?? {},
    newDrafts: drafts,
    // Supply a conflicting draftProfiles entry to identify which profile the prompt box reads.
    draftProfiles: Object.fromEntries(Object.keys(drafts).map((id) => [id, OTHER_BOOK_SETUP])),
    sessionRows: rows,
    sessionOrigins: {},
    drafts: {},
    boxText: {},
    sentPrompts: {},
    promptsBySession: new Map(),
    queues: {},
    running: new Set(),
    saved: { comments: [] },
    models: {},
    commandLists: overrides.commandLists ?? {},
    claudeSkillPaths: new Map<string, string | null>(),
    skillLists: overrides.skillLists ?? {},
    catalog: overrides.catalog ?? null,
    awaitingSessionRecords: overrides.awaitingSessionRecords ?? {},
    folders: overrides.folders ?? (() => []),
    cwdForSession,
    ownCwdForSession,
    claudeCommandsFor,
    mcpServers: {},
    askLevels: overrides.askLevels ?? {},
    codexEffectiveModes: overrides.codexEffectiveModes ?? {},
    claudeEffectiveModes: overrides.claudeEffectiveModes ?? {},
    live: {},
    asks: [],
    draftCommentIds: {},
    promptAssets: () => [],
    attachmentNotices: {},
  };
  return read.call(
    host,
    rows.find((row) => row.id === id),
  );
}

// This conflicting profile belongs only to the draftProfiles fixture map.
const OTHER_BOOK_SETUP: SessionProfile = {
  agent: 'codex',
  model: 'gpt-5',
  effort: 'medium',
  permissionMode: 'on-request',
  source: 'recent',
};

