test('every tone panel.css draws as text reads at 4.5 to 1, or is a named exception', () => {
  // Measure stylesheet text tones in the dark and light theme fixtures.
  // Named exceptions retain their measured ratios.
  const THEMES = [
    { id: 'dark', kind: 'dark', table: DARK_MODERN_THEME },
    { id: 'light', kind: 'light', table: LIGHT_MODERN_THEME },
  ] as const;

  // Exception ratios must remain within the asserted rounding tolerance.
  const KNOWN_FAILING: Partial<Record<string, Partial<Record<'dark' | 'light', number>>>> = {
    // The full context band's background mix reduces contrast below 4.5 in both theme fixtures.
    full: { dark: 2.65, light: 2.04 },
    // The notice context band's background mix reduces contrast below 4.5 in both theme fixtures.
    notice: { dark: 3.94, light: 4.28 },
    // The draft chip's modified-color mix falls below 4.5 in the light theme fixture.
    mod: { light: 3.93 },
    // The added-text tone falls below 4.5 in the light theme fixture.
    add: { light: 3.92 },
    // The deleted-text tone falls below 4.5 in the dark theme fixture.
    del: { dark: 2.58 },
  };

  // comment and unread are decoration tones, so text-tone measurements exclude them.
  const readings = measureTones(styleSource, THEMES, { skip: Object.keys(EXCLUDED_TONES) });
  assert.ok(readings.length, 'the scan found no tone that panel.css draws as text');
  for (const { tone, kind, worst } of readings) {
    const pinned = KNOWN_FAILING[tone]?.[kind];
    if (pinned === undefined) {
      assert.ok(
        worst >= 4.5,
        `--${tone} reads at ${worst.toFixed(2)} to 1 on a ${kind} panel and carries no recorded exception; ` +
          `fix it or add it to KNOWN_FAILING`,
      );
    } else {
      assert.ok(
        Math.abs(worst - pinned) < 0.03,
        `--${tone} now reads at ${worst.toFixed(2)} to 1 on a ${kind} panel, not the pinned ${pinned}; ` +
          `update KNOWN_FAILING to match, whichever way it moved`,
      );
    }
  }

  // The editor-supplied idle text tone remains below 4.5 in the dark theme fixture.
  const darkIdle = /--vscode-descriptionForeground:([^;]+);/.exec(DARK_MODERN_THEME);
  const lightIdle = /--vscode-descriptionForeground:([^;]+);/.exec(LIGHT_MODERN_THEME);
  assert.ok(
    darkIdle && lightIdle,
    'the theme fixtures no longer carry a description-text colour to measure --idle against',
  );
  const darkIdleWorst = worstOf(darkIdle[1], BACKGROUNDS.dark);
  const lightIdleWorst = worstOf(lightIdle[1], BACKGROUNDS.light);
  assert.ok(
    darkIdleWorst < 4.5,
    `--idle now reads at ${darkIdleWorst.toFixed(2)} to 1 on a dark panel; the recorded exception no longer applies, so update this comment`,
  );
  // The idle text tone clears 4.5 on every measured background in the light theme fixture.
  assert.ok(
    lightIdleWorst >= 4.5,
    `--idle now reads at ${lightIdleWorst.toFixed(2)} to 1 on a light panel, below 4.5; the exception may need to cover light too`,
  );
});

test('two status tones a reader tells apart never converge', () => {
  // Background contrast does not measure the difference between two status colors.
  const THEMES = [
    { id: 'dark', kind: 'dark', table: DARK_MODERN_THEME },
    { id: 'light', kind: 'light', table: LIGHT_MODERN_THEME },
  ] as const;

  // Compare each pair's minimum CIEDE2000 distance with its stored baseline.
  const BASELINE: Record<'dark' | 'light', Record<string, number>> = {
    dark: {
      'busy/need': 9.16,
      'warn/need': 16.19,
      'warn/busy': 18.78,
      'bad/busy': 18.84,
      'bad/need': 20.1,
      'ok/warn': 35.95,
      'ok/busy': 36.13,
      'bad/warn': 36.65,
      'ok/need': 42.89,
      'ok/bad': 56.88,
    },
    light: {
      'warn/busy': 6.22,
      'busy/need': 7.47,
      'warn/need': 13.15,
      'bad/need': 18.24,
      'bad/busy': 21.87,
      'bad/warn': 27.91,
      'ok/warn': 29.93,
      'ok/busy': 34.87,
      'ok/need': 42.9,
      'ok/bad': 60.6,
    },
  };

  // Allow each pair to move by 15% of its baseline or 1.5, whichever is greater.
  // This tolerance is policy, not a perception threshold.
  const allowanceFor = (baseline: number) => Math.max(1.5, baseline * 0.15);

  // Apply an independent distance floor so edited baselines cannot admit equal tones.
  const FLOOR = 6;

  // Require two disjoint status-tone pairs whose narrower distance reaches APART.
  // This limit does not depend on the editable baseline table.
  const APART = 20;

  // Every tone used by a session-list status selector must appear in STATUS_TONES.
  const onTheRail = statusSelectorTones(styleSource);
  assert.ok(onTheRail.length, 'no tone was found painting a rail status word');
  for (const tone of onTheRail) {
    assert.ok(
      (STATUS_TONES as readonly string[]).includes(tone),
      `panel.css paints a rail status with --${tone}, which STATUS_TONES does not name, ` +
        'so no pair comparison ever sees it',
    );
  }
  const drawn = new Set(textToneNames(styleSource));
  for (const tone of STATUS_TONES) {
    assert.ok(
      drawn.has(tone),
      `STATUS_TONES names --${tone}, which panel.css no longer draws as a word; ` +
        'rename it here or take it out of the list',
    );
  }

  const rows = statusToneDistances(styleSource, THEMES);
  const seen = new Set(rows.map((r) => `${r.kind} ${r.pair}`));
  assert.equal(seen.size, rows.length, 'a pair was measured twice in one theme');
  for (const kind of ['dark', 'light'] as const) {
    assert.deepEqual(
      new Set(rows.filter((r) => r.kind === kind).map((r) => r.pair)),
      new Set(Object.keys(BASELINE[kind])),
      `the ${kind} sweep and the ${kind} baseline table name different pairs`,
    );
  }

  // Check decreasing distances before increasing distances.
  const byFall = rows
    .slice()
    .sort((a, b) => a.distance - BASELINE[a.kind][a.pair] - (b.distance - BASELINE[b.kind][b.pair]));
  // Apply the independent floor before baseline-relative allowances.
  assert.ok(
    Math.min(...Object.values(BASELINE.light), ...Object.values(BASELINE.dark)) > FLOOR,
    `a recorded baseline has reached the ${FLOOR} floor, so the table no longer holds anything ` +
      'above it and the floor is the only check left; that is not a design, it is a symptom',
  );
  for (const { pair, kind, values, grounds, distance } of byFall) {
    assert.ok(
      distance >= FLOOR,
      `${pair} sits ${distance.toFixed(2)} apart on a ${kind} panel, under the ${FLOOR} this ` +
        `panel holds whatever the baseline says; ${values[0]} on ${grounds[0]} and ` +
        `${values[1]} on ${grounds[1]} are one colour`,
    );
  }
  for (const { pair, kind, values, grounds, distance } of byFall) {
    const was = BASELINE[kind][pair];
    const room = allowanceFor(was);
    assert.ok(
      distance >= was - room,
      `${pair} fell to ${distance.toFixed(2)} on a ${kind} panel from ${was}, over the ` +
        `${room.toFixed(2)} this panel allows it; ${values[0]} on ${grounds[0]} and ` +
        `${values[1]} on ${grounds[1]} are what converge`,
    );
  }
  // Check disjoint-pair separation before reporting increased pair distances.
  for (const kind of ['dark', 'light'] as const) {
    const held = widestDisjointPair(rows.filter((r) => r.kind === kind));
    assert.ok(
      held >= APART,
      `no two ${kind} status pairs that share no tone are both more than ${held.toFixed(2)} ` +
        `apart, where this panel holds a pair of them over ${APART} whatever the baseline ` +
        'says; the set has become one cluster with an outlier, and no single pair is where it ' +
        'shows',
    );
  }

  // This clustered palette clears the contrast and pair-floor limits but must fail disjoint-pair separation.
  const CLUSTERED: Record<string, string> = {
    ok: '#581e5b',
    bad: '#553e6d',
    warn: '#502f52',
    busy: '#774b0e',
    need: '#653377',
  };
  let clustered = styleSource;
  const lightAt = styleSource.indexOf('body.vscode-light');
  assert.ok(lightAt > 0, 'the light block is gone, so this attack no longer applies');
  for (const [tone, value] of Object.entries(CLUSTERED)) {
    const at = clustered.indexOf(`--${tone}:`, lightAt);
    assert.ok(at > 0, `the light block no longer declares --${tone}`);
    clustered = clustered.slice(0, at) + `--${tone}: ${value};` + clustered.slice(clustered.indexOf(';', at) + 1);
  }
  const cluster = statusToneDistances(clustered, THEMES).filter((r) => r.kind === 'light');
  for (const { pair, distance } of cluster) {
    assert.ok(
      distance >= FLOOR,
      `${pair} of the clustered palette sits ${distance.toFixed(2)} apart, under FLOOR, so ` +
        'that palette is caught one pair at a time and proves nothing about the set',
    );
  }
  for (const value of Object.values(CLUSTERED)) {
    const worst = chipWorstOf(value, BACKGROUNDS.light, CHIP_MIX.warn ?? 18);
    assert.ok(
      worst >= 4.5,
      `a word of the clustered palette reads at ${worst.toFixed(2)}, so the contrast guard ` +
        'catches it and this proves nothing about the set',
    );
  }
  const clusterHeld = widestDisjointPair(cluster);
  assert.ok(
    clusterHeld < APART,
    `a light palette closed into a cluster still offers two pairs sharing no tone at ` +
      `${clusterHeld.toFixed(2)}, so this no longer rejects the shape it exists for`,
  );

  for (const { pair, kind, distance } of rows) {
    const was = BASELINE[kind][pair];
    assert.ok(
      distance <= was + allowanceFor(was),
      `${pair} improved to ${distance.toFixed(2)} on a ${kind} panel from ${was}; ` +
        'record the new figure in BASELINE so the gain is what the next change is held to',
    );
  }
});

test('panel.css sizes every word in a unit the editor can move', () => {
  // Text sizing must follow the editor's font-size setting.
  // Check font, font-size, and line-height values after resolving custom properties and excluding comments.
  // Reject absolute, root-relative, and viewport-relative units.
  const FIXED = /\d\s*(px|pt|pc|cm|mm|in|q|r(em|ex|ch|cap|ic|lh)|[sld]?v(w|h|i|b|min|max))\b/i;
  const blanked = styleSource.replace(/\/\*[\s\S]*?\*\//g, (block) => block.replace(/[^\n]/g, ' '));
  const tokens = new Map<string, string>();
  for (const declared of blanked.matchAll(/(--[\w-]+)\s*:\s*([^;{}]+)/g)) {
    tokens.set(declared[1], declared[2].trim());
  }
  const resolve = (value: string): string => {
    let text = value;
    for (let pass = 0; pass < 5 && text.includes('var('); pass += 1) {
      const next = text.replace(/var\(\s*(--[\w-]+)[^()]*\)/g, (whole, name) => tokens.get(name) ?? whole);
      if (next === text) {
        break;
      }
      text = next;
    }
    return text;
  };
  const offenders: string[] = [];
  for (const found of blanked.matchAll(/(?:^|[;{}])\s*(font|font-size|line-height)\s*:\s*([^;}]+)/gi)) {
    if (!FIXED.test(resolve(found[2]))) {
      continue;
    }
    const before = blanked.slice(0, found.index + found[0].indexOf(found[1]));
    const opens = before.lastIndexOf('{');
    const encloses = Math.max(before.lastIndexOf('}', opens), before.lastIndexOf('{', opens - 1));
    const selector = before
      .slice(encloses + 1, opens)
      .replace(/\s+/g, ' ')
      .trim();
    const line = before.split('\n').length;
    offenders.push(`panel.css:${line} ${selector} { ${found[1]}: ${found[2].trim()} }`);
  }
  assert.deepEqual(
    offenders,
    [],
    'a word sized in a unit the editor cannot move does not follow the font size the reader ' +
      'chose. Use --t-body or --t-small, a multiple of the parent in em, or an unitless line ' +
      'height.',
  );
});

