// Pin every size token's declarations, including tokens referenced by other size tokens.
// The editor owns vscode-font-size, so the stylesheet declares no value for it.
const SIZE_TOKENS: Record<string, string[]> = {
  '--t-small': ['body { --t-small: 0.86em }'],
  '--t-figure': ['body { --t-figure: calc(0.92 * var(--vscode-font-size)) }'],
  '--t-body': ['body { --t-body: 0.92em }'],
  '--heading-step': ['body { --heading-step: 1.06 }'],
  '--vscode-font-size': [],
};

const THEME_SELECTOR = /vscode-(light|dark|high-contrast)|data-vscode-theme/;

test('every figure on a card draws at one size', () => {
  const rules = cssContract(styleSource);
  const figureClasses = classWords(
    FIGURE_BUILDERS.map((file) => path.join(__dirname, file)),
    { file: path.join(__dirname, 'panelfixture.ts'), type: 'FigureClassValues' },
  );
  EDITOR_BODY_CLASSES.forEach((name) => figureClasses.words.add(name));
  const written = (rule: CssRule, declaration: string): string =>
    `${[...rule.conditions, rule.selector].join(' { ')} { ${declaration} }`;
  // Match sizing properties without case sensitivity, including the all reset.
  const sizing = (text: string): boolean => /^(font|font-size|all):/i.test(text);
  const complaints: string[] = [];
  const sizes: string[] = [];
  for (const rule of rules) {
    const scoped = [...rule.conditions, rule.selector].join(' ');
    if (!namesClassWord(scoped, figureClasses) && !cssSelectors(rule.selector).some(bareSubject)) continue;
    for (const declaration of rule.declarations.filter(sizing)) {
      const home = written(rule, declaration);
      sizes.push(home);
      if (rule.conditions.some((condition) => condition.startsWith('@'))) {
        complaints.push(`\`${home}\` sizes an element around a figure inside an at-rule`);
      }
      if ([...rule.conditions, rule.selector].some((text) => THEME_SELECTOR.test(text))) {
        complaints.push(`\`${home}\` sizes an element around a figure under a theme selector`);
      }
      if (/!\s*important/i.test(declaration)) {
        complaints.push(`\`${home}\` sizes an element around a figure with \`!important\``);
      }
    }
  }
  // Follow custom-property references in sizing declarations.
  const reads = (text: string): string[] => [...text.matchAll(/var\(\s*(--[\w-]+)/g)].map((match) => match[1]);
  const pending = sizes.flatMap(reads);
  const tokens: Record<string, string[]> = {};
  for (let token = pending.shift(); token !== undefined; token = pending.shift()) {
    if (token in tokens) continue;
    const declarations = rules.flatMap((rule) =>
      rule.declarations.filter((text) => text.startsWith(`${token}:`)).map((text) => ({ rule, text })),
    );
    tokens[token] = declarations.map(({ rule, text }) => written(rule, text));
    declarations.forEach(({ text }) => pending.push(...reads(text)));
  }
  assert.deepEqual(
    complaints,
    [],
    'a figure on a card takes a size that holds at one width, in one theme, or over every other ' +
      'rule. Keep at-rules, theme selectors and `!important` off every rule that sizes a figure.',
  );
  assert.deepEqual(
    sizes,
    FIGURE_SIZES,
    'a figure on a card, or an element around one, takes its size from a different set of rules. ' +
      'A rule added here is a second home for a size even when it carries the value the first one carries.',
  );
  // Scope commitheadfact sizing to card headings because popover headings also use that class.
  assert.deepEqual(
    rules
      .filter((rule) => rule.declarations.some(sizing))
      .flatMap((rule) => cssSelectors(rule.selector))
      .filter((selector) => selector === '.commitheadfact'),
    [],
    'a size rule names `.commitheadfact` on its own, which also sizes the branch fact inside a ' +
      "stat popover's heading. Scope the selector to the card's Commits heading, such as " +
      '`.recordcommits .commitheadfact`.',
  );
  assert.deepEqual(
    Object.entries(SIZE_TOKENS)
      .filter(([token, homes]) => homes.length !== (token.startsWith('--vscode-') ? 0 : 1))
      .map(([token]) => token),
    [],
    'a size token in the list has a second declaration, or the stylesheet declares a token the editor writes',
  );
  assert.deepEqual(
    tokens,
    SIZE_TOKENS,
    'a size token a figure reads has a second declaration or a different value, so a figure ' +
      'draws at a size its own rule does not say',
  );
});

// Apply heading-step to the section word, letter spacing, and bottom margin.
// The adjacent count retains its figure size.
test('a section head lifts its word and carries the step through its spacing', () => {
  assert.deepEqual(cssDeclarations(styleSource, '.sec-word'), ['font-size: calc(1em * var(--heading-step))']);
  assert.ok(
    cssDeclarations(styleSource, '.sec-title').includes('letter-spacing: calc(0.01em * var(--heading-step))'),
    'the tracking on a section head no longer carries the heading step, so the head tracks tighter than its word',
  );
  assert.ok(
    cssDeclarations(styleSource, '.sectionheading > .sec-title').includes(
      'margin-bottom: calc(0.5em * var(--heading-step))',
    ),
    'the gap under a section head no longer carries the heading step, so the head sits closer to what it names',
  );
  assert.deepEqual(
    cssDeclarations(styleSource, '.sec-title').filter((text) => /^font:|^font-size:/.test(text)),
    [],
    'the section head sizes its own text again, so the counted total inside it draws larger than a chip',
  );

  const heads = [...cardSource.matchAll(/class: '(sec-title[^']*)'/g)];
  assert.ok(heads.length >= 5, `card.ts builds ${heads.length} section heads, fewer than the five it used to build`);
  const bare = heads
    .map((head) => {
      const at = (head.index ?? 0) + head[0].length;
      const after = cardSource.slice(at, at + 90);
      return /class: '([\w -]+)'/.exec(after)?.[1] === 'sec-word' ? null : `\`${head[1]}\``;
    })
    .filter((head) => head !== null);
  assert.deepEqual(
    bare,
    [],
    'a section head puts its word straight into `.sec-title`, so the word draws at the card size rather than the heading size',
  );
  assert.equal(
    (cardSource.match(/class: 'sec-word'/g) ?? []).length,
    heads.length,
    'card.ts builds a different number of heading words and section heads',
  );
});

