test('the rail is reworded when work starts or stops, and not on every event', () => {
  // Refresh session-list status only when the running-session set changes.
  const marker = 'public setRunning(';
  const from = panelHostSource.indexOf(marker);
  assert.notEqual(from, -1, 'setRunning is no longer where the rail hears about work in flight');
  const body = memberFrom(panelHostSource, from);
  sourceMatch(
    body,
    /const moved = next\.size !== this\.running\.size \|\| \[\.\.\.next\]\.some\(\(key\) => !this\.running\.has\(key\)\);/,
    'setRunning no longer compares the two sets, so it cannot tell a change from a repeat',
  );
  sourceMatch(
    body,
    /if \(moved\) \{ void this\.refresh\(true\); \}/,
    'setRunning no longer redraws cards and the rail when process liveness changes',
  );
  sourceDoesNotMatch(
    body.replace(/if \(moved\) \{\s*void this\.refresh\(true\);\s*\}/, ''),
    /this\.refresh\(/,
    'the panel refresh runs outside the guard, so every streamed event rebuilds it',
  );
});

test('activity changes leave the rail order alone while a host remains open', () => {
  // The catalog orders by activity, while the session list reconciles its displayed order separately.
  sourceMatch(
    panelHostSource,
    /const walkedSessions = orderSessionCatalog\(\[\.\.\.listed, \.\.\.this\.claudeChildren, \.\.\.codex\],[\s\S]*this\.activityFor\(session\)\);/,
    'the stable rail order replaced the recency order used outside the rail',
  );
  // Reused catalogs also order by the current activity reading.
  sourceMatch(
    panelHostSource,
    /const sorted = orderSessionCatalog\(admitted, \(session\) => this\.activityFor\(session\)\);/,
    'a reused catalog keeps the order it was walked in, so a session that grew stays put',
  );
  const rowsAt = panelHostSource.indexOf(
    'private railRows(statuses: ReturnType<typeof sessionStatusOf>): typeof this.sessionRows',
  );
  assert.notEqual(rowsAt, -1, 'the rail has no ordering seam of its own');
  const rows = memberFrom(panelHostSource, rowsAt);
  sourceMatch(
    rows,
    /stableRailOrder\(this\.sessionRows, this\.railOrder, statuses\)/,
    'the rail takes the activity-sorted rows directly, so running sessions move on every write',
  );
  sourceMatch(
    rows,
    /this\.railOrder = ordered\.map\(\(row\) => row\.id\);/,
    'the reconciled order is not retained for the next refresh',
  );

  const attach = panelHostSource.slice(
    panelHostSource.indexOf('private attach(host: PanelHost)'),
    panelHostSource.indexOf('private anyVisible()'),
  );
  sourceMatch(
    attach,
    /if \(!this\.hosts\.length\) \{ this\.railOrder = \[\]; this\.boxText = \{\}; \}/,
    'a new set of panel hosts inherits an old rail order instead of seeding from current activity',
  );
  const postAt = panelHostSource.indexOf('private postRail(');
  assert.notEqual(postAt, -1, 'running-state changes have no rail update path');
  const post = memberFrom(panelHostSource, postAt);
  sourceMatch(
    post,
    /if \(!this\.hosts\.length\) \{ return; \}[\s\S]*this\.railInputFor\(counts, statuses, openChildren, railNow\)/,
    'a running-state update after the last host closes repopulates the cleared order from stale rows',
  );
  const railPayloadAt = panelHostSource.indexOf('private railInputFor(');
  const railPayload = memberFrom(panelHostSource, railPayloadAt);
  sourceMatch(railPayload, /sessions: this\.railRows\(statuses\)/, 'the shared payload bypasses the stable rail order');
});

test('unread dots keep the same column across session statuses', () => {
  const dot = styleRule('.railcard.is-unread::before');
  const left = /left: (?:calc\((\d+)px - var\((--[\w-]+)\)\)|(\d+)px);/.exec(dot);
  const size = /width: (\d+)px;/.exec(dot);
  assert.ok(left && size, 'the unread dot is no longer placed and sized in the card padding');
  const inset = Number(left[1] ?? left[3]);
  const property = left[2];
  const plain = styleRule('.railcard');
  const defaultCompensation = property ? new RegExp(`${property}: (\\d+)px;`).exec(plain) : null;
  assert.ok(!property || defaultCompensation, 'the unread dot has no default border compensation');
  const plainOffset = inset - Number(defaultCompensation?.[1] ?? 0);
  for (const status of [null, 'running', 'subagents', 'background', 'waiting', 'failed']) {
    const rule = status ? styleRulesNaming(`.railcard.${status}`) : plain;
    const border = Number(/border-left: (\d+)px solid/.exec(rule)?.[1] ?? 0);
    const compensation = property ? new RegExp(`${property}: (\\d+)px;`).exec(rule) : null;
    const compensated = Number(compensation?.[1] ?? defaultCompensation?.[1] ?? 0);
    const offset = border + inset - compensated;
    assert.equal(offset, plainOffset, `the unread dot shifts on a ${status ?? 'quiet'} session`);
    assert.equal(compensated, border, `the unread dot compensation differs from the ${status ?? 'quiet'} border`);
    const padding = status ? Number(/padding-left: (\d+)px;/.exec(rule)?.[1]) : railCardIndent();
    assert.ok(Number.isFinite(padding), `a ${status} card has no title indent`);
    const room = border + padding - offset - Number(size[1]);
    assert.ok(room > Number(size[1]), `the unread dot touches the ${status ?? 'quiet'} session title`);
  }
  assert.doesNotMatch(
    styleRulesNaming("#rail[data-density='compact'] .railcard.is-unread::before"),
    /(?:^|\s)left:/,
    'compact rows replace the shared unread dot column',
  );
});

test('the card menu offers the read state and the copy, and none of it in the palette', () => {
  // Pin native menu labels from the extension manifest.
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const titles = new Map<string, string>(
    manifest.contributes.commands.map((c: { command: string; title: string }) => [c.command, c.title]),
  );
  assert.equal(titles.get('arc.markTurnRead'), 'Mark as read');
  assert.equal(titles.get('arc.markTurnUnread'), 'Mark as unread');
  assert.equal(titles.get('arc.copyTurnSummary'), 'Copy the summary');
  assert.equal(titles.get('arc.commentOnTurn'), 'Add a comment');

  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const whenOf = (command: string) => menu.filter((m) => m.command === command).map((m) => m.when);
  // Build menu conditions from the shared turn-section identifiers.
  // Read and unread actions apply only to the states they change.
  const S = TURN_MENU_SECTIONS;
  const on = (...names: string[]) => names.map((n) => `webviewSection == '${n}'`).join(' || ');
  assert.deepEqual(
    whenOf('arc.markTurnRead'),
    [on(S.unread, S.unreadSummary)],
    'Mark as read is not offered on exactly the cards that are unread',
  );
  assert.deepEqual(
    whenOf('arc.markTurnUnread'),
    [on(S.read, S.readSummary)],
    'Mark as unread is not offered on exactly the cards that are read',
  );
  assert.deepEqual(
    whenOf('arc.copyTurnSummary'),
    [on(S.readSummary, S.unreadSummary, S.summary)],
    'Copy the summary is not offered on exactly the cards that hold one',
  );
  // The comment action uses arcTurn, including cards without a summary or read-state section.
  assert.deepEqual(
    whenOf('arc.commentOnTurn'),
    ['arcTurn'],
    'the comment entry is offered by section, so a card naming none is offered nothing',
  );
  // Order copy actions after read actions, then comment actions.
  assert.equal(
    menu.filter((m) => m.command === 'arc.copyTurnSummary')[0].group,
    '2_copy@1',
    'the copy is not grouped below the read entries',
  );
  assert.equal(
    menu.filter((m) => m.command === 'arc.commentOnTurn')[0].group,
    '3_comment@1',
    'the comment is not grouped below the copy',
  );

  // Card context actions stay outside the command palette.
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  for (const command of ['arc.markTurnRead', 'arc.markTurnUnread', 'arc.copyTurnSummary', 'arc.commentOnTurn']) {
    assert.ok(
      palette.some((m) => m.command === command && m.when === 'false'),
      `${command} is in the command palette, where it has no card to act on`,
    );
  }

  // Keep the file-section entry first for the manifest section check.
  assert.equal(
    menu[0].when,
    "webviewSection == 'arcFile'",
    'a file entry no longer leads the webview menu, so the section guard now reads a different one',
  );
});

