test('local HTML and Markdown response links use their readers', () => {
  const opener = panelHostSource.slice(
    panelHostSource.indexOf('async function openLink('),
    panelHostSource.indexOf('// A picture the reader pressed', panelHostSource.indexOf('async function openLink(')),
  );
  const directory = opener.indexOf("executeCommand('revealInExplorer', uri)");
  const html = opener.indexOf("if (uri.scheme === 'file' && linkTargetIsHtml(uri.fsPath))");
  assert.ok(directory !== -1 && html > directory, 'an HTML-named directory bypasses the existing directory action');

  // Open image links with the editor viewer before checking the HTML branch.
  const image = opener.indexOf("if (uri.scheme === 'file' && linkTargetIsImage(uri.fsPath))");
  assert.ok(
    image !== -1 && image > directory && image < html,
    'a response link to a picture is opened as text, which reports the file as missing',
  );
  sourceMatch(
    opener.slice(image, html),
    /executeCommand\('vscode\.open', uri, \{ viewColumn: column \}\)/,
    'a picture is not handed to the editor viewer in the group the link asked for',
  );
  sourceMatch(
    opener,
    /executeCommand\(\s*'workbench\.action\.browser\.open',\s*uri\.toString\(true\)\s*\)/,
    'a local HTML file is not sent to the integrated browser',
  );

  const markdown = opener.indexOf("if (uri.scheme === 'file' && linkTargetIsMarkdown(uri.fsPath))");
  const htmlBranch = opener.slice(html, markdown);
  sourceMatch(
    htmlBranch,
    /Arc: VS Code did not open \$\{uri\.fsPath\} in the integrated browser\./,
    'a browser failure does not name the local file and browser action',
  );
  sourceDoesNotMatch(htmlBranch, /showTextDocument/, 'a browser failure falls back to raw HTML in the text editor');
  sourceMatch(htmlBranch, /\breturn;\s*\}\s*$/, 'the HTML branch falls through and opens the same file as raw text');
  assert.ok(markdown > html, 'a Markdown response link bypasses the directory, picture, or HTML routes');
  const markdownBranch = opener.slice(markdown, opener.indexOf('const selection', markdown));
  sourceMatch(
    markdownBranch,
    /executeCommand\(\s*'vscode\.openWith',\s*uri,\s*'vscode\.markdown\.preview\.editor',\s*column\s*\)/,
    'a Markdown response link is not sent to Markdown Preview in its requested editor group',
  );
  sourceMatch(
    markdownBranch,
    /Arc: VS Code did not open \$\{uri\.fsPath\} in Markdown Preview\./,
    'a Markdown Preview failure does not name the local file and reader',
  );
  sourceDoesNotMatch(
    markdownBranch,
    /showTextDocument/,
    'a Markdown Preview failure falls back to raw Markdown in the text editor',
  );
  sourceMatch(
    markdownBranch,
    /\breturn;\s*\}\s*$/,
    'the Markdown Preview branch falls through and opens the same file as raw text',
  );
  sourceMatch(
    opener,
    /showTextDocument\(uri, \{ selection, preview: true, viewColumn: column \}\)/,
    'a non-Markdown response link no longer opens in its requested editor group',
  );
});

test('a picture in a response reaches the reader, and the file it names opens on a press', () => {
  // Check workspace resource roots and image-action wiring.
  const rootsAt = panelHostSource.indexOf('private allowThemeFiles(webview: vscode.Webview)');
  const roots = memberFrom(panelHostSource, rootsAt);
  assert.ok(roots.length > 60, 'allowThemeFiles has gone, so this guard cannot see the resource roots');
  sourceMatch(
    roots,
    /workspaceFolders \?\? \[\]\)\.map\(\(f\) => f\.uri\)/,
    'the webview may not read the open folders, so every picture a response names draws nothing',
  );

  // Resolve image URIs for the receiving webview.
  sourceMatch(
    panelHostSource,
    /webview\.asWebviewUri\(vscode\.Uri\.file\(file\)\)\.toString\(\)/,
    'a picture is addressed to no webview, so only the host that built it can load one',
  );
  sourceMatch(
    panelHostSource,
    /const resolveImage = this\.imagesFor\(webview\);/,
    'cards are sent without a per-host picture address',
  );
  sourceMatch(
    panelHostSource,
    /if \(!inSummary && !inAnswers && !inSaid\) \{ return card; \}/,
    'every card is rendered again for every host, so an idle poll pays a parse per card',
  );
  // Re-render image references in mid-turn messages for each receiving host.
  sourceMatch(
    panelHostSource,
    /saidMessages: card\.saidMessages\.map\(\(said\) => \(\{/,
    'a mid-turn message is posted without rendered html, so the section draws nothing',
  );
  sourceMatch(
    panelHostSource,
    /const inSaid = card\.saidMessages\.some\(\(said\) => hasImageReference\(said\.text\)\);/,
    'a picture named in a mid-turn message draws as literal text',
  );

  // Run picturedFor with production Markdown and image-reference helpers.
  const pictured = (card: Record<string, unknown>) => {
    const marker = 'private picturedFor(card: RenderCard, resolveImage: ImageResolver): RenderCard {';
    const from = panelHostSource.indexOf(marker);
    assert.notEqual(from, -1, 'panelhost.ts no longer has a picturedFor, so this guard cannot run it');
    const rest = memberFrom(panelHostSource, from).slice(marker.length);
    const end = rest.lastIndexOf('}');
    assert.notEqual(end, -1, 'picturedFor has no closing brace');
    return new Function(
      'card',
      'resolveImage',
      'hasImageReference',
      'renderRichMarkdown',
      esbuild.transformSync(rest.slice(0, end), { loader: 'ts' }).code,
    )(
      card,
      (target: string) => ({ src: `vscode-webview://host/${target}`, path: `C:/work/${target}` }),
      hasImageReference,
      renderRichMarkdown,
    ) as Record<string, unknown>;
  };
  const drawn = pictured({
    kind: 'turn',
    summary: 'the response names no picture',
    summaryHtml: '<p>the response names no picture</p>',
    earlierAnswers: [],
    saidMessages: [
      {
        kind: 'commentary',
        at: 1,
        text: 'Here is how it looks: ![a shot](shot.png)',
        summaryHtml: '<p>rendered once with no host, which is the parse thrown away here</p>',
      },
    ],
  });
  const message = (drawn.saidMessages as Array<{ summaryHtml: string }>)[0].summaryHtml;
  assert.match(
    message,
    /<img src="vscode-webview:\/\/host\/shot\.png"/,
    'a picture named while the turn ran is addressed to no host, so the section draws a broken box',
  );
  assert.match(
    message,
    /data-image="C:\/work\/shot\.png"/,
    'the picture in a mid-turn message opens nothing when the reader presses it',
  );
  // picturedFor returns cards without image references unchanged.
  const plain = {
    kind: 'turn',
    summary: 's',
    summaryHtml: '<p>s</p>',
    earlierAnswers: [],
    saidMessages: [{ kind: 'commentary', at: 1, text: 'no picture', summaryHtml: '<p>no picture</p>' }],
  };
  assert.equal(pictured(plain), plain, 'a card naming no picture is rebuilt for every host');

  sourceMatch(
    hostHandler('openImage'),
    /await openImage\(msg\.path,/,
    'the extension host does not receive the picture press',
  );

  const opener = panelHostSource.slice(
    panelHostSource.indexOf('async function openImage('),
    panelHostSource.indexOf('// A visualization reference is local HTML'),
  );
  assert.ok(opener.length > 60, 'openImage has gone, so this guard cannot see how a picture opens');
  sourceMatch(
    opener,
    /imagePathFor\(target, folders\)/,
    'the host opens whatever path the webview sent, without asking whether it is in the workspace',
  );
  sourceMatch(
    opener,
    /'vscode\.open', vscode\.Uri\.file\(file\)/,
    'the picture does not open in the editor, so the panel needs a viewer of its own',
  );

  // Bound image height on the summary image selector.
  assert.match(
    styleRulesNaming('.summary img'),
    /max-height:/,
    'a picture in a response is drawn at its own height, so one screenshot fills the panel',
  );
});

