// Draft IDs use DRAFT_SESSION_PREFIX so the label sweep recognizes them.
test('every provisional session id is built from the prefix the sweep matches on', () => {
  const template = '`${DRAFT_SESSION_PREFIX}${crypto.randomUUID()}`';
  const built: string[] = [];
  for (const call of panelHostSource.matchAll(/this\.createDraft\(\s*([^,\n]+),/g)) {
    const arg = call[1].trim();
    if (!/^\w+$/.test(arg)) {
      built.push(arg);
      continue;
    }
    // Resolve identifier arguments through their most recent preceding const declaration.
    const declared = [...panelHostSource.slice(0, call.index).matchAll(new RegExp(`const ${arg} = (.+);`, 'g'))].pop();
    built.push(declared ? declared[1] : arg);
  }
  assert.ok(built.length > 0, 'panelhost.ts starts no session of its own, so nothing here is measured');
  assert.deepEqual(
    [...new Set(built)],
    [template],
    'a draft session is filed under an id the sweep cannot recognize, so its labels outlive the window',
  );
});

test('the rail card and the session heading both offer the read state the session is not in, and none of it in the palette', () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const titles = new Map<string, string>(
    manifest.contributes.commands.map((c: { command: string; title: string }) => [c.command, c.title]),
  );
  // Session read commands share their menu labels.
  // Categories distinguish session commands from turn commands in Keyboard Shortcuts.
  assert.equal(titles.get('arc.markSessionRead'), 'Mark as read');
  assert.equal(titles.get('arc.markSessionUnread'), 'Mark as unread');
  const categories = new Map<string, string | undefined>(
    manifest.contributes.commands.map((c: { command: string; category?: string }) => [c.command, c.category]),
  );
  for (const command of [
    'arc.markSessionRead',
    'arc.markSessionUnread',
    'arc.markTurnRead',
    'arc.markTurnUnread',
    'arc.pinSession',
    'arc.unpinSession',
    'arc.archiveSession',
    'arc.unarchiveSession',
    'arc.renameSession',
    'arc.labelSession',
    'arc.showSessionDetails',
  ]) {
    const expected = command.includes('Turn') ? 'Arc Turn' : 'Arc Session';
    assert.equal(
      categories.get(command),
      expected,
      `${command} carries no category consistent with the rest of its own menu`,
    );
  }
  for (const [session, turn] of [
    ['arc.markSessionRead', 'arc.markTurnRead'],
    ['arc.markSessionUnread', 'arc.markTurnUnread'],
  ]) {
    assert.notEqual(
      `${categories.get(session)} ${titles.get(session)}`,
      `${categories.get(turn)} ${titles.get(turn)}`,
      `${session} and ${turn} share a title and a category, so the Keyboard Shortcuts editor cannot tell them apart`,
    );
  }

  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const whenOf = (command: string) => menu.filter((m) => m.command === command).map((m) => m.when);
  // Session-list sections identify read state.
  // Heading sections identify archived state and carry read state separately.
  const S = RAIL_MENU_SECTIONS;
  const H = SESSION_MENU_SECTIONS;
  const onHeading = (suffix: string) =>
    `(webviewSection == '${H.live}' || webviewSection == '${H.archived}') && ${suffix}`;
  assert.deepEqual(
    whenOf('arc.markSessionRead'),
    [onHeading("sessionRead == 'unread'"), `webviewSection == '${S.unread}'`],
    'the mark is not offered on exactly the sessions with something new',
  );
  assert.deepEqual(
    whenOf('arc.markSessionUnread'),
    [onHeading("sessionRead == 'read'"), `webviewSection == '${S.read}'`],
    'the way back is not offered on exactly the sessions with nothing new',
  );
  // Menu conditions compare explicit read-state strings rather than booleans.
  assert.doesNotMatch(
    whenOf('arc.markSessionRead').join(''),
    /=== false|== false/,
    'the mark reads a boolean the absent case answers the same way as the direction it is not',
  );
  assert.doesNotMatch(
    whenOf('arc.markSessionUnread').join(''),
    /=== true|== true/,
    'the way back reads a boolean the absent case can be mistaken for',
  );

  // Session read actions stay outside the command palette.
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  for (const command of ['arc.markSessionRead', 'arc.markSessionUnread']) {
    assert.ok(
      palette.some((m) => m.command === command && m.when === 'false'),
      `${command} is in the command palette, where it has no session to act on`,
    );
  }

  // Check native command registration and browser message handling.
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  sourceMatch(
    extensionSource,
    /reg\('arc\.markSessionRead', \(arg\) => setSessionRead\(panel, arg, true\)\);/,
    'the session mark is registered on something other than the read hand-off',
  );
  sourceMatch(
    extensionSource,
    /reg\('arc\.markSessionUnread', \(arg\) => setSessionRead\(panel, arg, false\)\);/,
    'the session way back is registered on something other than the read hand-off',
  );
  // Ignore command arguments without a valid session identity.
  sourceMatch(
    extensionSource,
    /const session = sessionIdFrom\(arg\);\s*if \(!session\) \{\s*return;\s*\}/,
    'the session commands send a message for an argument that names no session',
  );
  sourceMatch(
    panelHostSource,
    /void this\.post\(\{ type: 'setSessionRead', session: this\.panelSession\(session\), read \}\);/,
    'the session commands reach no host, or they reach only one of the two',
  );
  sourceMatch(
    panelHandler('setSessionRead'),
    /readState\.setSession\(msg\.session, msg\.read\);/,
    'the message never reaches the two presses, so the menu entries do nothing',
  );
  // Update the heading's native-menu read state when session read state changes.
  const panelSource = fs.readFileSync(path.join(__dirname, 'webview', 'panel.ts'), 'utf8');
  sourceMatch(
    panelSource,
    /sessionState\.context\(session, persisted, \{\s*sessionRead: sessionReadState\(session\),/,
    'the heading row no longer carries the read state its own menu entries gate on',
  );
  sourceMatch(
    fs.readFileSync(path.join(__dirname, 'webview', 'timeline-renderer.ts'), 'utf8'),
    /options\.cardOptions\.read\.subscribe\(reconcile\)/,
    'a read change elsewhere in the session no longer refreshes the heading menu',
  );
});

test('the rail card and the session heading both offer archiving, and none of it in the palette', () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const titles = new Map<string, string>(
    manifest.contributes.commands.map((c: { command: string; title: string }) => [c.command, c.title]),
  );
  // Pin the native archive action labels.
  assert.equal(titles.get('arc.archiveSession'), 'Archive');
  assert.equal(titles.get('arc.unarchiveSession'), 'Unarchive');
  // Archive command categories identify the session in Keyboard Shortcuts.
  const categories = new Map<string, string | undefined>(
    manifest.contributes.commands.map((c: { command: string; category?: string }) => [c.command, c.category]),
  );
  assert.equal(categories.get('arc.archiveSession'), 'Arc Session');
  assert.equal(categories.get('arc.unarchiveSession'), 'Arc Session');

  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const whenOf = (command: string) => menu.filter((m) => m.command === command).map((m) => m.when);
  // Build archive conditions from shared section identifiers and the sessionArchived flag.
  const S = RAIL_MENU_SECTIONS;
  const H = SESSION_MENU_SECTIONS;
  const onRail = (suffix: string) =>
    `(webviewSection == '${S.unread}' || webviewSection == '${S.read}' || webviewSection == '${S.plain}') && ${suffix}`;
  assert.deepEqual(
    whenOf('arc.archiveSession'),
    [`webviewSection == '${H.live}'`, onRail('!sessionArchived')],
    'archiving is not offered on exactly the sessions that are not archived',
  );
  assert.deepEqual(
    whenOf('arc.unarchiveSession'),
    [`webviewSection == '${H.archived}'`, onRail('sessionArchived')],
    'the way back is not offered on exactly the sessions that are archived',
  );

  // Session archive actions stay outside the command palette.
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  for (const command of ['arc.archiveSession', 'arc.unarchiveSession']) {
    assert.ok(
      palette.some((m) => m.command === command && m.when === 'false'),
      `${command} is in the command palette, where it has no session to act on`,
    );
  }

  // Check native archive command registration and message handling.
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  sourceMatch(
    extensionSource,
    /reg\('arc\.archiveSession', \(arg\) => setSessionArchived\(panel, arg, true\)\);/,
    'archiving is registered on something other than the archive hand-off',
  );
  sourceMatch(
    extensionSource,
    /reg\('arc\.unarchiveSession', \(arg\) => setSessionArchived\(panel, arg, false\)\);/,
    'the way back is registered on something other than the archive hand-off',
  );
  sourceMatch(
    panelHostSource,
    /public setSessionArchived[\s\S]*this\.updateSessionMembership\(archived \? 'archive' : 'unarchive', session\)/,
    'the archive commands do not update and publish the provider-owned durable set',
  );
  sourceMatch(
    panelHandler('setSessionArchived'),
    /if \(msg\.archived\) sessionState\.hide\(msg\.session\);\s*else sessionState\.unarchive\(msg\.session\);/,
    'the message never reaches the two presses, so the menu entries do nothing',
  );
  // Refresh native-menu context on both session headings and session-list rows.
  const panelSource = fs.readFileSync(path.join(__dirname, 'webview', 'panel.ts'), 'utf8');
  sourceMatch(
    panelSource,
    /refreshContext: \(session\) => \{\s*timelineRenderer\?\.drawRowContext\(session\);\s*railRenderer\?\.drawRowContext\(session\);\s*\},/,
    'archiving or pinning refreshes only one of the two surfaces, so the other keeps offering the state the press just left',
  );
  const railSource = fs.readFileSync(path.join(__dirname, 'webview', 'rail.ts'), 'utf8');
  sourceMatch(
    railSource,
    /drawRowContext\(session\) \{/,
    'the rail no longer answers a context refresh, so a row can only redraw its menu by waiting for the next full rail message',
  );
});

