test('the Composer context command returns only to its menu host', () => {
  const from = panelHostSource.indexOf('public setComposerHidden(hidden: boolean): void {');
  assert.notEqual(from, -1, 'the provider no longer exposes the Composer visibility command');
  const rest = memberFrom(panelHostSource, from);
  const end = rest.lastIndexOf('}');
  assert.notEqual(end, -1, 'the Composer visibility command no longer has a readable body');
  const body = rest.slice(rest.indexOf('{') + 1, end);
  const setComposerHidden = new Function(`return function setComposerHidden(hidden) {${body}\n}`)() as (
    this: {
      composerMenuArm: { host: object; at: number } | null;
      hosts: object[];
      sendToHost: (host: object, message: unknown) => void;
    },
    hidden: boolean,
  ) => void;
  const firstPanel = {};
  const secondPanel = {};
  const sent: Array<{ host: object; message: unknown }> = [];
  const provider = {
    composerMenuArm: { host: firstPanel, at: Date.now() },
    hosts: [firstPanel, secondPanel],
    sendToHost(host: object, message: unknown) {
      sent.push({ host, message });
    },
  };

  setComposerHidden.call(provider, true);
  assert.deepEqual(
    sent,
    [{ host: firstPanel, message: { type: 'setComposerHidden', hidden: true } }],
    'the Composer command broadcasts to every panel instead of returning to its menu host',
  );

  provider.composerMenuArm = { host: firstPanel, at: Date.now() - 30_001 };
  setComposerHidden.call(provider, false);
  assert.equal(sent.length, 1, 'an expired Composer menu arm changes a panel after its native menu has closed');
});

test('session details returns only to the panel that opened its native menu', () => {
  const from = panelHostSource.indexOf('public showSessionDetails(session: string): void {');
  assert.notEqual(from, -1, 'the provider no longer exposes the native details command');
  const rest = memberFrom(panelHostSource, from);
  const end = rest.lastIndexOf('}');
  assert.notEqual(end, -1, 'the native details command no longer has a readable body');
  const body = rest.slice(rest.indexOf('{') + 1, end);
  const showSessionDetails = new Function(`return function showSessionDetails(session) {${body}\n}`)() as (
    this: {
      detailsMenuArm: { host: object; session: string; browserSession: string; at: number } | null;
      hosts: object[];
      sendToHost: (host: object, message: unknown) => void;
      post: (message: unknown) => void;
    },
    session: string,
  ) => void;
  const firstPanel = {};
  const secondPanel = {};
  const sent: Array<{ host: object; message: unknown }> = [];
  const provider = {
    detailsMenuArm: { host: firstPanel, session: 's1', browserSession: 's1', at: Date.now() },
    hosts: [firstPanel, secondPanel],
    sendToHost(host: object, message: unknown) {
      sent.push({ host, message });
    },
    post(message: unknown) {
      for (const host of this.hosts) {
        this.sendToHost(host, message);
      }
    },
    panelSession(session: string) {
      return session;
    },
  };

  showSessionDetails.call(provider, 's1');
  assert.deepEqual(
    sent,
    [{ host: firstPanel, message: { type: 'showSessionDetails', session: 's1' } }],
    'the command broadcasts the dialog to every panel instead of returning to its menu host',
  );

  provider.detailsMenuArm = {
    host: firstPanel,
    session: 's1',
    browserSession: 's1',
    at: Date.now() - 30_001,
  };
  showSessionDetails.call(provider, 's1');
  assert.equal(sent.length, 1, 'an expired native-menu arm opens a stale dialog instead of being discarded');
});

