test('retiring a default-selected child clears only that child effective permission', () => {
  const clear = new Function(
    `return function (agent, sessions) {\n${methodBody('public clearEffectiveModes(')}\n};`,
  )() as (this: Record<string, unknown>, agent: string, sessions: string[]) => void;
  const host = {
    codexEffectiveModes: { retired: { approvalPolicy: 'never' }, sibling: { approvalPolicy: 'on-request' } },
    claudeEffectiveModes: { retired: 'plan', sibling: 'auto' },
    usagePayload: () => ({}),
    post: () => undefined,
  };
  clear.call(host, 'codex', ['retired']);
  clear.call(host, 'claude', ['retired']);
  assert.deepEqual(host.codexEffectiveModes, { sibling: { approvalPolicy: 'on-request' } });
  assert.deepEqual(host.claudeEffectiveModes, { sibling: 'auto' });
});

