test('late browser attachment notices follow an adopted session', () => {
  const setAt = panelHostSource.indexOf('private setAttachmentNotice(');
  const setBody = panelHostSource.slice(setAt, panelHostSource.indexOf('private clearAttachmentNotice', setAt));
  sourceMatch(
    setBody,
    /this\.attachmentTarget\(session\) \?\? session/,
    'attachment notices do not resolve a provisional session through its alias',
  );
  const attachmentTarget = new Function(
    `return function (session) {\n${methodBody('private attachmentTarget(')}\n};`,
  )();
  const calls: string[] = [];
  const provider = {
    panelSession() {
      return 'durable';
    },
    stateFor(session: string) {
      calls.push(session);
      return { sessionId: session };
    },
  };
  assert.equal(attachmentTarget.call(provider, 'provisional'), 'durable');
  assert.deepEqual(
    calls,
    ['durable'],
    'attachment targeting accepts a stale provisional row before resolving its durable alias',
  );
  sourceMatch(
    hostHandler('fileReadError'),
    /setAttachmentNotice\(msg\.session/,
    'a late browser read failure writes its notice under the expired provisional session',
  );
  sourceMatch(
    hostHandler('fileRejected'),
    /setAttachmentNotice\(msg\.session/,
    'a late browser-side refusal writes its notice under the expired provisional session',
  );
  sourceMatch(
    hostHandler('attachFiles'),
    /!Array\.isArray\(msg\.files\)[\s\S]*setAttachmentNotice\(msg\.session/,
    'a malformed late attachment message bypasses adopted notice routing',
  );
  const adoptAt = panelHostSource.indexOf('private adoptDraft(');
  const adoptBody = panelHostSource.slice(adoptAt, panelHostSource.indexOf('public setCommands(', adoptAt));
  sourceMatch(
    adoptBody,
    /attachmentNotices\[provisional\][\s\S]*delete this\.attachmentNotices\[provisional\][\s\S]*attachmentNotices\[actual\] = notice/,
    'adoption leaves an already visible attachment notice behind on the provisional session',
  );
  const noticeAt = adoptBody.indexOf('const notice = this.attachmentNotices[provisional];');
  const migration = adoptBody.slice(noticeAt, adoptBody.indexOf('if (this.staging.delete(provisional))', noticeAt));
  sourceDoesNotMatch(
    migration,
    /setAttachmentNotice|this\.post\(/,
    'notice migration publishes an intermediate composer state before adoption has complete rows',
  );
});

