test('Codex new keeps late source comments through persistence, successor refusal, and Edit', () => {
  const source = 'source';
  const successor = 'successor';
  const resetId = 'reset';
  const asset = {
    id: '12345678-1234-4123-8123-123456789abc',
    name: 'diagram.png',
    mime: 'image/png',
    size: 4,
    digest: '0'.repeat(64),
  };
  const comments = [
    {
      id: 'comment-1',
      sessionId: source,
      turnKey: 'source:1',
      part: 'summary' as const,
      quote: '',
      note: 'first source comment',
      headline: 'Source turn',
      sessionTitle: 'Source',
      turnAt: 1,
      at: 2,
    },
    {
      id: 'comment-late',
      sessionId: source,
      turnKey: 'source:2',
      part: 'summary' as const,
      quote: '',
      note: 'late source comment',
      headline: 'Later turn',
      sessionTitle: 'Source',
      turnAt: 3,
      at: 4,
    },
  ];
  let queue = queueSubmissionAfter([], resetId, '/new review', ['comment-1'], [asset], 1, false, {
    agent: 'codex',
    owner: source,
  });
  queue = queueSubmissionAfter(queue, 'later', 'continue', [], [], 2, false, { agent: 'codex', owner: source });
  const sourceState = {
    ...COMPOSER_STATE,
    agent: 'codex' as const,
    sessionId: source,
    queued: queue,
    comments,
    draftCommentIds: [],
    assets: [],
  };
  const carried = commentsForQueuedSubmission(sourceState, queue[0], queue.slice(1));
  assert.deepEqual(
    carried.map((comment) => comment.id),
    ['comment-1', 'comment-late'],
  );
  queue = queueResetInFlight(
    queue,
    resetId,
    source,
    carried.map((comment) => comment.id),
  );
  assert.deepEqual(
    queue[0].commentIds,
    ['comment-1', 'comment-late'],
    'the late comment claim was not stored before the reset crossed the agent boundary',
  );
  queue = queueResetSucceeded(queue, resetId, source, successor);
  const restored = normalizePanelState({ queues: { [successor]: queue } }).queues[successor];
  assert.equal(restored[0].delivery.owner, successor);
  assert.equal(restored[1].delivery.owner, successor);
  const successorState = {
    ...sourceState,
    sessionId: successor,
    queued: restored,
  };
  const successorComments = commentsForQueuedSubmission(successorState, restored[0], restored.slice(1));
  const prompt = agentPromptToSend({
    ...successorState,
    queued: [],
    comments: successorComments,
    draft: '',
    draftCommentIds: [],
  }).text;
  assert.equal(prompt.match(/first source comment/g)?.length, 1);
  assert.equal(prompt.match(/late source comment/g)?.length, 1);
  queue = queueSuccessorFailed(queueSuccessorDelivery(restored, resetId), resetId, 'refused');
  const recovered = normalizePanelState({ queues: { [successor]: queue } }).queues[successor];
  assert.equal(recovered[0].delivery.phase, 'successor-recovery');
  assert.deepEqual(recovered[0].assets, [asset]);
  const edited = queueEdit(recovered, resetId, null);
  assert.ok(edited);
  assert.equal(
    edited.queued.some(queueCanDrain),
    false,
    'Edit released a later successor prompt before the edited draft was accepted',
  );
  const resubmitted = agentPromptToSend({
    ...successorState,
    queued: edited.queued,
    draft: edited.submission.text,
    draftCommentIds: edited.submission.commentIds,
    comments,
  }).text;
  assert.equal(resubmitted.match(/first source comment/g)?.length, 1);
  assert.equal(resubmitted.match(/late source comment/g)?.length, 1);
  assert.equal(
    queueAfterAcceptedRecovery(
      queueWithout(edited.queued, resetId),
      edited.queued.find((entry) => entry.id === resetId),
    ).every(queueCanDrain),
    true,
    'accepting the edited draft did not release its later successor prompts',
  );

  const failed = queueResetFailed(
    queueResetInFlight(
      queueSubmissionAfter([], resetId, '/new review', ['comment-1'], [asset], 1, false, {
        agent: 'codex',
        owner: source,
      }),
      resetId,
      source,
      ['comment-1'],
    ),
    resetId,
    source,
    'reset refused',
  );
  assert.equal(
    failed.some(queueCanDrain),
    false,
    'a failed reset payload can still reach the ordinary source prompt path',
  );
  assert.equal(failed[0].text, '/new review');
});

function queueRecoveryProvider(comments: ReturnType<typeof applyComment> = []) {
  const writes: unknown[] = [];
  const provider = Object.create(PanelProvider.prototype) as Record<string, any>;
  Object.assign(provider, {
    queues: {},
    drafts: {},
    boxText: {},
    assets: {},
    draftCommentIds: {},
    sentPrompts: {},
    picks: {},
    draftProfiles: {},
    sessionOrigins: {},
    railOrder: [],
    showing: '',
    promptsBySession: new Map(),
    saved: normalizePanelState({ comments }),
    memento: {
      update(_key: string, value: unknown) {
        writes.push(structuredClone(value));
        return Promise.resolve();
      },
    },
    queueHandoffs: new Set<string>(),
    queuedEditReservations: new Set<string>(),
    queuedEditOffers: new Map(),
    draftRevisions: new Map(),
    typedRenames: new Map(),
    repositoryScopeReady: true,
    pendingQueueDrains: new Set<string>(),
    attachmentStorageDir: null,
    clearSettlements: new Map(),
    newDrafts: {},
    live: {},
    awaitingSessionRecords: {},
    readyHosts: new Set(),
    assetCompletions: {
      begin() {
        return 1;
      },
      finish() {
        return false;
      },
    },
    assetHandoffs: new Set<string>(),
    assetIdsInHandoff: new Set<string>(),
    completedAssetTurns: new Set<number>(),
    deferredAssetDeletes: {},
    livePressHosts: new Map(),
    staging: new Set<string>(),
    attachmentNotices: {},
    asks: [],
    sessionAliases: new Map(),
    clearRoutes: new Map(),
    post() {
      return Promise.resolve();
    },
    postRail() {},
    usagePayload() {
      return {};
    },
    cwdForSession() {
      return 'C:\\ws';
    },
    rememberDrafts() {},
    rememberStarted() {},
    refresh() {
      return Promise.resolve();
    },
    dropCarriedAssets() {},
    sessionRows: ['source', 'successor', 'next'].map((id) => ({ id, label: id, agentKey: 'codex' })),
    running: new Set(),
    runningSinceKeys: new Map(),
    newestBySession: new Map(),
    newestCompactionBySession: new Map(),
    liveActivity: {},
    models: {},
    commandLists: {},
    skillLists: {},
    mcpServers: {},
    askLevels: {},
  });
  return { provider, writes };
}

test.each(['queued edit', 'reset recovery'])(
  'PanelProvider refuses an overflowing %s without losing persisted prompts or active draft ownership',
  async (route) => {
    const editorWindow = vscode.window as unknown as Record<string, unknown>;
    const originalNotice = editorWindow.showInformationMessage;
    editorWindow.showInformationMessage = () => Promise.resolve();
    try {
      const source = 'source';
      const comment = {
        id: 'active-comment',
        sessionId: source,
        turnKey: 'source:1',
        part: 'summary' as const,
        quote: '',
        note: 'active draft comment',
        headline: 'Source turn',
        sessionTitle: 'Source',
        turnAt: 1,
        at: 2,
      };
      const asset = {
        id: '12345678-1234-4123-8123-123456789abc',
        name: 'diagram.png',
        mime: 'image/png',
        size: 4,
        digest: '9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08',
      };
      const { provider, writes } = queueRecoveryProvider([comment]);
      const sent = vi.fn<() => Promise<{ delivered: boolean; reason: string; session: string }>>(async () => ({
        delivered: true,
        reason: '',
        session: source,
      }));
      provider.onSendPrompt = sent;
      provider.running.add('codex:' + source);
      provider.assets[source] = [asset];
      provider.draftCommentIds[source] = [comment.id];
      const activeText = 'a'.repeat(route === 'queued edit' ? DRAFT_TEXT_LIMIT : 100_000);
      provider.drafts[source] = activeText;
      provider.boxText[source] = activeText;
      provider.queues[source] = queueSubmissionAfter(
        queueSubmissionAfter(
          queueSubmissionAfter([], 'short', 's'.repeat(10), [], [], 1, false, { agent: 'codex', owner: source }),
          'long',
          'l'.repeat(DRAFT_TEXT_LIMIT),
          ['queued-comment'],
          [asset],
          2,
          false,
          { agent: 'codex', owner: source },
        ),
        'tail',
        't'.repeat(200_000),
        [],
        [],
        3,
        false,
        { agent: 'codex', owner: source },
      ).map((entry) => ({ ...entry, recoveryId: `submission-${entry.id}` }));
      if (route === 'reset recovery') {
        provider.queues[source][0] = {
          ...provider.queues[source][0],
          text: '',
          delivery: { phase: 'draft-recovery', owner: source, source, resetId: 'short' },
        };
        for (const entry of provider.queues[source].slice(1)) entry.delivery.barrier = 'short';
      }
      await provider.writeDrafts();
      const originalQueue = structuredClone(provider.queues[source]);
      const originalSaved = structuredClone(provider.saved);
      const posted: unknown[] = [];
      provider.post = (message: unknown) => {
        posted.push(message);
        return Promise.resolve();
      };
      provider.sendToHost = (_host: unknown, message: unknown) => {
        posted.push(message);
        return Promise.resolve(true);
      };
      if (route === 'queued edit') {
        const host = {};
        provider.requestQueuedEdit('short', source, 4, host, 'browser-source');
        assert.equal(provider.queuedEditReservations.has('short'), true);
        provider.acceptQueuedEdit('short', source, 4, 5, true, host);
      } else {
        provider.sendPrompt(
          activeText,
          source,
          5,
          'browser-source',
          undefined,
          undefined,
          undefined,
          'edited-submission',
        );
      }
      // Persist while delivery is blocked, then read the saved state as a reload does.
      await provider.writeDrafts();
      const reloaded = normalizePanelState(writes.at(-1));
      assert.deepEqual(reloaded.queues?.[source], originalSaved.queues[source], 'reload lost an admitted submission');
      assert.deepEqual(provider.queues[source], originalQueue, 'the refused replacement changed an admitted prompt');
      assert.equal(provider.drafts[source], activeText);
      assert.equal(provider.boxText[source], activeText);
      assert.equal(reloaded.drafts?.[source], activeText);
      assert.deepEqual(provider.assets[source], [asset]);
      assert.deepEqual(reloaded.assets?.[source], [asset]);
      assert.deepEqual(provider.draftCommentIds[source], [comment.id]);
      assert.deepEqual(reloaded.draftCommentIds?.[source], [comment.id]);
      assert.deepEqual(reloaded.comments, originalSaved.comments);
      assert.deepEqual(posted.at(-1), {
        type: 'restoreDraft',
        session: 'browser-source',
        text: activeText,
        revision: 5,
      });
      assert.equal(sent.mock.calls.length, 0, 'a refused replacement reached the agent');
    } finally {
      editorWindow.showInformationMessage = originalNotice;
    }
  },
);

test('PanelProvider uses production successor movement and retries a refused successor payload once', async () => {
  const source = 'source';
  const successor = 'successor';
  const resetId = 'reset';
  const asset = {
    id: '12345678-1234-4123-8123-123456789abc',
    name: 'diagram.png',
    mime: 'image/png',
    size: 4,
    digest: '9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08',
  };
  const comments = [
    {
      id: 'comment-1',
      sessionId: source,
      turnKey: 'source:1',
      part: 'summary' as const,
      quote: '',
      note: 'first source comment',
      headline: 'Source turn',
      sessionTitle: 'Source',
      turnAt: 1,
      at: 2,
    },
    {
      id: 'comment-late',
      sessionId: source,
      turnKey: 'source:2',
      part: 'summary' as const,
      quote: '',
      note: 'late source comment',
      headline: 'Later turn',
      sessionTitle: 'Source',
      turnAt: 3,
      at: 4,
    },
  ];
  const { provider, writes } = queueRecoveryProvider(comments);
  assert.equal(
    provider.noteSessionMoved,
    PanelProvider.prototype.noteSessionMoved,
    'the recovery fixture replaced production successor routing',
  );
  provider.attachmentStorageDir = tempDir('queue-recovery-assets-');
  fs.writeFileSync(path.join(provider.attachmentStorageDir, asset.id), 'test');
  provider.queues[source] = queueSubmissionAfter(
    queueSubmissionAfter([], resetId, '/new review', ['comment-1'], [asset], 1, false, {
      agent: 'codex',
      owner: source,
    }),
    'later',
    'later prompt',
    [],
    [],
    2,
    false,
    { agent: 'codex', owner: source },
  );
  const dependent = { id: 'dependent', order: 1, source, revision: 1, text: 'later prompt' };
  provider.saved.submittedPrompts = [dependent];
  provider.queues[source] = provider.queues[source].map((entry: QueuedSubmission) =>
    entry.id === 'later' ? { ...entry, recoveryId: dependent.id } : entry,
  );
  const promptTargets: string[] = [];
  let acceptSuccessor = false;
  provider.onClear = async () => ({ delivered: true, reason: '', session: successor });
  provider.onSendPrompt = async (_agent: string, session: string, _cwd: string, prompt: any) => {
    promptTargets.push(session);
    if (prompt.text !== 'composer content' && prompt.text !== 'revised exact prompt') {
      assert.equal(prompt.text.match(/first source comment/g)?.length, 1);
      assert.equal(prompt.text.match(/late source comment/g)?.length, 1);
      assert.deepEqual(
        prompt.assets?.map((entry: any) => entry.name),
        ['diagram.png'],
      );
    }
    return acceptSuccessor
      ? { delivered: true, reason: '', session }
      : { delivered: false, reason: 'successor refused', session };
  };

  provider.flushQueue(source);
  await vi.waitFor(() => {
    assert.equal(
      provider.queues[successor]?.[0]?.delivery.phase,
      'successor-recovery',
      JSON.stringify(provider.queues),
    );
  });
  assert.deepEqual(promptTargets, [successor]);
  assert.equal(provider.saved.submittedPrompts[0].owner, successor);
  assert.notEqual(provider.saved.submittedPrompts[0].accepted, true);
  assert.equal(source in provider.queues, false);
  assert.equal(provider.awaitingSessionRecords[successor]?.sessionId, successor);
  assert.ok(writes.some((value: any) => value.queues?.[successor]?.[0]?.delivery.phase === 'successor-recovery'));

  provider.drafts[successor] = 'composer content';
  provider.boxText[successor] = 'composer content';
  const host = {};
  provider.queuedEditOffers.set(host, {
    id: resetId,
    session: successor,
    browserSession: successor,
    revision: 1,
  });
  provider.queuedEditReservations.add(resetId);
  provider.acceptQueuedEdit(resetId, successor, 1, 1, true, host);
  await vi.waitFor(() => {
    assert.deepEqual(promptTargets, [successor], 'Edit sent the swapped Composer content');
  });
  await vi.waitFor(() => {
    assert.equal(provider.queues[successor][0].delivery.phase, 'draft-recovery');
    assert.equal(provider.queues[successor][1].delivery.barrier, resetId);
  });

  acceptSuccessor = true;
  const retry = { id: 'edited-retry', order: 2, source: successor, revision: 2, text: 'revised exact prompt' };
  const retryHost = { webview: {} };
  provider.hosts = [retryHost];
  provider.hostSessions = new Map([[retryHost, successor]]);
  await provider.acceptSubmission(retry.text, successor, 2, successor, retryHost, retry);
  await provider.importPromptRecovery([retry]);
  await vi.waitFor(() =>
    assert.equal(provider.saved.submittedPrompts.find((entry: any) => entry.id === retry.id)?.accepted, true),
  );
  const recovered = provider.saved.submittedPrompts.find((entry: any) => entry.id === retry.id);
  assert.equal(recovered.owner, successor);
  assert.equal(recovered.source, successor);
  assert.equal(recovered.order, 2);
  await vi.waitFor(() => {
    assert.equal(promptTargets.length, 2);
  });
  assert.deepEqual(promptTargets, [successor, successor]);
  assert.equal(provider.queues[successor][0].text, 'composer content');
  assert.equal(provider.queues[successor][0].delivery.barrier, undefined);
});

test('PanelProvider keeps source recovery through a failed edited retry and repeated Edit', async () => {
  const source = 'source';
  const resetId = 'reset';
  const { provider } = queueRecoveryProvider();
  provider.queues[source] = queueSubmissionAfter(
    queueSubmissionAfter([], resetId, '/new review', [], [], 1, false, { agent: 'codex', owner: source }),
    'later',
    'later prompt',
    [],
    [],
    2,
    false,
    { agent: 'codex', owner: source },
  );
  provider.onClear = async () => {
    throw new Error('reset failed');
  };
  const sent: string[] = [];
  provider.onSendPrompt = async (_agent: string, _session: string, _cwd: string, prompt: any) => {
    sent.push(prompt.text);
    return { delivered: false, reason: 'retry failed', session: source };
  };

  provider.flushQueue(source);
  await vi.waitFor(() => {
    assert.equal(provider.queues[source][0].delivery.phase, 'source-recovery');
  });
  provider.drafts[source] = 'first swapped draft';
  provider.boxText[source] = 'first swapped draft';
  const firstHost = {};
  provider.queuedEditOffers.set(firstHost, { id: resetId, session: source, browserSession: source, revision: 1 });
  provider.queuedEditReservations.add(resetId);
  provider.acceptQueuedEdit(resetId, source, 1, 1, true, firstHost);
  provider.sendPrompt('edited retry', source, 2);
  await vi.waitFor(() => {
    assert.deepEqual(sent, ['edited retry']);
    assert.equal(provider.queues[source][0].delivery.phase, 'source-recovery');
  });

  provider.drafts[source] = 'second swapped draft';
  provider.boxText[source] = 'second swapped draft';
  const secondHost = {};
  provider.queuedEditOffers.set(secondHost, { id: resetId, session: source, browserSession: source, revision: 3 });
  provider.queuedEditReservations.add(resetId);
  provider.acceptQueuedEdit(resetId, source, 3, 3, true, secondHost);
  await vi.waitFor(() => {
    assert.equal(provider.queues[source][0].delivery.phase, 'draft-recovery');
  });
  assert.deepEqual(sent, ['edited retry'], 'repeated Edit sent the swapped Composer content');
  assert.equal(provider.queues[source][1].delivery.barrier, resetId);
  assert.equal(provider.queues[source][2].delivery.barrier, resetId);
});

