test('PanelProvider releases failed-new dependents after Edit sends an exact clear', async () => {
  const source = 'source';
  const successor = 'successor';
  const resetId = 'reset';
  const { provider } = queueRecoveryProvider();
  provider.queues[source] = queueSubmissionAfter(
    queueSubmissionAfter(
      queueSubmissionAfter([], resetId, '/new review', [], [], 1, false, { agent: 'codex', owner: source }),
      'later-1',
      'first later prompt',
      [],
      [],
      2,
      false,
      { agent: 'codex', owner: source },
    ),
    'later-2',
    'second later prompt',
    [],
    [],
    3,
    false,
    { agent: 'codex', owner: source },
  );
  const clears: string[] = [];
  const sends: Array<{ session: string; text: string }> = [];
  provider.onClear = async (_agent: string, session: string, _cwd: string, name: string) => {
    clears.push(`${session}:${name}`);
    return clears.length === 1
      ? { delivered: false, reason: 'new failed', session: source }
      : { delivered: true, reason: '', session: successor };
  };
  provider.onSendPrompt = async (_agent: string, session: string, _cwd: string, prompt: any) => {
    sends.push({ session, text: prompt.text });
    return { delivered: true, reason: '', session };
  };

  provider.flushQueue(source);
  await vi.waitFor(() => {
    assert.equal(provider.queues[source]?.[0]?.delivery.phase, 'source-recovery');
  });
  provider.drafts[source] = '';
  provider.boxText[source] = '';
  const host = {};
  provider.queuedEditOffers.set(host, {
    id: resetId,
    session: source,
    browserSession: source,
    revision: 1,
  });
  provider.queuedEditReservations.add(resetId);
  provider.acceptQueuedEdit(resetId, source, 1, 1, true, host);
  await vi.waitFor(() => {
    assert.equal(provider.queues[source]?.[0]?.delivery.phase, 'draft-recovery');
  });

  provider.sendPrompt('/clear', source, 2);
  await vi.waitFor(() => {
    assert.deepEqual(sends, [{ session: successor, text: 'first later prompt' }]);
  });
  assert.equal(provider.queues[successor].every(queueCanDrain), true, 'a dependent retained the edited reset barrier');
  provider.flushQueue(successor);
  await vi.waitFor(() => {
    assert.deepEqual(sends, [
      { session: successor, text: 'first later prompt' },
      { session: successor, text: 'second later prompt' },
    ]);
  });
  assert.deepEqual(clears, [`${source}:review`, `${source}:`]);
  assert.equal(source in provider.queues, false);
  assert.equal(successor in provider.queues, false);
  assert.equal(
    sends.some((entry) => entry.session === source),
    false,
    'a dependent prompt ran on the reset source',
  );
});

test('every Codex new invocation routes through the durable reset record', () => {
  const sendAt = panelHostSource.indexOf('private sendPrompt(');
  const sendBody = panelHostSource.slice(sendAt, panelHostSource.indexOf('private send(', sendAt));
  const flushAt = panelHostSource.indexOf('public flushQueue(');
  const flushBody = panelHostSource.slice(flushAt, panelHostSource.indexOf('private promptAssets(', flushAt));
  sourceMatch(
    sendBody,
    /request\?\.command === 'new'[\s\S]*queueSubmissionAfter\(/,
    'an idle Codex new can bypass the durable queue record',
  );
  sourceMatch(
    flushBody,
    /clearRequest\(state\.agent, text\)[\s\S]*queueResetInFlight\([\s\S]*this\.startClear\(ready, attempted, text\)/,
    'a queued Codex new can bypass the reset transition',
  );
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  sourceMatch(
    extensionSource,
    /panel\.onClear = async \(agent, session, cwd, name\)[\s\S]*live\.clear\(name\)/,
    'the successor name is dropped before the agent boundary',
  );
});

function clearSettlementMethods() {
  const compiled = esbuild.transformSync(
    `
export function finishClearSettlement(settlement: any) {\n${methodBody('private finishClearSettlement(')}\n}
export function cancelClearSettlement(session: string, reason: string) {\n${methodBody('private cancelClearSettlement(')}\n}
export function noteLocalAnswer(session: string, clearFailure: string | null = null, turnId?: number) {\n${methodBody('public noteLocalAnswer(')}\n}
export function startClear(state: any, queued: any = null, text: string = '/clear') {\n${methodBody('private startClear(')}\n}`,
    {
      loader: 'ts',
      format: 'cjs',
      target: 'esnext',
    },
  ).code;
  const module = {
    exports: {} as {
      finishClearSettlement: (this: Record<string, any>, settlement: Record<string, any>) => void;
      cancelClearSettlement: (this: Record<string, any>, session: string, reason: string) => void;
      noteLocalAnswer: (
        this: Record<string, any>,
        session: string,
        clearFailure?: string | null,
        turnId?: number,
      ) => void;
      startClear: (this: Record<string, any>, state: Record<string, any>, queued?: Record<string, any>) => void;
    },
  };
  new Function(
    'module',
    'exports',
    'queueWithout',
    'pressesAfterLocalAnswer',
    'clearRequest',
    'queueResetFailed',
    compiled,
  )(module, module.exports, queueWithout, pressesAfterLocalAnswer, clearRequest, queueResetFailed);
  return module.exports;
}

function clearSettlementHost(methods: ReturnType<typeof clearSettlementMethods>) {
  const resolutions = new Map<string, (delivery: Record<string, unknown>) => void>();
  const host: Record<string, any> = {
    clearSettlements: new Map<string, Record<string, any>>(),
    queueHandoffs: new Set<string>(),
    queues: {},
    delivered: [],
    flushed: [],
    liveCards: [],
    cwdForSession() {
      return 'C:\\ws';
    },
    usagePayload() {
      return {};
    },
    post() {
      return Promise.resolve();
    },
    writeDrafts() {
      return Promise.resolve();
    },
    stateFor(session: string) {
      return {
        agent: 'codex',
        sessionId: session,
        running: false,
        clearing: this.clearSettlements.has(session),
        queued: this.queues[session] ?? [],
        comments: [],
      };
    },
    noteLive(state: Record<string, unknown>) {
      this.liveCards.push(state.sessionId);
      return this.liveCards.length;
    },
    livePressAnswered(_session: string, _pressed: number, delivery: Record<string, unknown>) {
      this.failure = delivery;
    },
    flushQueue(session: string) {
      this.flushed.push(session);
    },
    finishClearSettlement(settlement: Record<string, any>) {
      methods.finishClearSettlement.call(this, settlement);
    },
    cancelClearSettlement(session: string, reason: string) {
      methods.cancelClearSettlement.call(this, session, reason);
    },
    noteLocalAnswer(session: string, clearFailure: string | null = null) {
      methods.noteLocalAnswer.call(this, session, clearFailure);
    },
    notices: [] as Array<[string, string]>,
    setAttachmentNotice(session: string, notice: string) {
      this.notices.push([session, notice]);
    },
    live: {},
    refresh() {
      return Promise.resolve();
    },
    noteSessionMoved(source: string, successor: string) {
      const settlement = this.clearSettlements.get(source);
      if (settlement) {
        this.clearSettlements.delete(source);
        settlement.session = successor;
        this.clearSettlements.set(successor, settlement);
      }
      if (this.queues[source]) {
        this.queues[successor] = this.queues[source];
        delete this.queues[source];
      }
      if (settlement?.delivery?.delivered) {
        this.finishClearSettlement(settlement);
      }
    },
    onClear(agent: string) {
      return new Promise((resolve) => {
        resolutions.set(agent, resolve);
      });
    },
  };
  return { host, resolutions };
}

test('a successful clear settles both agent event orders without a timeline card', async () => {
  const methods = clearSettlementMethods();
  let liveCards = 0;
  const { host, resolutions } = clearSettlementHost(methods);
  const originalNoteLive = host.noteLive;
  host.noteLive = function (state: Record<string, unknown>) {
    liveCards += 1;
    return originalNoteLive.call(this, state);
  };

  methods.startClear.call(host, { agent: 'claude', sessionId: 'claude-source' });
  await vi.waitFor(() => {
    assert.ok(resolutions.has('claude'));
  });
  resolutions.get('claude')!({ delivered: true, reason: '', session: 'claude-source' });
  await vi.waitFor(() => {
    assert.equal(
      host.clearSettlements.get('claude-source')?.delivery?.delivered,
      true,
      'Claude acceptance ended the transition before its successor arrived',
    );
  });
  host.noteSessionMoved('claude-source', 'claude-successor');

  methods.startClear.call(host, { agent: 'codex', sessionId: 'codex-source' });
  await vi.waitFor(() => {
    assert.ok(resolutions.has('codex'));
  });
  host.noteSessionMoved('codex-source', 'codex-successor');
  resolutions.get('codex')!({ delivered: true, reason: '', session: 'codex-successor' });
  await vi.waitFor(() => {
    assert.equal(host.clearSettlements.size, 0, 'a settled clear kept blocking its successor');
    assert.deepEqual(
      host.flushed,
      ['claude-successor', 'codex-successor'],
      'a provider event order skipped or repeated successor queue settlement',
    );
    assert.equal(liveCards, 0, 'the submitted clear command appeared before its successor opened');
  });
});

