test('a card is taken down by the tested rule, and matched on the session', () => {
  // Use livePressOver to reconcile live presses with accepted recorded work.
  const at = panelHostSource.indexOf('private dropSpentPresses()');
  assert.notEqual(at, -1, 'nothing takes a live card down, so every press leaves one behind');
  const body = memberFrom(panelHostSource, at);
  sourceMatch(
    body,
    /livePressOver\(press, seen, running, now, acceptedRecordedTurn\)/,
    'the panel decides when a card is over, which is a rule no test can reach',
  );
  // Compaction presses match compaction records, while prompt presses match turn records.
  sourceMatch(
    body,
    /this\.newestCompactionBySession\.get\(session\)/,
    'a compaction card waits for a turn, so it is drawn until the ceiling takes it',
  );
  sourceMatch(
    body,
    /this\.newestBySession\.get\(session\)\?\.startedAt/,
    'a prompt card waits for something other than the turn the prompt made',
  );
  // Read running state for the press's session and agent.
  sourceMatch(
    body,
    /sessionRunning\(keys, press\.agent, session\)/,
    'the card reads whether the agent is busy rather than whether this session is',
  );
  sourceMatch(
    body,
    /acceptedRecordedTurn = selectedWindowContainsRecordedTurn\(/,
    'a live prompt can leave without its recorded turn in the accepted selected window',
  );

  // Reconcile live presses after collection and running-state updates.
  const refresh = memberFrom(panelHostSource, panelHostSource.indexOf('async refresh('));
  sourceMatch(
    refresh,
    /this\.cards = this\.collect\(sessions\.filter\([\s\S]*?this\.dropSpentPresses\(\);/,
    'the parse reads the real turn and the card stays up until something else happens',
  );
  const running = memberFrom(panelHostSource, panelHostSource.indexOf('public setRunning('));
  sourceMatch(running, /this\.dropSpentPresses\(\);/, 'a turn ending leaves its card standing');
});

type LiveProvider = PanelProviderType & {
  [key: string]: unknown;
};

test('context host demand refreshes completed and pending aggregates without losing concurrent ownership', async () => {
  const fixture = liveProviderFixture(livePress());
  const provider = fixture.provider as unknown as Record<string, any>;
  const session = provider.showing;
  const state = provider.stateFor(session);
  state.context = { used: 100, max: 200 };
  provider.stateFor = (id: string) => (id === session ? state : null);
  provider.contextDemands = new WeakMap();
  provider.contextRequests = new WeakMap();
  let reads = 0;
  let release!: (raw: unknown) => void;
  const native = (tokens: number) => ({
    totalTokens: tokens,
    rawMaxTokens: 200,
    model: 'native',
    categories: [{ name: 'Messages', kind: 'used', tokens }],
  });
  provider.contextSource = () => ({
    id: 'child',
    current: () => true,
    read: () => {
      reads++;
      return new Promise((resolve) => {
        release = resolve;
      });
    },
  });
  const request = (id: number) => provider.requestContext(fixture.host, session, id, 0);
  const first = request(1);
  const concurrent = request(2);
  await Promise.resolve();
  assert.equal(reads, 1);
  release(native(100));
  await Promise.all([first, concurrent]);
  assert.equal(fixture.posted.length, 1);
  assert.equal((fixture.posted[0].detail as any).request, 2);
  await request(3);
  assert.equal(reads, 1);
  state.context = { used: 110, max: 200 };
  const refreshed = request(4);
  await Promise.resolve();
  assert.equal(reads, 2);
  release(native(110));
  await refreshed;
  assert.equal((fixture.posted.at(-1)!.detail as any).used, 110);
  state.context = { used: 120, max: 200 };
  const stale = request(5);
  await Promise.resolve();
  state.context = { used: 130, max: 200 };
  release(native(120));
  await stale;
  const reopened = request(6);
  await Promise.resolve();
  assert.equal(reads, 4);
  release(native(130));
  await reopened;
  assert.equal((fixture.posted.at(-1)!.detail as any).used, 130);
});

test('Codex context invalidation cancels every pending read across demand keys and panel lifetimes', async () => {
  for (const completed of [0, 2]) {
    const fixture = liveProviderFixture(livePress());
    const provider = fixture.provider as unknown as Record<string, any>;
    const session = provider.showing;
    const file = path.join(tempDir('context-cancellation-'), 'rollout.jsonl');
    fs.writeFileSync(file, '{}\n');
    const stat = revisionOf(fs.statSync(file, { bigint: true }));
    const state = provider.stateFor(session);
    state.agent = 'codex';
    state.context = { used: 100, max: 200 };
    provider.stateFor = (id: string) => (id === session ? state : null);
    provider.catalog = {
      folders: '',
      sessions: [{ agent: 'codex', sessionId: session, file, size: stat.size, mtimeMs: stat.mtimeMs }],
    };
    provider.contextDemands = new WeakMap();
    provider.contextRequests = new WeakMap();
    const reads: Array<{ signal: AbortSignal; resolve: (value: null) => void }> = [];
    provider.progressiveWorker = {
      run: (_request: unknown, _generation: number, signal: AbortSignal) =>
        new Promise<null>((resolve) => {
          reads.push({ signal, resolve });
          signal.addEventListener('abort', () => resolve(null), { once: true });
        }),
    };
    provider.contextSource = (_agent: string, id: string) => provider.codexContextSource(id);
    const requests = [provider.requestContext(fixture.host, session, 1, 0)];
    await Promise.resolve();
    state.context = { used: 110, max: 200 };
    requests.push(provider.requestContext(fixture.host, session, 2, 0));
    await Promise.resolve();
    const reopened = { webview: {}, visible: () => true };
    provider.hostSessions.set(reopened, session);
    requests.push(provider.requestContext(reopened, session, 3, 0));
    await Promise.resolve();
    assert.equal(reads.length, 3);
    reads[completed].resolve(null);
    await requests[completed];
    provider.invalidateContext(session);
    try {
      assert.deepEqual(
        reads.map((read) => read.signal.aborted),
        reads.map((_, index) => index !== completed),
      );
    } finally {
      for (const read of reads) read.resolve(null);
      await Promise.all(requests);
    }
    assert.equal(provider.contextReadControllers.size, 0);
  }
});

test('Codex host preserves active reasons and restores categories after a measured source revision', async () => {
  const fixture = liveProviderFixture(livePress());
  const provider = fixture.provider as unknown as Record<string, any>;
  const session = provider.showing;
  const records = codexContextRecords(session);
  const previous = structuredClone(records.at(-1)!);
  const file = path.join(tempDir('active-context-host-'), 'rollout.jsonl');
  const state = provider.stateFor(session);
  state.agent = 'codex';
  state.settings.selectedModel = 'gpt-6.1-sol';
  state.context = { used: 10_000, max: 20_000 };
  provider.stateFor = (id: string) => (id === session ? state : null);
  provider.catalog = { sessions: [{ agent: 'codex', sessionId: session, file }] };
  provider.contextDemands = new WeakMap();
  provider.contextRequests = new WeakMap();
  let replaceDuringRead = false;
  provider.progressiveWorker = {
    run: async (request: any, generation: number, signal: AbortSignal) => {
      const estimate = await readCodexContext(file, session, revisionOf(fs.statSync(file, { bigint: true })), signal);
      if (replaceDuringRead) fs.appendFileSync(file, JSON.stringify(previous) + '\n');
      return { generation, value: { kind: 'codex-context', estimate } };
    },
  };
  provider.contextSource = (_agent: string, id: string) => provider.codexContextSource(id);
  const request = async (id: number) => {
    fs.writeFileSync(file, records.map((row) => JSON.stringify(row)).join('\n') + '\n');
    await provider.requestContext(fixture.host, session, id, provider.contextGenerations?.get(session) ?? 0);
    return fixture.posted.at(-1)!.detail as any;
  };
  assert.equal((await request(1)).status, 'available');
  records.push({
    type: 'response_item',
    payload: { type: 'function_call', call_id: 'pending', name: 'read', arguments: '{}' },
  });
  assert.equal((await request(2)).reason, 'pending-tools');
  assert.deepEqual(state.context, { used: 10_000, max: 20_000 });
  records.push({
    type: 'response_item',
    payload: { type: 'function_call_output', call_id: 'pending', output: 'result' },
  });
  records.push(previous);
  assert.equal((await request(3)).reason, 'awaiting-measurement');
  const next = structuredClone(previous);
  next.payload.info.last_token_usage.input_tokens += 50;
  records.push(next);
  state.context.used += 50;
  provider.invalidateContext(session);
  const restored = await request(4);
  assert.equal(restored.status, 'available');
  assert.equal(restored.generation, 1);
  assert.equal(restored.used, 10_150);
  assert.equal(restored.reason, undefined);
  replaceDuringRead = true;
  const posted = fixture.posted.length;
  await request(5);
  assert.equal(fixture.posted.length, posted, 'a changed source published obsolete categories');
});

test('context host rejects obsolete identity and malformed replies and settles disconnected demand', async () => {
  for (const change of ['model', 'selection', 'child', 'generation', 'malformed', 'disconnected']) {
    const fixture = liveProviderFixture(livePress());
    const provider = fixture.provider as unknown as Record<string, any>;
    const session = provider.showing;
    const state = provider.stateFor(session);
    state.context = { used: 100, max: 200 };
    state.settings.selectedModel = 'host';
    provider.stateFor = (id: string) => (id === session ? state : null);
    provider.contextDemands = new WeakMap();
    provider.contextRequests = new WeakMap();
    let owned = true;
    let reads = 0;
    let release!: (raw: unknown) => void;
    provider.contextSource =
      change === 'disconnected'
        ? () => null
        : () => ({
            id: 'child',
            current: () => owned,
            read: () => {
              reads++;
              return new Promise((resolve) => {
                release = resolve;
              });
            },
          });
    const pending = provider.requestContext(fixture.host, session, 1, 0);
    await Promise.resolve();
    if (change === 'model') state.settings.selectedModel = 'new-model';
    if (change === 'selection') provider.hostSessions.set(fixture.host, 'other');
    if (change === 'child') owned = false;
    if (change === 'generation') provider.invalidateContext(session);
    if (change !== 'disconnected')
      release({
        totalTokens: 100,
        rawMaxTokens: 200,
        model: 'native',
        categories: [{ name: 'Messages', kind: change === 'malformed' ? { toString: null } : 'used', tokens: 100 }],
      });
    await pending;
    if (change === 'malformed' || change === 'disconnected') {
      assert.equal((fixture.posted.at(-1)!.detail as any).status, 'unavailable');
      if (change === 'malformed') {
        const retry = provider.requestContext(fixture.host, session, 2, 0);
        await Promise.resolve();
        assert.equal(reads, 2);
        release({
          totalTokens: 100,
          rawMaxTokens: 200,
          model: 'native',
          categories: [{ name: 'Messages', kind: 'used', tokens: 100 }],
        });
        await retry;
        assert.equal((fixture.posted.at(-1)!.detail as any).status, 'available');
      }
    } else assert.equal(fixture.posted.length, 0, change);
  }
});

test('context lifecycle changes invalidate only their session through production prompt, compact, clear and selection paths', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  for (const operation of ['send', 'startCompaction', 'startClear', 'show']) {
    const fixture = liveProviderFixture(livePress());
    const provider = fixture.provider as unknown as Record<string, any>;
    const session = provider.showing;
    provider.contextSource = () => null;
    provider.clearSettlements = new Map();
    provider.onSendPrompt = provider.onCompact = provider.onClear = () => new Promise(() => {});
    provider.onSelectionChanged = () => {};
    provider.contextGenerations = new Map([
      [session, 3],
      ['other', 9],
    ]);
    const state = provider.stateFor(session);
    if (operation === 'show') provider.show('other', fixture.host);
    else provider[operation](state, operation === 'send' ? 'hello' : undefined);
    assert.equal(provider.contextGenerations.get(session), 4, operation);
    assert.equal(provider.contextGenerations.get('other'), 9, operation);
  }
  sourceMatch(
    extensionSource,
    /if \(affected\) panel\.invalidateContext\(affected\);/,
    'child events invalidate their own session',
  );
  sourceMatch(
    extensionSource,
    /if \(state\.sessionId\) panel\.invalidateContext\(state\.sessionId\);/,
    'retired children invalidate their own session',
  );
  sourceMatch(
    extensionSource,
    /const setModelFor[\s\S]*?panel\.invalidateContext\(session\);/,
    'model changes invalidate their own session',
  );
});

