      provider.noteResponseEnded(first.sessionId, { status }, 1);
      const projected = (fixture.posted.at(-1) as any).live[0];
      const state = status === 'ok' ? 'done' : status === 'error' ? 'failed' : 'interrupted';
      assert.equal(projected.state, state);
