      provider.livePressAnswered(first.sessionId, second.at, { delivered: true, reason: '', turnId: 2 });
      provider.noteReply(first.sessionId, 'Second response', 2);
      provider.noteResponseEnded(first.sessionId, { status: 'interrupted' });
