test('the unsent prompts reach storage and come back out of it', () => {
  // Restore drafts and submitted-prompt recovery from saved host state.
  const ctor = memberFrom(panelHostSource, panelHostSource.indexOf('constructor('));
  sourceMatch(
    ctor,
    /this\.drafts = \{ \.\.\.this\.saved\.drafts \};/,
    'a window opens with the stored prompts unread, so the box is empty and nothing can reach them',
  );
  sourceMatch(
    ctor,
    /this\.sentPrompts = restoredSentPrompts\(this\.saved\);/,
    'a window opens with no memory of a prompt an agent process never recorded, so a restart loses it',
  );
  sourceMatch(
    ctor,
    /this\.queues = normalizeQueuedSubmissions\(this\.saved\.queues\)/,
    'a window opens without the submissions Arc already accepted',
  );

  const draftsWriteAt = panelHostSource.indexOf('private writeDrafts(): Promise<void> {');
  const draftsWrite = memberFrom(panelHostSource, draftsWriteAt);
  sourceMatch(
    draftsWrite,
    /this\.saved\.sentPrompts = sentPromptsToSave\(this\.sentPrompts, this\.promptsBySession\);/,
    'a send never reaches storage, so a restart still loses the prompt an agent process never recorded',
  );

  const saveAt = panelHostSource.indexOf('private saveState(');
  const stateSave = memberFrom(panelHostSource, saveAt);
  sourceMatch(
    stateSave,
    /const queues = this\.saved\.queues[\s\S]*this\.saved = normalizePanelState\(state, railFilters\)[\s\S]*this\.saved\.queues = queues/,
    'saving a fold or filter erases the persisted local queue',
  );
  const forgetAt = panelHostSource.indexOf('public async forgetState()');
  const forget = memberFrom(panelHostSource, forgetAt);
  sourceMatch(
    forget,
    /this\.saved\.queues = normalizeQueuedSubmissions\(this\.queues\)/,
    'forgetting panel preferences also cancels locally accepted submissions',
  );
  sourceMatch(
    forget,
    /this\.saved\.comments = acceptedComments[\s\S]*const resetState = structuredClone\(this\.saved\)[\s\S]*const resetSaved = this\.saveState\(resetState\)[\s\S]*await resetSaved/,
    'a comments-only waiting submission disappears when panel preferences are forgotten',
  );

  // Typing, sending, and accepted queue edits use holdDraft.
  for (const [marker, what] of [
    ['private setDraft(', 'a keystroke'],
    ['private sendPrompt(', 'a prompt going out'],
    ['private acceptQueuedEdit(', 'a queued prompt coming back to the box'],
  ] as const) {
    sourceMatch(
      memberFrom(panelHostSource, panelHostSource.indexOf(marker)),
      /this\.holdDraft\(/,
      `${what} bypasses the one writer that persists prompts and updates the rail`,
    );
  }
  const heldAt = panelHostSource.indexOf('private holdDraft(session: string, text: string');
  assert.notEqual(heldAt, -1, 'draft changes have no common writer');
  const heldBody = memberFrom(panelHostSource, heldAt);
  sourceMatch(
    heldBody,
    /const moved = hasUnsentPrompt\(this\.drafts\[session\]\) !== hasUnsentPrompt\(text\);/,
    'the rail is refreshed on every letter or does not notice when meaningful input appears',
  );
  sourceMatch(
    heldBody,
    /if \(immediate\) \{ void this\.writeDrafts\(\); \} else \{ this\.rememberDrafts\(\); \}/,
    'the common draft writer no longer preserves immediate recovery and delayed typing writes',
  );
  sourceMatch(
    heldBody,
    /if \(moved\) \{ this\.postRail\(true\); \}/,
    'a prompt can appear or disappear without rewording its rail card',
  );
  sourceMatch(
    heldBody,
    /return moved;/,
    'the draft writer does not report the only transition that can change the composer controls',
  );
  const typedAt = panelHostSource.indexOf('private setDraft(text: string, keep: string, session: string)');
  const typedBody = memberFrom(panelHostSource, typedAt);
  sourceMatch(
    typedBody,
    /const railMoved = this\.holdDraft\(session, keep\);/,
    'every letter asks the host to rebuild and return the complete composer state',
  );
  // Visible recalled text can differ from the persisted draft.
  // Keep boxText synchronized with the visible text.
  sourceMatch(typedBody, /this\.boxText\[session\] = text;/, 'the send control no longer follows the words on screen');
  // Draft typing resolves the row without rebuilding complete prompt-box state.
  sourceDoesNotMatch(
    typedBody,
    /this\.stateFor\(/,
    'every letter typed merges and cleans every prompt the walk offers, to name a session',
  );
  // Write visible boxText after holdDraft to preserve recalled text.
  assert.ok(
    typedBody.indexOf('this.boxText[session] = text;') > typedBody.indexOf('this.holdDraft('),
    'the words to remember overwrite the words on screen, so the send control answers for neither',
  );
  sourceMatch(
    typedBody,
    /if \(shown \|\| railMoved\) \{/,
    'a recalled prompt in an empty box leaves the send control saying there is nothing to send',
  );

  // Flush pending draft persistence during provider disposal.
  const dispose = memberFrom(panelHostSource, panelHostSource.indexOf('private disposeOwned(): void {'));
  sourceMatch(
    dispose,
    /this\.writeDrafts\(\)/,
    'the pending write is dropped when the window closes, which is exactly when it matters',
  );

  // Preserve host-owned drafts across browser state normalization.
  const body = memberFrom(panelHostSource, panelHostSource.indexOf('private saveState('));
  const held = body.indexOf('const drafts = this.saved.drafts;');
  const rebuilt = body.indexOf('this.saved = normalizePanelState(state, railFilters);');
  const put = body.indexOf('this.saved.drafts = drafts;');
  assert.ok(
    held !== -1 && rebuilt !== -1 && put !== -1,
    'a save from one host wipes the prompt the reader is typing in the other',
  );
  assert.ok(
    held < rebuilt && rebuilt < put,
    'the drafts are read or put back on the wrong side of the rebuild, so an empty set is what survives',
  );

  // Preserve host-owned submitted-prompt recovery across browser state normalization.
  const sentHeld = body.indexOf('const sentPrompts = this.saved.sentPrompts;');
  const sentPut = body.indexOf('this.saved.sentPrompts = sentPrompts;');
  assert.ok(
    sentHeld !== -1 && sentPut !== -1,
    'a save from one host wipes the sent prompt no transcript has recorded yet in the other',
  );
  assert.ok(
    sentHeld < rebuilt && rebuilt < sentPut,
    'the sent prompts are read or put back on the wrong side of the rebuild, so an empty set is what survives',
  );
});

// Typed facade for the imported prompt-editing history helpers.

interface UndoParts {
  textEdit(before: string, after: string, caret: number): TextEdit;
  undoJoins(last: TextEdit | null, edit: TextEdit, gap: number): boolean;
  undoStart(text: string, start: number, end: number): UndoStack;
  undoRecord(stack: UndoStack, text: string, start: number, end: number, now: number): void;
  undoTake(stack: UndoStack, back: boolean): UndoStep | null;
  undoIntent: typeof undoIntent;
  UNDO_GAP: number;
  UNDO_DEPTH: number;
}

function undoParts(): UndoParts {
  return { textEdit, undoJoins, undoStart, undoRecord, undoTake, undoIntent, UNDO_GAP, UNDO_DEPTH };
}

// Append characters with controlled edit timestamps and return the final timestamp.
function typedInto(parts: UndoParts, stack: UndoStack, run: string, from: number, gap: number): number {
  let now = from;
  let text = stack.done[stack.done.length - 1].text;
  for (const ch of run) {
    text += ch;
    now += gap;
    parts.undoRecord(stack, text, text.length, text.length, now);
  }
  return now;
}

// Return retained undo text from oldest to newest.
function undoTexts(stack: UndoStack): string[] {
  return stack.done.map((step) => step.text);
}

test('an edit is read off the two texts, at the right place and the right size', () => {
  const { textEdit } = undoParts();
  // Supply the caret position reported after each edit.
  const cases: [string, string, number, string, number, string, string][] = [
    ['', 'h', 1, 'insert', 0, '', 'h'],
    ['hell', 'hello', 5, 'insert', 4, '', 'o'],
    ['abc', 'abdc', 3, 'insert', 2, '', 'd'],
    ['ab', 'a', 1, 'delete', 1, 'b', ''],
    ['hello', 'helo', 3, 'delete', 3, 'l', ''],
    ['hello', 'world', 5, 'other', 0, 'hello', 'world'],
    ['hi', 'hi', 2, 'other', 2, '', ''],
    ['run /co', 'run /compact ', 13, 'insert', 7, '', 'mpact '],
    // The caret distinguishes identical-character edits at opposite ends of a run.
    ['aaa', 'aaaa', 1, 'insert', 0, '', 'a'],
    ['aaa', 'aaaa', 4, 'insert', 3, '', 'a'],
    ['aaa', 'aa', 0, 'delete', 0, 'a', ''],
    ['aaa', 'aa', 2, 'delete', 2, 'a', ''],
  ];
  for (const [before, after, caret, kind, at, removed, added] of cases) {
    const edit = textEdit(before, after, caret);
    assert.equal(edit.kind, kind, `"${before}" to "${after}" is read as the wrong kind of change`);
    assert.equal(edit.at, at, `"${before}" to "${after}" with the caret at ${caret} starts in the wrong place`);
    assert.equal(edit.removed, removed, `"${before}" to "${after}" takes out the wrong text`);
    assert.equal(edit.added, added, `"${before}" to "${after}" puts in the wrong text`);
  }

  // An invalid caret falls back to the difference between the texts.
  assert.equal(textEdit('hell', 'hello', 99).at, 4, 'a caret that explains nothing is trusted anyway');

  // Single-character edits join typing runs.
  // Whitespace ends a run, while larger edits remain separate.
  assert.equal(textEdit('hell', 'hello', 5).solo, false, 'a single character typed is read as a paste');
  assert.equal(textEdit('hell', 'hello', 5).ends, false, 'a letter closes the word it is part of');
  assert.equal(textEdit('one', 'one ', 4).ends, true, 'a space leaves the word it ends open');
  assert.equal(textEdit('one', 'one\n', 4).ends, true, 'a newline leaves the line it ends open');
  assert.equal(textEdit('run /co', 'run /compact ', 13).solo, true, 'a command completed is read as one keystroke');

  // Count Unicode characters rather than UTF-16 units for edit grouping.
  // Nonbreaking spaces end a run.
  assert.equal(textEdit('a', 'a\u{1F600}', 3).solo, false, 'an emoji typed is read as a paste');
  assert.equal(textEdit('a', 'a\u{1F600}', 3).ends, false, 'an emoji closes the word it is part of');
  assert.equal(
    textEdit('one', 'one' + String.fromCharCode(160), 4).ends,
    true,
    'a no-break space leaves the word it ends open',
  );
});

test('a run of typing is one step, and undo walks back a word at a time', () => {
  const parts = undoParts();
  const stack = parts.undoStart('', 0, 0);
  typedInto(parts, stack, 'one two', 1000, 40);

  assert.deepEqual(
    undoTexts(stack),
    ['', 'one ', 'one two'],
    'a run of typing is filed as more or fewer steps than the words in it',
  );

  assert.equal(parts.undoTake(stack, true)?.text, 'one ', 'undo takes back something other than the last word');
  assert.equal(parts.undoTake(stack, true)?.text, '', 'a second undo does not reach what the box started from');
  assert.equal(parts.undoTake(stack, true), null, 'undo runs off the end of the steps rather than stopping');

  assert.equal(parts.undoTake(stack, false)?.text, 'one ', 'redo does not put back what undo took');
  assert.equal(parts.undoTake(stack, false)?.text, 'one two', 'redo stops short of where the reader was');
  assert.equal(parts.undoTake(stack, false), null, 'redo carries on past the last step it took');
});

test('a run ends at a pause, at a change of direction and at anything larger than a keystroke', () => {
  const parts = undoParts();

  // A pause beyond UNDO_GAP starts another step.
  const paused = parts.undoStart('', 0, 0);
  const at = typedInto(parts, paused, 'ab', 1000, 40);
  typedInto(parts, paused, 'c', at + parts.UNDO_GAP + 1, 0);
  assert.deepEqual(
    undoTexts(paused),
    ['', 'ab', 'abc'],
    'a pause longer than the gap does not end the run it interrupted',
  );

  // Deletion starts a separate run after insertion, while consecutive backspaces join.
  const wiped = parts.undoStart('', 0, 0);
  typedInto(parts, wiped, 'abc', 1000, 40);
  parts.undoRecord(wiped, 'ab', 2, 2, 1200);
  parts.undoRecord(wiped, 'a', 1, 1, 1240);
  assert.deepEqual(
    undoTexts(wiped),
    ['', 'abc', 'a'],
    'a backspace joins the typing before it, or a run of them is filed one step per press',
  );

  // A paste stays separate from typing before and after it.
  const pasted = parts.undoStart('', 0, 0);
  typedInto(parts, pasted, 'ab', 1000, 40);
  parts.undoRecord(pasted, 'abLONG', 6, 6, 1090);
  typedInto(parts, pasted, 'c', 1130, 40);
  assert.deepEqual(
    undoTexts(pasted),
    ['', 'ab', 'abLONG', 'abLONGc'],
    'a paste is swallowed by the typing around it, so one undo takes back more than the reader pasted',
  );
});

test('two edits at opposite ends of a run of one character do not join', () => {
  // Preserve separate undo steps for identical-character edits at opposite ends of a run.
  const parts = undoParts();
  const stack = parts.undoStart('aa', 2, 2);
  parts.undoRecord(stack, 'aaa', 3, 3, 1000);
  parts.undoRecord(stack, 'aaaa', 1, 1, 1040);
  assert.deepEqual(
    undoTexts(stack),
    ['aa', 'aaa', 'aaaa'],
    'the two ends of a run of one character are read as the same place, so a state is lost',
  );

  // Opposite-end deletions also retain separate steps.
  const cut = parts.undoStart('bbb', 3, 3);
  parts.undoRecord(cut, 'bb', 2, 2, 2000);
  parts.undoRecord(cut, 'b', 0, 0, 2040);
  assert.deepEqual(
    undoTexts(cut),
    ['bbb', 'bb', 'b'],
    'a character taken off each end of a run is read as one run of backspaces',
  );

  // Ordinary consecutive typing retains one undo step.
  const plain = parts.undoStart('', 0, 0);
  typedInto(parts, plain, 'word', 3000, 40);
  assert.deepEqual(undoTexts(plain), ['', 'word'], 'a plain run of typing is no longer one step');
});

test('a change ends what the reader had taken back, and the steps have a ceiling', () => {
  const parts = undoParts();
  const stack = parts.undoStart('', 0, 0);
  typedInto(parts, stack, 'one two', 1000, 40);
  parts.undoTake(stack, true);
  assert.equal(stack.undone.length, 1, 'undo keeps nothing to put back');

  // Typing after undo clears the redo branch.
  typedInto(parts, stack, 'x', 5000, 40);
  assert.equal(stack.undone.length, 0, 'redo still offers a step the new text was never made against');
  assert.equal(parts.undoTake(stack, false), null, 'redo puts back text the reader wrote over');

  // Caret movement without a text change adds no undo step.
  const still = parts.undoStart('hi', 2, 2);
  parts.undoRecord(still, 'hi', 0, 0, 9000);
  assert.equal(still.done.length, 1, 'a caret moving is filed as a step of its own');

  const deep = parts.undoStart('', 0, 0);
  for (let i = 1; i <= parts.UNDO_DEPTH + 5; i++) parts.undoRecord(deep, 'x'.repeat(i), i, i, i * 10000);
  assert.equal(parts.UNDO_DEPTH, 200, 'the fixed history depth changed');
  assert.equal(deep.done.length, parts.UNDO_DEPTH, 'the steps grow without a ceiling');
  assert.notEqual(deep.done[0].text, '', 'the oldest state is kept past the fixed ceiling');
  assert.equal(
    deep.done[deep.done.length - 1].text.length,
    parts.UNDO_DEPTH + 5,
    'the newest step is the one dropped, so undo goes forwards',
  );
});

test('undo and redo are read off the press the same way on both platforms', () => {
  const { undoIntent } = undoParts();
  const press = (over: Record<string, unknown>) => ({
    key: 'z',
    ctrlKey: false,
    metaKey: false,
    shiftKey: false,
    altKey: false,
    ...over,
  });

  assert.equal(undoIntent(press({ ctrlKey: true })), 'undo', 'Ctrl and Z is not undo');
  assert.equal(undoIntent(press({ metaKey: true })), 'undo', 'Cmd and Z is not undo, so a Mac has no undo');
  assert.equal(undoIntent(press({ ctrlKey: true, shiftKey: true })), 'redo', 'Ctrl, Shift and Z is not redo');
  assert.equal(undoIntent(press({ metaKey: true, shiftKey: true })), 'redo', 'Cmd, Shift and Z is not redo');
  assert.equal(undoIntent(press({ key: 'y', ctrlKey: true })), 'redo', 'Ctrl and Y is not redo');
  assert.equal(
    undoIntent(press({ key: 'Z', ctrlKey: true })),
    'undo',
    'the press is read off the letter as it arrives, so Caps Lock takes undo away',
  );

  assert.equal(undoIntent(press({})), '', 'a bare Z is taken as undo, so the letter cannot be typed');
  assert.equal(undoIntent(press({ ctrlKey: true, altKey: true })), '', 'a press with Alt held is taken as undo');
  assert.equal(
    undoIntent(press({ key: 'y', ctrlKey: true, shiftKey: true })),
    '',
    'Ctrl, Shift and Y is taken as redo',
  );
  assert.equal(undoIntent(press({ key: 'x', ctrlKey: true })), '', 'a press that is not Z or Y is answered');
  assert.equal(undoIntent(null), '', 'a listener handed nothing at all answers with a move');
});

// The page-level send chord follows platform conventions.

test('the send chord takes one modifier per platform and refuses the other one', () => {
  const press = (over: Record<string, unknown>) => ({
    key: 'Enter',
    ctrlKey: false,
    metaKey: false,
    shiftKey: false,
    altKey: false,
    ...over,
  });

  assert.equal(sendChordLabel('Win32'), 'Ctrl and Enter', 'Windows is not told about Ctrl and Enter');
  assert.equal(sendChordLabel('Linux x86_64'), 'Ctrl and Enter', 'Linux is not told about Ctrl and Enter');
  assert.equal(sendChordLabel('MacIntel'), 'Command and Enter', 'a Mac is not told about Command and Enter');
  assert.equal(sendChordKeyshortcut('Win32'), 'Control+Enter', 'Windows announces the wrong key');
  assert.equal(sendChordKeyshortcut('Linux x86_64'), 'Control+Enter', 'Linux announces the wrong key');
  assert.equal(sendChordKeyshortcut('MacIntel'), 'Meta+Enter', 'a Mac announces the wrong key');
  assert.equal(sendChordSentence('Win32'), 'Ctrl and Enter sends from anywhere in the panel.');
  assert.equal(sendChordSentence('MacIntel'), 'Command and Enter sends from anywhere in the panel.');

  assert.equal(isSendChord(press({ ctrlKey: true }), 'Win32'), true, 'Ctrl and Enter does not send on Windows');
  assert.equal(isSendChord(press({ ctrlKey: true }), 'Linux x86_64'), true, 'Ctrl and Enter does not send on Linux');
  assert.equal(isSendChord(press({ metaKey: true }), 'MacIntel'), true, 'Command and Enter does not send on a Mac');

  // Reject the other platform's modifier.
  assert.equal(isSendChord(press({ ctrlKey: true }), 'MacIntel'), false, 'Ctrl and Enter sends on a Mac');
  assert.equal(isSendChord(press({ metaKey: true }), 'Win32'), false, 'Command and Enter sends on Windows');

  assert.equal(isSendChord(press({}), 'Win32'), false, 'plain Enter is read as the chord');
  assert.equal(isSendChord(press({ shiftKey: true }), 'Win32'), false, 'Shift and Enter is read as the chord');
  assert.equal(
    isSendChord(press({ ctrlKey: true, shiftKey: true }), 'Win32'),
    false,
    'Ctrl, Shift and Enter is read as the chord, so the new line it makes also sends',
  );
  assert.equal(isSendChord(press({ altKey: true }), 'Win32'), false, 'Alt and Enter is read as the chord');
  assert.equal(
    isSendChord(press({ ctrlKey: true, altKey: true }), 'Win32'),
    false,
    'Ctrl, Alt and Enter is read as the chord',
  );
  assert.equal(isSendChord(press({ key: 'a', ctrlKey: true }), 'Win32'), false, 'a letter is read as the chord');
  assert.equal(isSendChord(null, 'Win32'), false, 'a listener handed nothing at all sends the box');
});

// Cut and copy use the current line when the text selection is empty.

test('the line under the caret is taken with the break that separates it from its neighbour', () => {
  const took = (text: string, caret: number, cut = false) => {
    const at = lineRange(text, caret, cut);
    return text.slice(at.start, at.end);
  };

  // Include the following line break for both cut and copy.
  for (const cut of [false, true]) {
    assert.equal(took('one\ntwo\nthree', 0, cut), 'one\n', 'the caret at the start of a line takes the wrong line');
    assert.equal(took('one\ntwo\nthree', 3, cut), 'one\n', 'the caret at the end of a line takes the line after it');
    assert.equal(
      took('one\ntwo\nthree', 4, cut),
      'two\n',
      'the caret at the start of the middle line takes the wrong line',
    );
    assert.equal(
      took('one\ntwo\nthree', 6, cut),
      'two\n',
      'the caret inside a line takes something other than that line',
    );
    // Empty middle lines retain their line break.
    assert.equal(took('a\n\nb', 2, cut), '\n', 'an empty line in the middle cannot be cut');
  }

  // Cutting the final line includes its preceding break.
  // Copying it excludes that break.
  assert.equal(took('one\ntwo\nthree', 9, true), '\nthree', 'the last line leaves an empty line behind when it is cut');
  assert.equal(took('one\ntwo\nthree', 13, true), '\nthree', 'the caret at the very end cuts the wrong line');
  assert.equal(
    took('one\ntwo\nthree', 9),
    'three',
    'a copy of the last line opens with a break the reader did not copy',
  );
  assert.equal(took('one\ntwo\nthree', 13), 'three', 'a copy at the very end takes the wrong line');

  // A single line is taken whole, and an empty text field supplies nothing.
  for (const cut of [false, true]) {
    assert.equal(took('one line', 4, cut), 'one line', 'the only line in the box is not taken whole');
    assert.equal(took('', 0, cut), '', 'an empty box hands the clipboard something');
  }
});

test('cut and copy are read off the press, and every other press is left alone', () => {
  const press = (over: Record<string, unknown>) => ({
    key: 'x',
    ctrlKey: false,
    metaKey: false,
    shiftKey: false,
    altKey: false,
    ...over,
  });

  assert.equal(lineIntent(press({ ctrlKey: true })), 'cut', 'Ctrl and X is not cut');
  assert.equal(lineIntent(press({ metaKey: true })), 'cut', 'Cmd and X is not cut, so a Mac has no line cut');
  assert.equal(lineIntent(press({ key: 'c', ctrlKey: true })), 'copy', 'Ctrl and C is not copy');
  assert.equal(
    lineIntent(press({ key: 'C', metaKey: true })),
    'copy',
    'the press is read off the letter as it arrives, so Caps Lock takes the line copy away',
  );

  assert.equal(lineIntent(press({})), '', 'a bare X is taken, so the letter cannot be typed');
  assert.equal(lineIntent(press({ ctrlKey: true, shiftKey: true })), '', 'Ctrl, Shift and X is taken as a line cut');
  assert.equal(lineIntent(press({ ctrlKey: true, altKey: true })), '', 'a press with Alt held is taken as a line cut');
  assert.equal(lineIntent(press({ key: 'v', ctrlKey: true })), '', 'paste is answered as though it were a cut');
  assert.equal(lineIntent(null), '', 'a listener handed nothing at all answers with a press');
});

