test('attachment compatibility and contents are checked at every handoff boundary', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const pickAt = panelHostSource.indexOf('private pickOnDraft(');
  const pick = memberFrom(panelHostSource, pickAt);
  sourceMatch(
    pick,
    /unsupportedPromptAsset\(next\.agent, this\.assets\[session\] \?\? \[\]\)/,
    'a draft can switch to an agent that cannot read an attached file',
  );
  sourceMatch(
    pick,
    /setAttachmentNotice[\s\S]*return;/,
    'an incompatible agent switch neither explains the refusal nor stops the switch',
  );

  const sendAt = panelHostSource.indexOf('private sendPrompt(');
  const send = panelHostSource.slice(sendAt, panelHostSource.indexOf('// The one place a prompt leaves', sendAt));
  sourceMatch(
    send,
    /unsupportedPromptAsset\(state\.agent, heldAssets\)/,
    'Send does not recheck whether the aimed agent accepts every attached file',
  );
  sourceMatch(
    send,
    /attachmentRefusal\('unsupported', unsupported\.name\)[\s\S]*restoreDraft/,
    'a send-time compatibility refusal loses the draft or omits its inline notice',
  );

  assert.equal(
    [...extensionSource.matchAll(/validateResolvedPromptAssets\(prompt\.assets\)/g)].length,
    3,
    'an existing, forked, or fresh session can send files changed while that session was opening',
  );
  const directAt = extensionSource.indexOf('const turnId = await withExistingSessionActivity');
  const direct = extensionSource.slice(directAt, extensionSource.indexOf('panel.refresh()', directAt));
  sourceMatch(
    direct,
    /withExistingSessionActivity[\s\S]*validateResolvedPromptAssets[\s\S]*session\.prompt/,
    'the existing-session check runs before the opening wait or after prompt delivery',
  );

  sourceMatch(
    hostHandler('attachFiles'),
    /mime: stagedAssetMime\(file\.name, file\.mime, bytes\)/,
    'paste and drop still let a browser MIME override a known textual filename extension',
  );

  const writes = [...panelHostSource.matchAll(/const written = await stagePromptAssets/g)].map(
    (match) => match.index ?? -1,
  );
  assert.equal(writes.length, 1);
  for (const at of writes) {
    const after = memberFrom(panelHostSource, at);
    sourceMatch(
      after,
      /stateFor\(target\)[\s\S]*unsupportedPromptAsset\(settled\.agent, written\)[\s\S]*mergePromptAssets/,
      'an agent switch during file staging can merge a file the new agent cannot read',
    );
  }

  const abandonAt = panelHostSource.indexOf('public abandonDraft(');
  const abandon = memberFrom(panelHostSource, abandonAt);
  sourceMatch(
    abandon,
    /this\.staging\.has\(draftId\)/,
    'an attachment-only draft can be abandoned while its file is still staging',
  );
});

