test('a session row carries a bounded rail name, past the sixty-character cut the timeline heading still reads, but short of the complete name', () => {
  const long = Array.from({ length: 60 }, (_, i) => `word${i}`).join(' ');
  assert.ok(long.length > 200, 'the fixture name is not long enough to exercise the rail bound');
  const full = normalizeFullSessionTitle(long);
  const capped = normalizeSessionTitle(long);
  assert.equal(full, long, 'normalizeFullSessionTitle keeps a bound of its own, cutting what Details and rename show');
  assert.ok(
    capped !== null && capped.length <= 63,
    'the timeline heading, search results and saved comments no longer read the sixty-character cut',
  );

  const from = panelHostSource.indexOf('this.sessionRows = all.map(');
  const statement = statementFrom(panelHostSource, from);
  const built = esbuild.transformSync(
    `export function build(all, sessions, parentEdges, fullLabels, AGENT_NAMES, formatWhen, formatRelative, shortenTo, RAIL_NAME_LIMIT) {\n${statement}\n  return this.sessionRows;\n}`,
    { loader: 'ts', format: 'cjs' },
  ).code;
  const builtModule = { exports: {} as { build: (...args: unknown[]) => { label: string; railName?: string }[] } };
  new Function('module', 'exports', built)(builtModule, builtModule.exports);
  const rows = builtModule.exports.build.call(
    { activityFor: () => 0, sessionLabel: () => ({ label: capped, fullLabel: full }), agentRunFor: () => false },
    [{ sessionId: 's1', agent: 'claude' }],
    [],
    { edges: [] },
    new Map(),
    { claude: 'Claude' },
    () => '',
    () => '',
    shortenTo,
    200,
  );
  assert.equal(
    rows[0].label,
    capped,
    'a rail row lost its own short label; the popover heading and composer target would draw the wide name',
  );
  assert.notEqual(
    rows[0].railName,
    undefined,
    'a rail row falls back to the sixty-character label; the rail can draw only as much as the heading does',
  );
  assert.ok(rows[0].railName!.length <= 203, 'a rail row carries its complete, unbounded name on every render payload');
  assert.notEqual(
    rows[0].railName,
    full,
    'a rail row carries its complete, unbounded name rather than a bound past any rail width',
  );
});

// Supply metadata, parsed-name, and rename inputs to the provider's naming methods.
function namedSessionProvider(
  stored: Iterable<[string, Record<string, unknown>]> = [],
  overrides: { file?: string; agent?: 'claude' | 'codex'; codexTurnTitle?: string } = {},
) {
  const session = {
    sessionId: 'named-session',
    file: overrides.file ?? 'named-session.jsonl',
    agent: overrides.agent ?? 'claude',
    size: overrides.file ? fs.statSync(overrides.file).size : 1000,
    mtimeMs: 10,
    cwd: 'C:\\ws',
    // Preserve the catalog's file identity with each reported revision.
    dev: overrides.file
      ? listSessionFiles(path.dirname(overrides.file)).find((row) => row.file === overrides.file)?.dev
      : undefined,
    ino: overrides.file
      ? listSessionFiles(path.dirname(overrides.file)).find((row) => row.file === overrides.file)?.ino
      : undefined,
  };
  // Supply Codex parsed-turn names for heading projection.
  const codexTitles = new Map(overrides.codexTurnTitle ? [[session.sessionId, overrides.codexTurnTitle]] : []);
  const provider = Object.create(PanelProvider.prototype) as LiveProvider;
  const titles = new Map<string, Record<string, unknown>>(stored);
  Object.assign(provider, {
    sessionNames: new SessionNames(),
    titles,
    carriedNames: new Map(),
    derivedCacheCheckpointState: { markChanged: () => undefined },
  });
  const call = (method: string, ...args: unknown[]) =>
    (provider[method] as (...values: unknown[]) => unknown).apply(provider, args);
  const byId = new Map([[session.sessionId, session]]);
  return {
    titles,
    metadata(entry: Record<string, unknown>, previous = titles.get(session.file)) {
      const stored = {
        size: session.size,
        mtimeMs: 10,
        fullLabel: entry.label,
        activityMs: null,
        agentRun: false,
        outcome: null,
        stats: null,
        ...entry,
      };
      titles.set(
        session.file,
        carryDerivedTitleFacts(
          previous as DerivedTitleEntry | undefined,
          stored as DerivedTitleEntry,
        ) as unknown as Record<string, unknown>,
      );
      // Fresh metadata replaces the carried name.
      (provider['carriedNames'] as Map<string, unknown>).delete(session.file);
      call('observeStoredEntry', session, titles.get(session.file));
    },
    drawn() {
      return {
        rail: (call('sessionLabel', session) as { label: string }).label,
        heading: call('headingTitle', session.sessionId, byId, codexTitles) as string,
      };
    },
    // Supply current metadata size while retaining the catalog's earlier size.
    readMetadataAfterGrowth() {
      const meta = readSessionMeta(session.file);
      this.metadata({
        size: fs.statSync(session.file).size,
        label: meta.title,
        fullLabel: meta.fullTitle,
        nameSource: meta.titleSource,
        nameAt: meta.titleAt,
      });
    },
    // Update catalog identity and size before reading transcript metadata.
    readMetadata() {
      const listed = listSessionFiles(path.dirname(session.file)).find((row) => row.file === session.file)!;
      session.ino = listed.ino;
      session.size = listed.size;
      const meta = readSessionMeta(session.file);
      this.metadata({
        size: session.size,
        label: meta.title,
        fullLabel: meta.fullTitle,
        nameSource: meta.titleSource,
        nameAt: meta.titleAt,
      });
    },
    refresh(parsed: ReturnType<typeof turn>, catalog?: ReturnType<typeof listSessionFiles>[number]) {
      if (catalog) Object.assign(session, catalog);
      call('observeParsedNames', [parsed], byId);
      return {
        rail: (call('sessionLabel', session) as { label: string }).label,
        heading: call('headingTitle', session.sessionId, byId, new Map()) as string,
      };
    },
    // Read the native Codex name index into the provider.
    readIndex() {
      Object.assign(provider, { threadNames: readThreadNames(codexSessionIndexPath(), null) });
    },
    // Run the host rename method with a stubbed agent callback and capture names at refresh.
    rename(title: string, agent: (title: string) => Promise<void>, state: Record<string, unknown> = {}) {
      const renders: Array<{ reason: unknown; paths: unknown; rail: string; heading: string }> = [];
      Object.assign(provider, {
        ...state,
        catalog: { folders: '', sessions: [session] },
        onRenameSession: async (_agent: string, _session: string, _cwd: string | null, name: string) => agent(name),
        refresh: () => {
          renders.push({ reason: provider['refreshReason'], paths: provider['targetedRefreshPaths'], ...this.drawn() });
          return Promise.resolve();
        },
      });
      return {
        renders,
        result: call('renameSession', session.sessionId, title) as Promise<{ title: string; error: string }>,
      };
    },
    // Supply a name carried across derived-cache invalidation.
    carry(label: string) {
      (provider['carriedNames'] as Map<string, unknown>).set(session.file, { label, fullLabel: label });
    },
    // Return the distinct names used by this session's search entries.
    search() {
      Object.assign(provider, { corpus: provider['corpus'] ?? new Map(), allSessions: () => [session] });
      return [...new Set((call('searchCorpus') as Array<{ sessionTitle: string }>).map((entry) => entry.sessionTitle))];
    },
    // Read provider-owned selection, pin, label, and read state.
    reader() {
      return readerOf(provider);
    },
  };
}

// Supply selected identity, pin membership, labels, and read watermarks.
function readerState(): Record<string, unknown> {
  return {
    showing: 'named-session',
    pinnedTop: new Set(['named-session']),
    saved: {
      labels: { 'named-session': ['perf'] },
      read: { 'named-session': 'k1' },
      readTo: { 'named-session': 100 },
      pinnedTop: ['named-session'],
    },
  };
}

function readerOf(from: Record<string, unknown>): unknown {
  const saved = from.saved as Record<string, unknown>;
  return {
    showing: from.showing,
    pinnedTop: [...(from.pinnedTop as Set<string>)],
    labels: saved.labels,
    read: saved.read,
    readTo: saved.readTo,
    savedPins: saved.pinnedTop,
  };
}

// Build one native Claude custom-title record.
function customTitleRecord(title: string): string {
  return `${JSON.stringify({ type: 'custom-title', customTitle: title, sessionId: 'named-session' })}\n`;
}

function renamedClaudeTranscript(): string {
  const file = path.join(tempDir('rename-panel-'), 'named-session.jsonl');
  fs.writeFileSync(
    file,
    `${JSON.stringify({
      type: 'user',
      uuid: 'u1',
      sessionId: 'named-session',
      timestamp: '2026-09-18T10:00:00.000Z',
      message: { role: 'user', content: 'Fix the login flow' },
    })}\n${customTitleRecord('First name')}`,
  );
  return file;
}

test('renaming a session that already has a custom name draws the new name on its rail row and heading together', async () => {
  const file = renamedClaudeTranscript();
  const provider = namedSessionProvider([], { file });
  provider.readMetadata();
  const olderCustomMetadata = { ...provider.titles.get(file) };
  assert.deepEqual(provider.drawn(), { rail: 'First name', heading: 'First name' });
  const { renders, result } = provider.rename(
    '  Second   name ',
    async (title) => {
      fs.appendFileSync(file, customTitleRecord(title));
    },
    readerState(),
  );
  assert.deepEqual(await result, { title: 'Second name', error: '' });
  provider.metadata(olderCustomMetadata, olderCustomMetadata);
  assert.deepEqual(
    provider.drawn(),
    { rail: 'Second name', heading: 'Second name' },
    'delayed custom metadata erased the confirmed rename',
  );
  assert.equal(provider.titles.get(file)?.label, 'Second name', 'delayed custom metadata persisted the old name');
  assert.deepEqual(
    renders,
    [{ reason: 'session-rename', paths: [file], rail: 'Second name', heading: 'Second name' }],
    'the render after the rename drew the old name',
  );
  provider.readMetadata();
  assert.deepEqual(provider.drawn(), { rail: 'Second name', heading: 'Second name' });
  assert.equal(provider.titles.get(file)?.label, 'Second name', 'a restart draws the old name');
  assert.deepEqual(
    provider.reader(),
    readerOf(readerState()),
    'a rename changed the selection, the pin, the labels, or the read state',
  );

  // A later native Claude title takes precedence.
  fs.appendFileSync(file, customTitleRecord('Third name'));
  provider.readMetadata();
  assert.deepEqual(
    provider.drawn(),
    { rail: 'Third name', heading: 'Third name' },
    'a later native rename lost to the name Arc held',
  );
});

