// Supply production performance counters and threshold checks with captured diagnostic outputs.
function startupFixture() {
  const logged: Array<[string, Record<string, unknown>]> = [];
  const warned: Array<[string, Record<string, unknown>]> = [];
  const notices: string[] = [];
  const host = { webview: {}, visible: () => true };
  const provider = Object.create(PanelProvider.prototype) as LiveProvider;
  Object.assign(provider, {
    hosts: [host],
    readyHosts: new Set([host]),
    refreshGeneration: 7,
    clearRoutes: new Map(),
    panelStartedAt: null,
    startupThresholds: new StartupThresholdWatch(),
    diagnostics: {
      enabled: () => true,
      log: (event: string, record: Record<string, unknown>) => {
        logged.push([event, record]);
      },
      warn: (event: string, record: Record<string, unknown>) => {
        warned.push([event, record]);
      },
      file: () => null,
    },
    performanceOutput: {
      appendLine: (line: string) => {
        notices.push(line);
      },
    },
  });
  const wiring = provider as unknown as { performanceSink(): PerformanceEventSink };
  Object.assign(provider, { performanceCounters: new PanelPerformanceCounters(0, wiring.performanceSink()) });
  const call = provider as unknown as {
    notePanelStart(): void;
    browserPainted(host: unknown, generation: number, stage: string): void;
  };
  return { call, host, logged, warned, notices };
}

// Measure startup duration from panel opening rather than process startup.
test('the startup threshold measures the wait since the panel opened', () => {
  const clock = vi.spyOn(performance, 'now');
  try {
    const quick = startupFixture();
    // Open the panel after one process hour and acknowledge its first card 1.5 seconds later.
    clock.mockReturnValue(3_600_000);
    quick.call.notePanelStart();
    clock.mockReturnValue(3_601_500);
    quick.call.browserPainted(quick.host, 7, 'firstCard');

    assert.deepEqual(quick.notices, [], 'a panel that drew in 1.5 seconds reported a slow start');
    assert.deepEqual(quick.warned, [], 'a panel that drew in 1.5 seconds wrote a breach whatever the setting says');
    assert.deepEqual(
      quick.logged,
      [
        [
          'startup',
          {
            milestone: 'firstCard',
            elapsedMs: 3_601_500,
            panelElapsedMs: 1_500,
          },
        ],
      ],
      'the log lost the host-relative milestone or the panel-relative one',
    );

    const slow = startupFixture();
    clock.mockReturnValue(3_600_000);
    slow.call.notePanelStart();
    clock.mockReturnValue(3_640_000);
    slow.call.browserPainted(slow.host, 7, 'firstCard');

    assert.deepEqual(
      slow.notices,
      ['Arc took 40 seconds to draw its first card. The expected time is under 30 seconds.'],
      'a panel that took 40 seconds to draw told the reader nothing',
    );
    assert.deepEqual(slow.warned, [
      [
        'startupThreshold',
        {
          milestone: 'firstCard',
          elapsedMs: 40_000,
          hostElapsedMs: 3_640_000,
          thresholdMs: 30_000,
        },
      ],
    ]);
  } finally {
    clock.mockRestore();
  }

  sourceMatch(
    panelHostSource,
    /private attach\(host: PanelHost\): void \{\s*this\.notePanelStart\(\);/,
    'a panel opening does not record when it started loading',
  );
  sourceMatch(
    panelHostSource,
    /new PanelPerformanceCounters\(Date\.now\(\), this\.performanceSink\(\)\)/,
    'the counters report to something other than the panel diagnostics sink',
  );
});

// A first card after completeRender does not extend the startup interval.
test('a first card drawn after the first draw finished reports no slow start', () => {
  const clock = vi.spyOn(performance, 'now');
  try {
    const empty = startupFixture();
    clock.mockReturnValue(1_000);
    empty.call.notePanelStart();
    clock.mockReturnValue(2_000);
    empty.call.browserPainted(empty.host, 7, 'railReady');
    clock.mockReturnValue(3_000);
    empty.call.browserPainted(empty.host, 7, 'completeRender');
    // Advance three hours after startup completion before acknowledging the first card.
    clock.mockReturnValue(10_803_000);
    empty.call.browserPainted(empty.host, 7, 'firstCard');

    assert.deepEqual(empty.notices, [], 'a card drawn hours after the first draw reported a slow start');
    assert.deepEqual(
      empty.warned,
      [],
      'a card drawn hours after the first draw wrote a breach whatever the setting says',
    );
    assert.deepEqual(
      empty.logged.map(([, record]) => record.milestone),
      ['railReady', 'completeRender', 'firstCard'],
      'the log lost a milestone',
    );
  } finally {
    clock.mockRestore();
  }
});

