// Log every message-budget breach and warn once per message kind.
test('every budget breach reaches the log and the first of a kind reaches the reader', () => {
  const logged: Array<[string, Record<string, unknown>]> = [];
  const notices: string[] = [];
  const host = { webview: { postMessage: () => true } };
  const provider = Object.create(PanelProvider.prototype) as LiveProvider;
  Object.assign(provider, {
    readyHosts: new Set([host]),
    warnedMessageBudgets: new Set<string>(),
    diagnostics: {
      enabled: () => true,
      log: (event: string, record: Record<string, unknown>) => {
        logged.push([event, record]);
      },
      warn: () => {},
      file: () => null,
    },
    performanceOutput: {
      appendLine: (line: string) => {
        notices.push(line);
      },
    },
  });
  const wiring = provider as unknown as { performanceSink(): PerformanceEventSink };
  Object.assign(provider, { performanceCounters: new PanelPerformanceCounters(0, wiring.performanceSink()) });
  const call = provider as unknown as {
    sendToHost(host: unknown, message: unknown): Thenable<boolean>;
  };

  const message = { type: 'render', cards: 'x'.repeat(300_000) };
  call.sendToHost(host, message);
  call.sendToHost(host, message);
  call.sendToHost(host, { type: 'usage', usage: [] });

  const bytes = Buffer.byteLength(JSON.stringify(message), 'utf8');
  const breaches = logged.filter(([event]) => event === 'budgetBreach');
  assert.equal(breaches.length, 2, 'a refresh over budget on every post reached the log fewer times than it breached');
  assert.deepEqual(breaches[1][1], { kind: 'render', bytes, budgetBytes: 250_000 });
  assert.equal(notices.length, 1, 'the output channel repeats a line for one message kind');
  assert.equal(notices[0].startsWith(`render message is ${bytes} bytes, above its 250000-byte budget.`), true);
  assert.equal(
    logged.filter(([event]) => event === 'message').length,
    3,
    'a posted message left the log without its kind and byte count',
  );
});

