test.each(['rejection', 'null', 'moved'])(
  'handoff worker outcomes name failures while owner movement stays silent (%s)',
  async (outcome) => {
    const notices: string[] = [];
    const original = vscode.window.showInformationMessage;
    Object.assign(vscode.window, {
      showInformationMessage: (message: string) => {
        notices.push(message);
        return Promise.resolve();
      },
    });
    try {
      const f = pendingModelLauncher();
      notices.length = 0;
      f.provider.progressiveWorker.run = async () => {
        if (outcome === 'rejection') throw new Error('worker unavailable');
        if (outcome === 'moved') f.provider.hostSessions.set(f.owner, 'other');
        return null;
      };
      await f.provider.finishHandoffRecovery('source', null, '', false, f.owner);
      assert.equal(f.created.length, 0);
      assert.equal(notices.length, outcome === 'moved' ? 0 : 1);
      assert.equal(f.provider.attachmentHandoffs.size, 0);
    } finally {
      Object.assign(vscode.window, { showInformationMessage: original });
    }
  },
);

test.each(['complete', 'moved', 'closed', 'generation'])(
  'reader menu parent survives deferred recovery only for its owner (%s)',
  async (outcome) => {
    const f = pendingModelLauncher();
    f.provider.sessionAliases = new Map();
    f.provider.detailsMenuArm = { host: f.owner, session: 'source', at: Date.now() };
    f.provider.newSessionWithLabels('source');
    assert.deepEqual(f.provider.saved.readerParents, {});
    assert.deepEqual(f.created, []);
    if (outcome === 'moved') f.provider.hostSessions.set(f.owner, 'other');
    if (outcome === 'closed') f.provider.hosts = [];
    if (outcome === 'generation') f.provider.selectionGeneration++;
    f.release(f.result);
    await f.completed();
    assert.equal(f.created.length, outcome === 'complete' ? 1 : 0);
    assert.deepEqual(
      f.provider.saved.readerParents,
      outcome === 'complete' ? { [f.created[0][0] as string]: 'source' } : {},
    );
  },
);

