test('provider reload sweeps provisional reader parents independently of labels and keeps stale-panel saves host-owned', () => {
  const listener = vi
    .spyOn(PanelProvider.prototype as unknown as { wireEditorListeners(): void }, 'wireEditorListeners')
    .mockImplementation(() => {});
  const draft = `${DRAFT_SESSION_PREFIX}parent`;
  let stored: unknown = {
    labels: 'invalid',
    readerParents: { child: draft, [draft]: 'durable', durableChild: 'undiscovered' },
  };
  const memento = {
    get: () => stored,
    update: (_key: string, value: unknown) => {
      stored = structuredClone(value);
      return Promise.resolve();
    },
  } as unknown as vscode.Memento;
  let first: InstanceType<typeof PanelProvider> | undefined;
  let second: InstanceType<typeof PanelProvider> | undefined;
  try {
    first = new PanelProvider('', {} as vscode.Uri, memento);
    const provider = first as unknown as Record<string, any>;
    assert.deepEqual(provider.saved.readerParents, { durableChild: 'undiscovered' });
    provider.readPrint = () => '';
    provider.saveState({ collapsed: ['another-panel'], readerParents: { forged: 'parent' } });
    second = new PanelProvider('', {} as vscode.Uri, memento);
    const reloaded = second as unknown as Record<string, any>;
    assert.deepEqual(reloaded.saved.readerParents, { durableChild: 'undiscovered' });
    assert.deepEqual(reloaded.saved.collapsed, ['another-panel']);
    assert.equal('readerParents' in webviewPanelState(reloaded.saved), false);
    reloaded.sessionRows = [
      { id: 'durableChild', label: 'Child' },
      { id: 'undiscovered', label: 'Parent returned' },
    ];
    assert.deepEqual(reloaded.parentOfShown('durableChild'), {
      id: 'undiscovered',
      label: 'Parent returned',
      relation: 'reader',
    });
  } finally {
    first?.dispose();
    second?.dispose();
    listener.mockRestore();
  }
});

test.each(['claude', 'codex'] as const)(
  'submitted recovery keeps the %s setup through accepted adoption and follow-up',
  async (agent) => {
    const { provider } = queueRecoveryProvider();
    const session = `draft:first-${agent}`;
    const host = { webview: {} };
    const profile: SessionProfile = { agent, model: '', effort: '', permissionMode: '', source: 'custom' };
    const original = newSessionDraft(session, 'C:/ws', null, 1000, profile);
    Object.assign(provider, {
      hosts: [host],
      hostSessions: new Map([[host, session]]),
      readyHosts: new Set([host]),
      hostPreviousSessions: new Map(),
      hidden: new Set(),
      pinnedTop: new Set(),
      trail: emptyTrail(),
      sessionRows: [{ id: session, label: 'Draft', agentKey: agent }],
      commandLists: {},
      skillLists: {},
      askLevels: {},
      running: new Set(),
      models: {},
      mcpServers: {},
      stagingTokens: new Map(),
      stagingOperations: new Map(),
      draftRevisions: new Map(),
    });
    provider.newDrafts[session] = original;
    provider.draftProfiles[session] = original.profile;
    provider.picks[session] = sessionSettingsForProfile(profile);
    const oldState = provider.stateFor.bind(provider);
    provider.stateFor = (id: string) => {
      const state = oldState(id);
      return state
        ? {
            ...state,
            agent: provider.newDrafts[id]?.profile.agent ?? provider.awaitingSessionRecords[id]?.agent ?? agent,
            profile: provider.draftProfiles[id],
            settings: { ...provider.picks[id] },
          }
        : null;
    };
    let release!: () => void;
    const waiting = new Promise<void>((resolve) => {
      release = resolve;
    });
    provider.memento.update = () => waiting;
    let accept!: (answer: PromptDelivery) => void;
    let launched: NewSessionDraft | undefined;
    provider.onSendDraftPrompt = (draft: NewSessionDraft) => {
      launched = draft;
      return new Promise<PromptDelivery>((resolve) => {
        accept = resolve;
      });
    };
    const published: unknown[] = [];
    provider.onSessionSettingsAdopted = (id: string, settings: unknown) => published.push([id, settings]);
    const text = '  first\n' + 'x'.repeat(4500) + '\n  ';
    await provider.onMessage({ type: 'draft', session, text, keep: text, revision: 1 }, host);
    const attempt = { id: `first-${agent}`, order: 1, source: session, revision: 2, text };
    const pending = provider.acceptSubmission(text, session, 2, session, host, attempt);
    provider.pickOnDraft(session, 'agent', agent === 'claude' ? 'codex' : 'claude');
    assert.notEqual(provider.newDrafts[session].profile.agent, agent);
    provider.sessionRows[0].agentKey = provider.newDrafts[session].profile.agent;
    provider.queues[session] = queueSubmissionAfter([], 'queued', 'newer draft', [], [], 1, false, {
      agent,
      owner: session,
    });
    provider.sendToHost = () => Promise.resolve(true);
    provider.requestQueuedEdit('queued', session, 2, host);
    provider.acceptQueuedEdit('queued', session, 2, 3, true, host);
    release();
    await pending;
    assert.equal(launched?.profile.agent, agent);
    accept({ delivered: true, reason: '', session: 'accepted' });
    await vi.waitFor(() => assert.equal(provider.awaitingSessionRecords.accepted?.agent, agent));
    assert.deepEqual(launched?.profile, original.profile);
    assert.deepEqual(provider.picks.accepted, sessionSettingsForProfile(profile));
    assert.deepEqual(published, [['accepted', sessionSettingsForProfile(profile)]]);
    assert.equal(provider.drafts.accepted, 'newer draft');
    assert.equal(provider.draftRevisions.get('accepted'), 3);
    delete provider.stateFor;
    assert.equal(provider.stateFor('accepted').agent, agent);
    const targets: string[] = [];
    provider.onSendPrompt = async (nextAgent: string) => {
      targets.push(nextAgent);
      return { delivered: true, session: 'accepted' };
    };
    await provider.onMessage(
      { type: 'draft', session: 'accepted', text: 'follow-up', keep: 'follow-up', revision: 4 },
      host,
    );
    provider.sendPrompt('follow-up', 'accepted', 5);
    await vi.waitFor(() => assert.deepEqual(targets, [agent]));
  },
);

test('health distinguishes unready actions, handler failure and acknowledgements without logging their content', async () => {
  const fixture = liveProviderFixture(livePress());
  const provider = fixture.provider as unknown as Record<string, any>;
  const directory = tempDir('provider-health');
  let clock = 0;
  const health = new HostHealth({
    directory,
    workspace: 'test',
    build: { sourceCommit: null, dirty: null, builtAt: 1 },
    now: () => clock,
  });
  provider.health = health;
  const lines = () =>
    fs
      .readFileSync(health.file.replace('.json', '.jsonl'), 'utf8')
      .trim()
      .split('\n')
      .map((line) => JSON.parse(line));
  try {
    provider.readyHosts.clear();
    await provider.onMessage({ type: 'showSession', session: 'secret-session' }, fixture.host);
    assert.equal(lines().at(-1).event, 'unready');
    assert.equal(
      lines().some((line) => line.phase === 'select'),
      false,
    );
    provider.readyHosts.add(fixture.host);
    provider.show = () => {
      throw new Error('secret-error');
    };
    await assert.rejects(
      provider.onMessage({ type: 'showSession', session: 'secret-session' }, fixture.host),
      /secret-error/,
    );
    assert.equal(lines().at(-1).outcome, 'failed');
    clock += 1000;
    provider.newSession = () => true;
    await provider.onMessage({ type: 'newSession' }, fixture.host);
    assert.equal(lines().at(-1).phase, 'new');
    assert.equal(lines().at(-1).outcome, 'returned');
    provider.healthPanel(fixture.host).sent = 77;
    await provider.onMessage({ type: 'health', sequence: 76 }, fixture.host);
    assert.equal(provider.healthPanel(fixture.host).ack, 76);
    await provider.onMessage({ type: 'health', sequence: 77 }, fixture.host);
    assert.equal(provider.healthPanel(fixture.host).ack, 77);
    assert.equal(lines().at(-1).event, 'ack');
    const warning = vi.spyOn(console, 'warn').mockImplementation(() => {});
    try {
      clock += 1000;
      await provider.onMessage({ type: 'sendPrompt', text: 'secret-prompt' }, fixture.host);
    } finally {
      warning.mockRestore();
    }
    assert.equal(lines().at(-1).event, 'parseRejected');
    assert.equal(fs.readFileSync(health.file.replace('.json', '.jsonl'), 'utf8').includes('secret'), false);
    const blocked = path.join(directory, 'blocked');
    fs.writeFileSync(blocked, 'file');
    const failed = new HostHealth({
      directory: blocked,
      workspace: 'test',
      build: { sourceCommit: null, dirty: null, builtAt: 1 },
    });
    provider.health = failed;
    await provider.onMessage({ type: 'newSession' }, fixture.host);
    assert.equal(failed.status().failed, true);
    failed.dispose();
  } finally {
    health.dispose();
  }
});

test('health replies advance across pulses and replacement panels survive unresolved transports', async () => {
  const fixture = liveProviderFixture(livePress());
  const provider = fixture.provider as unknown as Record<string, any>;
  const never = new Promise<boolean>(() => {});
  const callbacks = new Set<unknown>();
  let posts = 0;
  const send = provider.sendToHost;
  provider.sendToHost = (_host: unknown, message: any) => {
    if (message.type !== 'health') return Promise.resolve(true);
    posts++;
    return {
      then(fulfilled: unknown, rejected: unknown) {
        callbacks.add(fulfilled);
        callbacks.add(rejected);
        return never;
      },
    };
  };
  const oldHosts = Array.from({ length: 20 }, () => ({}));
  provider.hosts = oldHosts;
  provider.healthPulse(1);
  provider.healthPulse(2);
  assert.equal(posts, 16);
  await provider.onMessage({ type: 'health', sequence: 1 }, oldHosts[0]);
  assert.equal(provider.healthPanel(oldHosts[0]).ack, 1);
  provider.healthPulse(3);
  assert.equal(posts, 17);
  await provider.onMessage({ type: 'health', sequence: 1 }, oldHosts[0]);
  assert.equal(provider.healthPanel(oldHosts[0]).ack, 1);
  await provider.onMessage({ type: 'health', sequence: 4 }, oldHosts[0]);
  assert.equal(provider.healthPanel(oldHosts[0]).ack, 1);
  await provider.onMessage({ type: 'health', sequence: 3 }, oldHosts[0]);
  assert.equal(provider.healthPanel(oldHosts[0]).ack, 3);
  for (let i = 0; i < 40; i++) {
    provider.hosts = [(fixture.host = {} as any)];
    provider.healthPulse(4 + i);
    assert.equal(provider.healthPanel(fixture.host).sent, 4 + i);
  }
  assert.equal(posts, 57);
  assert.equal(callbacks.size, 1);
  provider.readyHosts.add(fixture.host);
  let selected = false;
  provider.show = () => {
    selected = true;
  };
  await provider.onMessage({ type: 'showSession', session: 'source' }, fixture.host);
  assert.equal(selected, true);
  provider.sendToHost = send;
});

test('a recovered browser resumes bounded health requests on its existing panel host', async () => {
  const fixture = liveProviderFixture(livePress());
  const provider = fixture.provider as unknown as Record<string, any>;
  const host = fixture.host;
  const posts: number[] = [];
  provider.readyHosts.add(host);
  provider.sendToHost = (_host: unknown, message: { type: string; sequence: number }) => {
    if (message.type === 'health') posts.push(message.sequence);
    return new Promise<boolean>(() => {});
  };
  provider.healthPulse(1);
  provider.healthPulse(2);
  assert.deepEqual(posts, [1]);
  provider.browserReady(host);
  provider.healthPulse(3);
  provider.healthPulse(4);
  assert.deepEqual(posts, [1, 3]);
  assert.equal(provider.healthPanel(host).sent, 3);
  await provider.onMessage({ type: 'health', sequence: 1 }, host);
  assert.equal(provider.healthPanel(host).posting, true);
  await provider.onMessage({ type: 'health', sequence: 3 }, host);
  assert.equal(provider.healthPanel(host).posting, false);
});

