test('New health remains active during asynchronous recovery and records its actual settlement', async () => {
  const window = vscode.window as any;
  const original = window.showInformationMessage;
  window.showInformationMessage = () => {};
  try {
    for (const accepted of [true, false]) {
      const f = pendingModelLauncher();
      const provider = f.provider as Record<string, any>;
      const health = new HostHealth({
        directory: tempDir('host-health-new-recovery'),
        workspace: 'test',
        build: { sourceCommit: null, dirty: null, builtAt: 1 },
      });
      provider.health = health;
      provider.readyHosts = new Set([f.owner]);
      provider.healthPanels = new WeakMap();
      try {
        await provider.onMessage({ type: 'newSession', request: { kind: 'row', key: 'current' } }, f.owner);
        health.sample();
        const pending = JSON.parse(fs.readFileSync(health.file, 'utf8'));
        assert.equal(pending.active.filter((work: any) => work.phase === 'new').length, 1);
        assert.equal(
          pending.outcomes.some((work: any) => work.phase === 'new'),
          false,
        );
        assert.equal(f.created.length, 0);
        f.release(accepted ? f.result : null);
        await f.completed();
        health.sample();
        const settled = JSON.parse(fs.readFileSync(health.file, 'utf8'));
        assert.equal(settled.active.length, 0);
        assert.equal(settled.outcomes.at(-1).outcome, accepted ? 'returned' : 'rejected');
        assert.equal(settled.outcomes.at(-1).panel, pending.active[0].panel);
        assert.equal(f.created.length, accepted ? 1 : 0);
      } finally {
        health.dispose();
      }
    }
  } finally {
    window.showInformationMessage = original;
  }
});

test('submitted recovery refuses failed storage, changed scope and disposed origins without replacing newer drafts', async () => {
  for (const failure of ['storage', 'scope', 'disposed']) {
    const fixture = liveProviderFixture(livePress());
    const provider = fixture.provider as unknown as Record<string, any>;
    const health = new HostHealth({
      directory: tempDir('retention-health'),
      workspace: 'test',
      build: { sourceCommit: null, dirty: null, builtAt: 1 },
    });
    provider.health = health;
    provider.saved = normalizePanelState({});
    provider.stateFor = () => ({ ...COMPOSER, sessionId: 'sess', assets: [], draftCommentIds: [], queued: [] });
    let cwd = '/project';
    provider.cwdForSession = () => cwd;
    let release!: () => void;
    const suspended = new Promise<void>((resolve) => {
      release = resolve;
    });
    provider.memento = {
      update: () =>
        suspended.then(() => {
          if (failure === 'storage') throw new Error('full');
        }),
    };
    const delivered: unknown[] = [];
    provider.sendPrompt = (...args: unknown[]) => delivered.push(args);
    const text = 'unprotected first prompt';
    const attempt = { id: failure, order: 1, source: 'sess', revision: 1, text };
    const pending = provider.acceptSubmission(text, 'sess', 1, 'sess', fixture.host, attempt);
    const originalPanel = provider.healthPanel(fixture.host).id;
    health.sample();
    assert.ok(
      JSON.parse(fs.readFileSync(health.file, 'utf8')).active.some(
        (work: { phase: string }) => work.phase === 'retention',
      ),
    );
    provider.drafts.sess = 'newer draft';
    if (failure === 'scope') cwd = '/other';
    if (failure === 'disposed') provider.hosts = [];
    if (failure === 'disposed') provider.healthPanels.delete(fixture.host);
    release();
    await pending;
    const evidence = fs
      .readFileSync(health.file.replace('.json', '.jsonl'), 'utf8')
      .trim()
      .split('\n')
      .map((line) => JSON.parse(line));
    assert.equal(
      evidence.find((line) => line.phase === 'retention' && line.event === 'settled')?.outcome,
      failure === 'storage' ? 'failed' : 'returned',
    );
    assert.equal(evidence.find((line) => line.phase === 'send' && line.event === 'settled')?.panel, originalPanel);
    assert.equal(evidence.find((line) => line.phase === 'retention' && line.event === 'settled')?.panel, originalPanel);
    if (failure === 'disposed') assert.equal(provider.healthPanels.has(fixture.host), false);
    health.dispose();
    assert.equal(delivered.length, 0);
    assert.equal(provider.drafts.sess, 'newer draft');
    assert.equal(provider.saved.submittedPrompts[0].text, text);
  }
});

test.each(['opens', 'closes'] as const)(
  'a Claude prompt sent behind a queued compaction agrees with whether a request is open when a request %s during the save',
  async (change) => {
    const session = 's1';
    const { provider } = queueRecoveryProvider();
    const host = { webview: {} };
    const ask = { kind: 'question', id: 'ask-1', questions: [] };
    provider.asks = change === 'closes' ? [{ session, ask }] : [];
    provider.hosts = [host];
    provider.queues[session] = queueSubmissionAfter([], 'compact', '/compact', [], [], 1, false, {
      agent: 'claude',
      owner: session,
    });
    provider.stateFor = () => ({
      ...COMPOSER_STATE,
      sessionId: session,
      running: true,
      queued: provider.queues[session] ?? [],
      asks: provider.asks.filter((entry: any) => entry.session === session).map((entry: any) => entry.ask),
    });
    let release!: () => void;
    const saving = new Promise<void>((resolve) => {
      release = resolve;
    });
    provider.importPromptRecovery = () => saving;
    const answered: string[] = [];
    provider.onAnswerAsk = (_session: string, id: string) => answered.push(id);
    const sent: string[] = [];
    provider.send = (_state: unknown, text: string) => sent.push(text);
    const text = 'read the config';
    const attempt = { id: `asks-${change}`, order: 1, source: session, revision: 1, text };
    const pending = provider.acceptSubmission(text, session, 1, session, host, attempt);
    provider.asks = change === 'opens' ? [{ session, ask }] : [];
    release();
    await pending;
    const queuedBehind = provider.queues[session].map((entry: any) => entry.text);
    if (change === 'opens') {
      assert.deepEqual(answered, ['ask-1'], 'the request opened during the save was not answered by the prompt');
      assert.deepEqual(sent, [text], 'the answer waited behind the compaction after it closed the request');
      assert.deepEqual(queuedBehind, ['/compact']);
    } else {
      assert.deepEqual(answered, []);
      assert.deepEqual(sent, [], 'the prompt overtook the compaction after the request closed during the save');
      assert.deepEqual(queuedBehind, ['/compact', text]);
    }
  },
);

function catalogSendProvider(agent: 'claude' | 'codex') {
  const root = tempDir('catalog-send-');
  const workspace = path.join(root, 'workspace');
  const worktree = path.join(root, 'worktree');
  const session = `catalog-${agent}`;
  const source = { agent, file: path.join(root, `${session}.jsonl`), sessionId: session, cwd: worktree };
  const { provider } = queueRecoveryProvider();
  delete provider.cwdForSession;
  const host = { webview: {} };
  const posted: Array<Record<string, unknown>> = [];
  const delivered: Array<{ session: string; cwd: string; text: string }> = [];
  Object.assign(provider, {
    authoritativeCatalog: [source],
    catalog: { sessions: [source] },
    completeCatalogScope: JSON.stringify([workspace, worktree]),
    repositoryScopeRoots: [workspace, worktree],
    folders: () => [workspace],
    hosts: [host],
    hostSessions: new Map([[host, session]]),
    sessionRows: [{ id: session, label: 'Listed session', agentKey: agent }],
    post(message: Record<string, unknown>) {
      posted.push(message);
      return Promise.resolve();
    },
    onSendPrompt: async (_agent: string, target: string, cwd: string, prompt: { text: string }) => {
      delivered.push({ session: target, cwd, text: prompt.text });
      return { delivered: true, reason: '', session: target };
    },
  });
  return { provider, host, session, worktree, posted, delivered };
}

