test.each(['claude', 'codex'] as const)(
  'catalog-backed %s submissions stay undelivered when scope readiness changes during persistence',
  async (agent) => {
    for (const mode of ['send', 'queue'] as const) {
      const { provider, host, session, posted, delivered } = catalogSendProvider(agent);
      let release!: () => void;
      const held = new Promise<void>((resolve) => {
        release = resolve;
      });
      let writes = 0;
      provider.memento = { update: () => (++writes === 1 ? held : Promise.resolve()) };
      const text = `${mode} during scope change`;
      let sent: Promise<void> | undefined;
      if (mode === 'queue') {
        provider.queues[session] = queueSubmissionAfter([], 'queued', text, [], [], 1, false, {
          agent,
          owner: session,
        });
        provider.flushQueue(session);
      } else {
        const attempt = { id: `scope-${agent}`, order: 1, source: session, revision: 1, text };
        sent = provider.acceptSubmission(text, session, 1, session, host, attempt);
      }
      await vi.waitFor(() => assert.equal(writes, 1));
      provider.repositoryScopeReady = false;
      release();
      if (mode === 'queue') {
        await vi.waitFor(() => assert.equal(provider.queues[session][0].delivery.phase, 'queued'));
        assert.ok(provider.pendingQueueDrains.has(session));
      } else {
        await sent;
        assert.deepEqual(
          posted.filter((message) => message.type === 'restoreDraft').map((message) => message.text),
          [text],
        );
      }
      assert.deepEqual(delivered, []);
    }
  },
);

