    accept({ delivered: true, reason: '', session: 'source' });
    await vi.waitFor(() => assert.equal(provider.saved.submittedPrompts[0].accepted, true));
    assert.deepEqual(provider.saved.comments, [edited]);
    await provider.writeDrafts();
