    assert.equal(f.messages.length, 2);
    f.acknowledge();
    await vi.advanceTimersByTimeAsync(0);
    assert.equal((await fresh).status, 'applied');
    f.acknowledge(f.messages[0]);
    assert.equal(f.writes.length, 2);
